pivotUI <- pivotUI <- function(df, df_name = paste(deparse(substitute(df)), collapse = " "), rows = NULL, cols = NULL,
  llm_hints = NULL, snapshot_id = NULL) {

  if (is.null(snapshot_id)) {
    uid <- paste0("pv", paste(sample(letters, 8, replace = TRUE), collapse = ""))
  } else {
    uid <- paste0("pv", gsub("[^A-Za-z0-9_]", "", snapshot_id))
  }
  uid  <- paste0("pv", paste(sample(letters, 8, replace = TRUE), collapse = ""))
  wid  <- paste0(uid, "w")
  lid  <- paste0(uid, "l")
  fid  <- paste0(uid, "f")
  converted_date_cols <- names(df)[sapply(df, function(x) inherits(x, c("yearmon", "yearqtr")))]
  date_cols           <- names(df)[sapply(df, function(x) inherits(x, c("Date", "POSIXct", "POSIXlt")))]
  all_date_cols       <- union(date_cols, converted_date_cols)
  date_vars_json      <- as.character(jsonlite::toJSON(all_date_cols))
  converted_vars_json <- as.character(jsonlite::toJSON(converted_date_cols))
  df_json <- df
  for (col in converted_date_cols) {
    x <- as.numeric(df_json[[col]])
    if (inherits(df_json[[col]], "yearqtr")) {
      year <- floor(x); month <- round((x - year) * 4) * 3 + 1
    } else {
      year <- floor(x); month <- round((x - year) * 12) + 1
    }
    df_json[[col]] <- paste(year, sprintf("%02d", month), "01", sep = "-")
  }
  for (col in date_cols) {
    df_json[[col]] <- format(df_json[[col]], "%Y-%m-%d")
  }
  json <- jsonlite::toJSON(df_json, dataframe = "rows", na = "null")

  col_annotations_json <- if (!is.null(llm_hints) && is.list(llm_hints) && length(llm_hints) > 0)
  as.character(jsonlite::toJSON(llm_hints, auto_unbox = TRUE))
  else "{}"

  css <- "
  .pvtTable { border-collapse: collapse; font-family: Arial, sans-serif; font-size: 13px; }
  .pvtTable th, .pvtTable td { border: 1px solid #888; padding: 5px 10px; }
  .pvtColLabel { background-color: #4472C4; color: darkred; font-weight: bold; text-align: center; }
  .pvtRowLabel { background-color: #D9E1F2; color: #1F3864; font-weight: bold; }
  .pvtAxisLabel { background-color: #1F3864; color: green; font-weight: bold; text-align: center; }
  .pvtVal { text-align: right; background-color: #FFFFFF; vertical-align: top; }
  .pvtTotal { background-color: #BDD7EE; font-weight: bold; text-align: right; }
  .pvtTotalLabel { background-color: #BDD7EE; font-weight: bold; }
  .pvtGrandTotal { background-color: #9DC3E6; font-weight: bold; text-align: right; }
  .pvtColLabel { cursor: pointer; }
  .pvtRowLabel { cursor: pointer; }
  .pvtRowLabel:hover { background: #f0f0f0; }
  tbody .pvtTotalLabel:hover { background: #f0f0f0; }
  .pvtColLabel:hover { opacity: 0.85; }
  .pvtTotalLabel { cursor: pointer; }
  .pvtTotalLabel:hover { opacity: 0.85; }

  .sort-arrow { font-size: 10px; margin-left: 3px; vertical-align: middle; }
  .code-panels { display: flex; flex-direction: column; gap: 2px; margin-bottom: 20px; }
  .code-panel { width: 100%; }
  .panel-hdr {
    margin: 0; padding: 8px 12px; color: white;
    font-family: Arial; font-size: 13px; font-weight: bold;
    border-radius: 4px 4px 0 0;
  }
  .wide-hdr { background-color: #4472C4; }
  .long-hdr { background-color: #70AD47; }
  .full-hdr { background-color: #C55A11; }
  .code-box {
    background: #F8F8F8; border: 1px solid #DDD; padding: 12px;
    font-family: 'Courier New', monospace; font-size: 12px;
    white-space: pre; min-height: 110px;
    border-radius: 0 0 4px 4px; line-height: 1.6; color: #333;
  }
  .stat-slots {
    display: flex; flex-direction: column; gap: 4px; align-items: flex-start;
    background: #f0f4ff; border: 1px solid #b0c4f0; padding: 8px 12px;
    border-radius: 4px; font-family: Arial, sans-serif;
  }
  .stat-slots-lbl { font-size: 14px; font-weight: bold; color: #1F3864; margin-right: 4px; }
  .stat-slot { display: flex; align-items: center; gap: 4px; font-size: 14px; color: #1F3864;
    background: #fff; border: 1px solid #c0d0f0; border-radius: 3px; padding: 3px 7px; }
    .stat-slot select { font-size: 14px; border: 1px solid #aaa; border-radius: 2px;
      padding: 1px 3px; background: #fff; color: #333; }
      .stat-slot-sep { color: #999; font-size: 14px; }
      .reorder-btn { cursor: pointer; margin-left: 6px; font-size: 14px; user-select: none; }
      .reorder-btn:hover { opacity: 0.75; }
      .reorder-popup-item {
        padding: 5px 14px; cursor: pointer; white-space: nowrap;
        color: #1F3864 !important; background: #ffffff !important;
      }
      .reorder-popup-item:hover { background: #EEF2FF !important; }
      .reorder-popup-item.rp-active { background: #D9E1F2 !important; font-weight: bold; }
      .rp-section-hdr {
        padding: 4px 10px 3px; font-size: 11px; font-weight: bold;
        color: #555 !important; background: #f0f0f0 !important;
        border-bottom: 1px solid #ddd;
      }
      .rp-input {
        font-size: 12px; padding: 1px 3px; border: 1px solid #aaa;
        border-radius: 2px; margin: 0 2px; color: #333 !important;
        background: #fff !important; vertical-align: baseline;
      }
      .rp-apply { cursor: pointer; color: #4472C4 !important; font-weight: bold; margin-left: 2px; }
      .rp-apply:hover { color: #2a5099 !important; }
      .pvtFilteredAttribute { background-color: #FFCCCC !important; }
      .pvt-num-filtered { font-style: italic !important; background-color: #FFCCCC !important; color: #8B0000 !important; }
      .pv-insert-btn {
        font-size: 12px; padding: 2px 10px; cursor: pointer; font-weight: normal;
        border: 1px solid rgba(255,255,255,0.6); border-radius: 3px;
        background: rgba(255,255,255,0.15); color: white;
      }
      .pv-insert-btn:hover { background: rgba(255,255,255,0.3); }
      .pv-insert-btn:disabled { opacity: 0.55; cursor: default; }
      .pv-btn-ok  { background: rgba(30,180,60,0.55)  !important; }
      .pv-btn-warn{ background: rgba(200,140,0,0.55)  !important; }
      .pv-btn-err { background: rgba(200,50,50,0.55)  !important; }
      .pv-chart-wrap { margin-top: 16px; padding: 12px 16px; border: 1px solid #ddd;
        border-radius: 4px; background: #fafafa; }
        .pv-chart-ctrl { display: flex; align-items: center; gap: 8px; margin-bottom: 10px;
          font-family: Arial; font-size: 13px; color: #333; }
          .pv-chart-ctrl select { font-size: 13px; border: 1px solid #aaa;
            border-radius: 3px; padding: 2px 4px; }
            .ggplot-hdr { background-color: #7B5EA7; }
            .heatmap-gg-hdr { background-color: rosybrown; }
            .reg-hdr { background-color: #1A7891; }
            .pv-reg-vars { display:inline-flex; align-items:center; gap:5px; font-size:12px; color:#333; }
            .pv-reg-vars select { font-size:12px; border:1px solid #aaa; border-radius:3px; padding:1px 4px; max-width:130px; }
            .pv-reg-vars label { white-space:nowrap; }
            .pv-tabs { display:flex; margin-bottom:0; border-bottom:2px solid #4472C4; }
            .pv-tab-btn { padding:7px 22px; cursor:pointer; font-size:13px; font-family:Arial,sans-serif; font-weight:bold;
              border:1px solid #ccc; border-bottom:none; background:#f0f4ff; color:#555;
              border-radius:4px 4px 0 0; margin-right:4px; }
              .pv-tab-btn.active { background:#4472C4; color:white; border-color:#4472C4; }
              .pv-snapshot-bar {
                display: flex;
                justify-content: space-between;
                align-items: center;
                border-bottom: 2px solid #4472C4;
                margin-bottom: 8px;
              }

              .pv-snapshot-actions {
                display: flex;
                gap: 6px;
                align-items: center;
                padding-bottom: 4px;
                flex-wrap: wrap;
              }

              .pv-snapshot-btn {
                font-size: 12px;
                padding: 4px 10px;
                cursor: pointer;
                border: 1px solid #4472C4;
                border-radius: 4px;
                background: #4472C4;
                color: white;
                white-space: nowrap;
              }

              .pv-snapshot-btn:hover {
                background: #2F5597;
              }
              .pv-reg-tab-selectors { display:flex; align-items:center; gap:8px; flex-wrap:wrap;
                padding:10px 14px 10px; font-family:Arial,sans-serif; font-size:13px;
                background:#2F5496; border-radius:4px; margin-bottom:10px; }
                .pv-reg-tab-selectors label { white-space:nowrap; font-weight:bold; color:white; }
                .pv-reg-tab-selectors select { font-size:13px; padding:2px 4px; border:1px solid #aaa; border-radius:3px; min-width:120px; color:#222; background:#fff; }
                .pv-simpson-nudge { font-size:12px; color:#444; font-style:italic;
                  background:#FFF9E6; border:1px solid #F0C040; border-radius:4px;
                  padding:7px 12px; margin:0 0 10px 0; }
                  .pv-facet-grid { display:flex; flex-wrap:wrap; gap:12px; }
                  .pv-facet-panel { flex:1 1 220px; min-width:180px; }
                  .pv-facet-lbl { font-size:12px; font-weight:bold; color:#555; text-align:center; margin-bottom:4px; }
                  .pv-facet-btn { font-size:12px; padding:2px 8px; cursor:pointer; border:1px solid #aaa;
                    border-radius:3px; background:#e8e8e8; color:#333; }
                    .pv-facet-btn.active { background:#4472C4; color:white; border-color:#4472C4; }
                    .pv-freey-lbl { font-size:12px; color:#555; cursor:pointer; }
                    .pv-undoredo { display:inline-flex; align-items:center; gap:4px; margin:4px 0 6px; }
                    .pv-undoredo-btn { font-size:12px; padding:2px 8px; cursor:pointer; border:1px solid #aaa;
                      border-radius:3px; background:#e8e8e8; color:#333; }
                      .pv-undoredo-btn:disabled { opacity:0.38; cursor:default; }
                      .pv-undoredo-lbl { font-size:11px; color:#888; min-width:40px; text-align:center; }
                      .pv-yaxis-wrap { display:flex; align-items:stretch; gap:0; }
                      .pv-yaxis-panel { display:flex; flex-direction:column; align-items:center; padding:4px 4px 4px 2px; gap:2px; width:46px; flex-shrink:0; }
                      .pv-yaxis-lbl { font-size:10px; color:#888; font-family:Arial; text-align:center; min-height:14px; line-height:14px; white-space:nowrap; overflow:hidden; max-width:44px; text-overflow:ellipsis; }
                      input[type=range].pv-yslider { -webkit-appearance:slider-vertical; writing-mode:vertical-lr; direction:rtl; width:22px; height:140px; flex:none; padding:0; margin:0; cursor:pointer; }
                      .pv-yaxis-auto { font-size:10px; padding:2px 4px; cursor:pointer; border:1px solid #aaa; border-radius:3px; background:#e8e8e8; color:#333; margin-top:4px; white-space:nowrap; }
                      .pv-yaxis-auto:hover { background:#d0d0d0; }
                      .wider-opts-bar {
                        display:flex; align-items:center; gap:6px; flex-wrap:wrap;
                        padding:5px 10px; margin-bottom:8px;
                        background:#f0f4ff; border:1px solid #b0c4f0;
                        border-radius:4px; font-family:Arial; font-size:12px;
                        color:#1F3864; font-weight:normal;
                      }
                      .wider-opts-bar * { font-weight:normal !important; }
                      .wider-opts-lbl { margin-right:2px; white-space:nowrap; }
                      .wider-opts-sep { color:#bbb; }
                      .wider-opts-bar label { display:flex; align-items:center; gap:3px; cursor:pointer; white-space:nowrap; }
                      .wider-opts-bar input[type=text] {
                        font-size:12px; padding:2px 4px; border:1px solid #aaa;
                        border-radius:2px; background:#fff; color:#333; vertical-align:middle;
                      }
                      .pv-longform-btn {
                        font-size:12px; padding:2px 8px; cursor:pointer; border:1px solid #4472C4;
                        border-radius:3px; background:#e8eff8; color:#1F3864;
                      }
                      .pv-longform-btn:hover { background:#c8d8f0; }
                      .pv-longform-popup {
                        position:fixed; z-index:10000; background:#fff; border:1px solid #4472C4;
                        border-radius:6px; box-shadow:0 4px 18px rgba(0,0,0,0.28);
                        min-width:340px; max-width:640px; display:flex; flex-direction:column;
                      }
                      .pv-longform-popup-hdr {
                        background:#5B9BD5; color:#fff; padding:6px 10px; font-size:13px;
                        font-family:Arial; font-weight:bold; border-radius:5px 5px 0 0;
                        cursor:move; display:flex; justify-content:space-between; align-items:center;
                        user-select:none; -webkit-user-select:none;
                      }
                      .pv-longform-popup-body {
                        overflow:auto; padding:6px 8px; max-height:360px;
                      }
                      .pv-longform-close-btn {
                        background:none; border:none; color:#fff; font-size:17px; line-height:1;
                        cursor:pointer; padding:0 2px; margin-left:10px;
                      }
                      .pv-longform-close-btn:hover { color:#ffe066; }
                      .pv-binscat-lbl { font-size:12px; color:#555; cursor:pointer; }
                      .pv-numbinscat-lbl { font-size:12px; color:#555; cursor:pointer; }
                      .pv-boxplot-lbl { font-size:12px; color:#555; cursor:pointer; }
                      .pv-boxplot-note { font-size:12px; color:#888; font-style:italic; text-align:center; padding:20px 0; margin:0; }
                      .pv-bin-section { margin-top:10px; padding:10px 14px; border:1px solid #c8d4e8;
                        border-radius:4px; background:#f4f7ff; font-family:Arial; font-size:13px; }
                        .pv-bin-hdr { font-weight:bold; color:#1F3864; margin-bottom:8px; }
                        .pv-bin-row { display:flex; align-items:center; flex-wrap:wrap; gap:6px;
                          margin-bottom:6px; padding:6px 10px; background:#fff;
                          border:1px solid #dde3f0; border-radius:3px; }
                          .pv-bin-row select, .pv-bin-row input[type=number], .pv-bin-row input[type=text] {
                            font-size:12px; padding:2px 4px; border:1px solid #aaa; border-radius:3px;
                            background:#fff; color:#333; }
                            .pv-bin-badge { font-size:11px; padding:2px 8px; border-radius:10px;
                              background:#4472C4; color:#fff; font-weight:bold;
                              display:inline-block; min-width:110px; text-align:center;
                              white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
                              .pv-bin-apply { font-size:12px; padding:2px 9px; cursor:pointer;
                                border:1px solid #4472C4; border-radius:3px; background:#4472C4; color:#fff; }
                                .pv-bin-apply:hover { background:#2a5099; border-color:#2a5099; }
                                .pv-bin-remove { font-size:12px; padding:2px 9px; cursor:pointer;
                                  border:1px solid #c55; border-radius:3px; background:#fff; color:#c55; }
                                  .pv-bin-remove:hover { background:#fee; }
                                  .stat-and-vars-bar { display:flex; align-items:stretch; gap:12px; }
                                  .stat-slots-col { display:flex; flex-direction:column; gap:8px; flex-shrink:0; }
                                  .pv-var-matrix { flex:1; display:flex; flex-wrap:wrap; align-content:flex-start;
                                    gap:4px; padding:6px 8px; background:#f4f7ff; border:1px solid #c8d4e8;
                                    border-radius:4px; overflow-y:auto; min-height:60px; }
                                    .pv-renderer-slot { display:flex; align-items:center;
                                      padding:6px 12px; background:#f0f4ff; border:1px solid #b0c4f0;
                                      border-radius:4px; gap:6px; white-space:nowrap; font-family:Arial; }
                                      .pv-renderer-slot > span { font-size:13px; font-weight:bold; color:#1F3864; }
                                      .pv-renderer-slot select { font-size:13px; border:1px solid #aaa;
                                        border-radius:3px; padding:2px 4px; background:#fff; color:#333; }
                                        .pv-attr-panel-hdr { font-size:11px; font-weight:bold; color:#1F3864;
                                          padding:3px 2px 5px; border-bottom:1px solid #c8d4e8; margin-bottom:4px;
                                          letter-spacing:0.5px; text-transform:uppercase;
                                          flex-basis:100%; flex-shrink:0; }
                                          .pvtUnused .pvtAttr { display:inline-flex !important; align-items:center !important;
                                            margin:0 !important; background:#dce8f8; color:#1F3864;
                                            border:1px solid #b0c8e8; border-radius:3px; white-space:nowrap; }
                                            .pvtFilterBox { background:#fff !important; color:#1F3864 !important;
                                              border:1px solid #999 !important; box-shadow:2px 4px 12px rgba(0,0,0,0.3) !important;
                                              border-radius:4px !important; font-size:13px !important; font-family:Arial,sans-serif !important; }
                                              .pvtFilterBox h4 { background:#1F3864 !important; color:#fff !important;
                                                padding:6px 12px !important; margin:0 0 8px !important;
                                                border-radius:4px 4px 0 0 !important; font-size:13px !important; font-weight:bold !important; }
                                                .pvtFilterBox input { background:#fff !important; color:#333 !important; border:1px solid #ccc; }
                                                .pvtFilterBox label { color:#1F3864 !important; font-size:13px !important; }
                                                .pv-role-dot { display:inline-block; width:7px; height:7px; border-radius:50%;
                                                  margin-right:5px; flex-shrink:0; vertical-align:middle; }
                                                  .pv-col-tip { display:none; position:fixed; z-index:9999; max-width:260px;
                                                    padding:5px 9px; background:#1F3864; color:#fff; font-size:12px;
                                                    line-height:1.5; border-radius:4px; pointer-events:none;
                                                    box-shadow:2px 3px 8px rgba(0,0,0,0.35); }
                                                    "

                                                    js_tmpl <- "$(function() {
                                                        var data = window['__UID__pvdata'];
                                                        var dfName = '__DFNAME__';
                                                        var colAnnotations = __COL_ANNOTATIONS__;
                                                        var BS = '\\\\';  // single backslash -- used to emit R's \\(x) lambda syntax

                                                        // -- Aggregator definitions ------------------------------------------------
                                                        var AGG_FNS = {
                                                          'Count':        function(v) { return v.length; },
                                                          'Sum':          function(v) { return v.reduce(function(a,b){return a+b;},0); },
                                                          'Mean':         function(v) { return v.reduce(function(a,b){return a+b;},0)/v.length; },
                                                          'Median':       function(v) {
                                                            var s=v.slice().sort(function(a,b){return a-b;}),m=Math.floor(s.length/2);
                                                            return s.length%2?s[m]:(s[m-1]+s[m])/2;
                                                          },
                                                          'SD': function(v) {
                                                            if(v.length<2)return NaN;
                                                            var n=v.length,mu=v.reduce(function(a,b){return a+b;},0)/n;
                                                            return Math.sqrt(v.reduce(function(s,x){return s+(x-mu)*(x-mu);},0)/(n-1));
                                                          },
                                                          'Min':          function(v) { return Math.min.apply(null,v); },
                                                          'Max':          function(v) { return Math.max.apply(null,v); },
                                                          'Count Unique': function(v) { var s={}; v.forEach(function(x){s[x]=1;}); return Object.keys(s).length; },
                                                          'NA Ratio':     function(v) { return v.reduce(function(a,b){return a+b;},0)/v.length; },
                                                          'Variation Ratio': function(v) {
                                                            var c={}; v.forEach(function(x){c[x]=(c[x]||0)+1;});
                                                            return 1 - Math.max.apply(null, Object.keys(c).map(function(k){return c[k];}))/v.length;
                                                          },
                                                          'Entropy': function(v) {
                                                            var c={}, n=v.length;
                                                            v.forEach(function(x){c[x]=(c[x]||0)+1;});
                                                            return -Object.keys(c).reduce(function(s,k){ var p=c[k]/n; return s+p*Math.log2(p); }, 0);
                                                          }
                                                        };
                                                        var AGG_R_TIDY = {
                                                          'Count':        'n()',
                                                          'Sum':          'sum(VAR, na.rm = TRUE)',
                                                          'Mean':         'mean(VAR, na.rm = TRUE)',
                                                          'Median':       'median(VAR, na.rm = TRUE)',
                                                          'SD':           'sd(VAR, na.rm = TRUE)',
                                                          'Min':          'min(VAR, na.rm = TRUE)',
                                                          'Max':          'max(VAR, na.rm = TRUE)',
                                                          'Count Unique':    'n_distinct(VAR)',
                                                          'NA Ratio':        'mean(is.na(VAR))',
                                                          'Variation Ratio': '1 - max(prop.table(table(VAR[!is.na(VAR)])))',
                                                          'Entropy':         '(function(v){p<-prop.table(table(v[!is.na(v)]));-sum(p*log2(p))})(VAR)'
                                                        };
                                                        var ALL_AGGS = ['Count','Sum','Mean','Median','SD','Min','Max','Count Unique','NA Ratio','Variation Ratio','Entropy'];
                                                        var ALL_VARS = data.length ? Object.keys(data[0]) : [];

                                                        // -- Stat slots ------------------------------------------------------------
                                                        var numVars        = ALL_VARS.filter(function(v){ return data.length && typeof data[0][v]==='number'; });
                                                        var DATE_VARS      = __DATE_VARS__;
                                                        var CONVERTED_VARS = __CONVERTED_VARS__;
                                                        function isDateVar(v) { return DATE_VARS.indexOf(v) !== -1; }
                                                        var CAT_UNIQUE_THRESH = 15; // variables with <= this many unique values are treated as categorical
                                                        var uniqueCounts = {};
                                                        ALL_VARS.forEach(function(v) {
                                                            var s = {};
                                                            data.forEach(function(r) { if (r[v] != null) s[String(r[v])] = 1; });
                                                            uniqueCounts[v] = Object.keys(s).length;
                                                          });
                                                          var catVars = ALL_VARS.filter(function(v) {
                                                              return (data.length && typeof data[0][v] !== 'number') || uniqueCounts[v] <= CAT_UNIQUE_THRESH;
                                                            });
                                                            var statSlots = [
                                                              { varName: '', aggName: 'Count' },
                                                              { varName: '', aggName: 'Mean'  },
                                                              { varName: '', aggName: 'SD'    }
                                                            ];

                                                            function activeSlots() {
                                                              return statSlots.filter(function(s) { return s.aggName==='Count' || s.varName; });
                                                            }
                                                            function slotName(slot) {
                                                              if (slot.aggName==='Count') return 'n';
                                                              return slot.aggName.toLowerCase().replace(/ /g,'_') + '_' + slot.varName;
                                                            }

                                                            // -- Other state ----------------------------------------------------------
                                                            var sortState         = { colIdx: -1, dir: 1, colLabel: null };
                                                            var rowSortState      = { rowIdx: -1, dir: 1 };
                                                            var reorderState      = { mode: 'original', param: '' };
                                                            var transformState    = { mode: 'none',     param: '' };
                                                            var lastCfg           = null;
                                                            var widerOpts         = { namesSort: false, valuesFill: '', namesGlue: '', valuesFn: false };
                                                            var pristineTbodyHTML = null;
                                                            var chartInstances   = [];
                                                            var chartStatIdx     = 0;
                                                            var chartFacet       = false;
                                                            var chartFreeY       = false;
                                                            var chartRowFacet    = false;
                                                            var stateHistory     = [];
                                                            var historyIdx       = -1;
                                                            var _historyMuted    = false;
                                                            var rawData           = data.slice();
                                                            var workData          = data.slice();
                                                            var binConfigs        = {};
                                                            var binscatterMode    = false;
                                                            var numBinscatterMode = false;
                                                            var boxplotMode       = false;
                                                            var regGroupVar       = '';
                                                            var regXVar           = '';
                                                            var regYVar           = '';
                                                            var activeTab         = 'pivot';
                                                            var regChartInstances = [];
                                                            var horizontal        = false;
                                                            var yAxisMin          = null;
                                                            var yAxisMax          = null;
                                                            var _restoreSortState    = null;
                                                            var _restoreRowSortState = null;

                                                            function rColName(s) {
                                                              if (/^[a-zA-Z.][a-zA-Z0-9._]*$/.test(s)) return s;
                                                              return '`' + s + '`';
                                                            }
                                                            function dq(s)    { return '\"' + s + '\"'; }
                                                            function dqArr(a) { return a.map(dq).join(', '); }

                                                            function buildPivotWider(cols, vFrom) {
                                                              var args = [];
                                                              if (widerOpts.namesGlue && cols.length > 1) {
                                                                args.push('names_glue  = ' + dq(widerOpts.namesGlue));
                                                              } else {
                                                                args.push('names_from  = ' + (cols.length===1 ? cols[0] : 'c('+cols.join(', ')+')'));
                                                              }
                                                              args.push('values_from = ' + vFrom);
                                                              if (widerOpts.namesSort)         args.push('names_sort  = TRUE');
                                                              if (widerOpts.valuesFill !== '') args.push('values_fill = ' + widerOpts.valuesFill);
                                                              return '  pivot_wider(\\n' + args.map(function(a){return '    '+a;}).join(',\\n') + '\\n  )';
                                                            }

                                                            function buildValuesFnCode(rows, cols, cfg) {
                                                              var slots = activeSlots();
                                                              if (!slots.length) return null;
                                                              var hasCount = slots.some(function(s){ return s.aggName==='Count'; });
                                                              var uAggs = []; slots.forEach(function(s){ if(uAggs.indexOf(s.aggName)===-1) uAggs.push(s.aggName); });
                                                              if (hasCount || uAggs.length > 1) {
                                                                var reason = hasCount ? 'Count — n() has no values_fn equivalent' :
                                                                'multiple aggregation functions ('+uAggs.join(', ')+') detected';
                                                                return '# values_fn is not applicable here: '+reason+'.\\n' +
                                                                '# Use the group_by() + summarise() + pivot_wider() approach instead.';
                                                              }
                                                              var agg = uAggs[0];
                                                              var lambda = '~' + AGG_R_TIDY[agg].replace(/\\bVAR\\b/g, '.x');
                                                              var uVars = []; slots.forEach(function(s){ if(uVars.indexOf(s.varName)===-1) uVars.push(s.varName); });
                                                              var vFrom = uVars.length===1 ? rColName(uVars[0]) : 'c('+uVars.map(rColName).join(', ')+')';
                                                              cfg = cfg || lastCfg;
                                                              var numFLines=getNumericFilterCode(cfg,true), catFLines=getCategoricalFilterCode(cfg,true);
                                                              var filterSteps=numFLines.concat(catFLines).map(function(l){return '  '+l+' |>\\n';}).join('');
                                                              var binSteps=allBinMutateSteps();
                                                              var hasTransform=transformState.mode!=='none'&&rows.length>0;
                                                              var hasReorder  =reorderState.mode!=='original'&&rows.length>0;
                                                              var transformStep=hasTransform?'  '+getReorderMutate(transformState.mode,rows[0],transformState.param)+' |>\\n':'';
                                                              var reorderStep  =hasReorder  ?'  '+getReorderMutate(reorderState.mode,  rows[0],reorderState.param  )+' |>\\n':'';
                                                              var pwArgs = [];
                                                              if (rows.length>0) pwArgs.push('id_cols     = '+(rows.length===1?rows[0]:'c('+rows.join(', ')+')'));
                                                              if (widerOpts.namesGlue && cols.length>1) {
                                                                pwArgs.push('names_glue  = '+dq(widerOpts.namesGlue));
                                                              } else {
                                                                pwArgs.push('names_from  = '+(cols.length===1?cols[0]:'c('+cols.join(', ')+')'));
                                                              }
                                                              pwArgs.push('values_from = '+vFrom);
                                                              pwArgs.push('values_fn   = '+lambda);
                                                              if (widerOpts.namesSort)         pwArgs.push('names_sort  = TRUE');
                                                              if (widerOpts.valuesFill !== '') pwArgs.push('values_fill = '+widerOpts.valuesFill);
                                                              return dfName+' |>\\n'+filterSteps+binSteps+transformStep+reorderStep+
                                                              '  pivot_wider(\\n'+pwArgs.map(function(a){return '    '+a;}).join(',\\n')+'\\n  )';
                                                            }

                                                            function computeLongData(rows, cols) {
                                                              var slots=activeSlots(), allGrp=rows.concat(cols);
                                                              if (!slots.length||!allGrp.length) return [];
                                                              var groups={}, order=[];
                                                              var _inc=(lastCfg&&lastCfg.inclusions)||{};
                                                              var _exc=(lastCfg&&lastCfg.exclusions)||{};
                                                              var _fd=computeFilteredData().filter(function(row){
                                                                  return Object.keys(_inc).every(function(v){return !_inc[v]||!_inc[v].length||_inc[v].indexOf(String(row[v]))!==-1;})&&
                                                                  Object.keys(_exc).every(function(v){return !_exc[v]||!_exc[v].length||_exc[v].indexOf(String(row[v]))===-1;});
                                                                });
                                                                _fd.forEach(function(d){
                                                                    var key=allGrp.map(function(v){return String(d[v]!=null?d[v]:'(NA)');}).join('\\x00');
                                                                    if(!groups[key]){ var g={}; allGrp.forEach(function(v){g[v]=d[v];}); g._rows=[]; groups[key]=g; order.push(key); }
                                                                    groups[key]._rows.push(d);
                                                                  });
                                                                  var result=[];
                                                                  order.forEach(function(key){
                                                                      var g=groups[key], row={};
                                                                      allGrp.forEach(function(v){row[v]=g[v];});
                                                                      slots.forEach(function(s){
                                                                          var name=slotName(s);
                                                                          if(s.aggName==='Count'){ row[name]=g._rows.length; }
                                                                          else {
                                                                            var vals=g._rows.map(function(d){return +d[s.varName];}).filter(function(x){return !isNaN(x);});
                                                                            row[name]=vals.length?AGG_FNS[s.aggName](vals):null;
                                                                          }
                                                                        });
                                                                        result.push(row);
                                                                      });
                                                                      return result;
                                                                    }

                                                                    function buildLongFormTable(data, headers) {
                                                                      if(!data.length) return '<p style=\"color:#888;font-style:italic;padding:8px\">No data.</p>';
                                                                      var MAX=200, shown=data.length>MAX, rows=data.slice(0,MAX);
                                                                      var fmt=function(v){
                                                                        if(v==null) return '<span style=\"color:#aaa\">NA</span>';
                                                                        if(typeof v==='number') return isNaN(v)?'<span style=\"color:#aaa\">NaN</span>':(+v.toFixed(4)).toString();
                                                                        return String(v);
                                                                      };
                                                                      return '<div style=\"overflow-x:auto;max-height:280px;overflow-y:auto;\">'+
                                                                      '<table style=\"border-collapse:collapse;font-size:12px;font-family:\\'Courier New\\',monospace;white-space:nowrap;\">'+
                                                                      '<thead><tr>'+headers.map(function(h){
                                                                          return '<th style=\"background:#5B9BD5;color:#fff;padding:4px 8px;border:1px solid #ccc;position:sticky;top:0\">'+h+'</th>';
                                                                        }).join('')+'</tr></thead><tbody>'+
                                                                        rows.map(function(r,i){
                                                                            return '<tr style=\"background:'+(i%2?'#f4f8ff':'#fff')+'\">'+
                                                                            headers.map(function(h){ return '<td style=\"padding:3px 8px;border:1px solid #e0e0e0;color:#333\">'+fmt(r[h])+'</td>'; }).join('')+'</tr>';
                                                                          }).join('')+'</tbody></table></div>'+
                                                                          (shown?'<p style=\"font-size:11px;color:#888;margin:3px 0 0\">Showing first '+MAX+' of '+data.length+' rows.</p>':'');
                                                                        }

                                                                        function _refreshLongForm(cfg) {
                                                                          try {
                                                                            var rows=cfg.rows||[], cols=cfg.cols||[], slots=activeSlots(), allGrp=rows.concat(cols);
                                                                            if(!slots.length||!allGrp.length){
                                                                              $('#__UID__-longform-popup').hide();
                                                                              $('#__UID__-longform-btn').text('\\u21c5 Show long form'); return false;
                                                                            }
                                                                            var data=computeLongData(rows,cols);
                                                                            var hdrs=allGrp.concat(slots.map(slotName));
                                                                            $('#__UID__-longform-popup-title').text(
                                                                              'Long form — group_by('+allGrp.join(', ')+') |> summarise()  ['+data.length+' rows]');
                                                                              $('#__UID__-longform-popup-body').html(buildLongFormTable(data,hdrs));
                                                                              return true;
                                                                            } catch(e) {
                                                                              $('#__UID__-longform-popup-body').html(
                                                                                '<p style=\"color:#c00;padding:8px;font-family:monospace;font-size:12px\">Long form error: '+String(e)+'</p>');
                                                                                return true;
                                                                              }
                                                                            }

                                                                            // ── Binning infrastructure ─────────────────────────────────────────────
                                                                            function fmtB(x) { return Math.round(x * 1000) / 1000; }
                                                                            function isBinVar(v) { return binConfigs.hasOwnProperty(v); }
                                                                            function nextBinColName(src) {
                                                                              if (!binConfigs.hasOwnProperty(src + '_bins')) return src + '_bins';
                                                                              var i = 2;
                                                                              while (binConfigs.hasOwnProperty(src + '_bins' + i)) i++;
                                                                              return src + '_bins' + i;
                                                                            }
                                                                            function applyBreaks(val, breaks) {
                                                                              if (val == null || isNaN(+val)) return '(NA)';
                                                                              var n = breaks.length;
                                                                              for (var i = 1; i < n; i++) {
                                                                                if (+val <= breaks[i]) return '[' + fmtB(breaks[i-1]) + ', ' + fmtB(breaks[i]) + (i === n-1 ? ']' : ')');
                                                                              }
                                                                              return '[' + fmtB(breaks[n-2]) + ', ' + fmtB(breaks[n-1]) + ']';
                                                                            }
                                                                            function parseBinMidpoint(label) {
                                                                              var ci = label.indexOf(',');
                                                                              if (ci < 0) return NaN;
                                                                              var lo = parseFloat(label.slice(1, ci));
                                                                              var hi = parseFloat(label.slice(ci + 1));
                                                                              return isNaN(lo) || isNaN(hi) ? NaN : (lo + hi) / 2;
                                                                            }
                                                                            function getRawScatterPts(xVar, yVar, filterFn) {
                                                                              return rawData.filter(function(d) {
                                                                                  return d[xVar] != null && !isNaN(+d[xVar]) && d[yVar] != null && !isNaN(+d[yVar]) &&
                                                                                  (!filterFn || filterFn(d));
                                                                                }).map(function(d) { return { x: +d[xVar], y: +d[yVar] }; });
                                                                              }
                                                                              function rebuildWorkData() {
                                                                                var bv = Object.keys(binConfigs);
                                                                                if (!bv.length) { workData = rawData.slice(); return; }
                                                                                workData = rawData.map(function(row) {
                                                                                    var nr = Object.assign({}, row);
                                                                                    bv.forEach(function(outCol) {
                                                                                        var cfg = binConfigs[outCol];
                                                                                        if (cfg && cfg.breaks && cfg.breaks.length >= 2) nr[outCol] = applyBreaks(row[cfg.source], cfg.breaks);
                                                                                      });
                                                                                      return nr;
                                                                                    });
                                                                                  }
                                                                                  function getNumVals(v) {
                                                                                    return rawData.map(function(d){ return d[v]; }).filter(function(x){ return x != null && !isNaN(+x); }).map(Number);
                                                                                  }
                                                                                  function equalWidthBreaks(vals, n) {
                                                                                    var mn = Math.min.apply(null, vals), mx = Math.max.apply(null, vals);
                                                                                    if (mn === mx) return [mn - 0.5, mx + 0.5];
                                                                                    var br = [mn]; for (var i = 1; i <= n; i++) br.push(mn + i * (mx - mn) / n); return br;
                                                                                  }
                                                                                  function equalFreqBreaks(vals, n) {
                                                                                    var sv = vals.slice().sort(function(a,b){return a-b;}), br = [sv[0]];
                                                                                    for (var i = 1; i < n; i++) {
                                                                                      var idx = Math.round(i * sv.length / n);
                                                                                      var v2 = sv[Math.max(0, Math.min(idx, sv.length - 1))];
                                                                                      if (v2 > br[br.length-1]) br.push(v2);
                                                                                    }
                                                                                    if (sv[sv.length-1] > br[br.length-1]) br.push(sv[sv.length-1]); return br;
                                                                                  }
                                                                                  function sdBreaks(vals, n) {
                                                                                    var mu = vals.reduce(function(a,b){return a+b;}, 0) / vals.length;
                                                                                    var sd = Math.sqrt(vals.reduce(function(s,x){return s+(x-mu)*(x-mu);}, 0) / Math.max(1, vals.length-1));
                                                                                    var mn = Math.min.apply(null, vals), mx = Math.max.apply(null, vals), half = Math.ceil(n/2), br = [mn];
                                                                                    for (var k = -half; k <= half; k++) { var b = mu + k * sd; if (b > br[br.length-1] && b < mx) br.push(b); }
                                                                                    if (mx > br[br.length-1]) br.push(mx); return br;
                                                                                  }
                                                                                  function domainBreaks(vals, str) {
                                                                                    var mn = Math.min.apply(null, vals), mx = Math.max.apply(null, vals);
                                                                                    var pts = str.split(',').map(function(s){ return parseFloat(s.trim()); }).filter(function(x){ return !isNaN(x); });
                                                                                    var br = [mn].concat(pts.filter(function(b){ return b > mn && b < mx; })).concat([mx]);
                                                                                    br.sort(function(a,b){return a-b;}); return br.filter(function(b,i,arr){ return i===0||b>arr[i-1]; });
                                                                                  }
                                                                                  function jenksBreaks(vals, n) {
                                                                                    var sv = vals.slice().sort(function(a,b){return a-b;}), m = sv.length;
                                                                                    n = Math.min(n, m-1); if (n <= 1) return [sv[0], sv[m-1]];
                                                                                    var lo = [], va = [];
                                                                                    for (var i = 0; i < m; i++) {
                                                                                      lo.push([]); va.push([]);
                                                                                      for (var j = 0; j <= n; j++) { lo[i].push(1); va[i].push(i===0 ? 0 : Infinity); }
                                                                                    }
                                                                                    for (var i = 1; i < m; i++) {
                                                                                      var s1=0, s2=0, w=0;
                                                                                      for (var p = i; p >= 0; p--) {
                                                                                        w++; s1 += sv[p]; s2 += sv[p]*sv[p]; var v2 = s2 - s1*s1/w;
                                                                                        if (p > 0) { for (var j = 2; j <= n; j++) { if (va[i][j] >= v2 + va[p-1][j-1]) { va[i][j] = v2 + va[p-1][j-1]; lo[i][j] = p; } } }
                                                                                      }
                                                                                      lo[i][1] = 1; va[i][1] = s2 - s1*s1/w;
                                                                                    }
                                                                                    var classes = [], kk = n, id = m-1;
                                                                                    while (kk >= 1) { classes.push(lo[id][kk]); id = lo[id][kk] - 1; kk--; }
                                                                                    classes.sort(function(a,b){return a-b;});
                                                                                    var br = [sv[0]].concat(classes.map(function(ci){ return sv[Math.max(0, ci-1)]; })).concat([sv[m-1]]);
                                                                                    return br.filter(function(b,i,arr){ return i===0||b>arr[i-1]; });
                                                                                  }
                                                                                  // MDLP (Fayyad & Irani 1993): strict=true removes the depth cap, letting MDL alone decide
                                                                                  function entropyBreaks(vals, targetVar, strict) {
                                                                                    var tvals = rawData.map(function(d){ return String(d[targetVar] == null ? '(NA)' : d[targetVar]); });
                                                                                    var m = vals.length, idx = []; for (var i = 0; i < m; i++) idx.push(i);
                                                                                    idx.sort(function(a,b){ return vals[a]-vals[b]; });
                                                                                    var sv = idx.map(function(i){ return vals[i]; }), st = idx.map(function(i){ return tvals[i]; });
                                                                                    function cnt(lo,hi){ var c={}; for(var i=lo;i<hi;i++) c[st[i]]=(c[st[i]]||0)+1; return c; }
                                                                                    function ent(lo,hi){ var n=hi-lo,c=cnt(lo,hi),e=0; Object.keys(c).forEach(function(k){var p=c[k]/n;if(p>0)e-=p*Math.log(p)/Math.LN2;}); return e; }
                                                                                    function nCl(lo,hi){ return Object.keys(cnt(lo,hi)).length; }
                                                                                    var splits = [];
                                                                                    function trySplit(lo,hi,depth){
                                                                                      if(!strict && depth>=8) return;
                                                                                      if(hi-lo<4) return;
                                                                                      var t=hi-lo,pe=ent(lo,hi),best=-Infinity,bp=-1;
                                                                                      for(var k=lo+1;k<hi-1;k++){if(sv[k]===sv[k-1])continue;var g=pe-(k-lo)/t*ent(lo,k)-(hi-k)/t*ent(k,hi);if(g>best){best=g;bp=k;}}
                                                                                      if(bp<0) return;
                                                                                      var kc=nCl(lo,hi),k1=nCl(lo,bp),k2=nCl(bp,hi);
                                                                                      var mdl=(Math.log(t-1)/Math.LN2+Math.log(Math.pow(3,kc)-2)/Math.LN2-kc*pe+k1*ent(lo,bp)+k2*ent(bp,hi))/t;
                                                                                      if(best<=mdl) return;
                                                                                      splits.push(sv[bp]); trySplit(lo,bp,depth+1); trySplit(bp,hi,depth+1);
                                                                                    }
                                                                                    trySplit(0, m, 0);
                                                                                    splits.sort(function(a,b){return a-b;});
                                                                                    return [sv[0]].concat(splits).concat([sv[m-1]]).filter(function(b,i,arr){return i===0||b>arr[i-1];});
                                                                                  }
                                                                                  // Logarithmic equal-width breaks (equally spaced on log10 scale)
                                                                                  function logEqualWidthBreaks(vals, n) {
                                                                                    // Remove non-positive values (log undefined)
                                                                                    var posVals = vals.filter(function(x) { return x > 0; });
                                                                                    if (posVals.length === 0) return [0, 1]; // fallback
                                                                                    var logMin = Math.log10(Math.min.apply(null, posVals));
                                                                                    var logMax = Math.log10(Math.max.apply(null, posVals));
                                                                                    if (logMin === logMax) return [Math.pow(10, logMin - 0.5), Math.pow(10, logMax + 0.5)];
                                                                                    var br = [];
                                                                                    for (var i = 0; i <= n; i++) {
                                                                                      var logVal = logMin + i * (logMax - logMin) / n;
                                                                                      br.push(Math.pow(10, logVal));
                                                                                    }
                                                                                    // Ensure monotonic and capture original min/max (including non-positive)
                                                                                    var mn = Math.min.apply(null, vals);
                                                                                    var mx = Math.max.apply(null, vals);
                                                                                    if (br[0] > mn) br.unshift(mn);
                                                                                    if (br[br.length-1] < mx) br.push(mx);
                                                                                    // Remove duplicates and sort
                                                                                    br = br.filter(function(v,i,a){ return i===0 || v > a[i-1]; });
                                                                                    return br;
                                                                                  }

                                                                                  // CART: recursive Gini-impurity minimization
                                                                                  function cartBreaks(vals, targetVar, maxBins) {
                                                                                    maxBins = maxBins || 5;
                                                                                    var tvals = rawData.map(function(d){ return String(d[targetVar] == null ? '(NA)' : d[targetVar]); });
                                                                                    var m = vals.length, idx = []; for (var i = 0; i < m; i++) idx.push(i);
                                                                                    idx.sort(function(a,b){ return vals[a]-vals[b]; });
                                                                                    var sv = idx.map(function(i){ return vals[i]; }), st = idx.map(function(i){ return tvals[i]; });
                                                                                    function gini(lo,hi){ var n=hi-lo,c={}; for(var i=lo;i<hi;i++) c[st[i]]=(c[st[i]]||0)+1; var g=1; Object.keys(c).forEach(function(k){var p=c[k]/n;g-=p*p;}); return g; }
                                                                                    var splits=[];
                                                                                    function trySplit(lo,hi,depth){
                                                                                      if(depth>=maxBins-1||hi-lo<4) return;
                                                                                      var t=hi-lo,pg=gini(lo,hi),best=-Infinity,bp=-1;
                                                                                      for(var k=lo+1;k<hi;k++){
                                                                                        if(sv[k]===sv[k-1]) continue;
                                                                                        var gain=pg-(k-lo)/t*gini(lo,k)-(hi-k)/t*gini(k,hi);
                                                                                        if(gain>best){best=gain;bp=k;}
                                                                                      }
                                                                                      if(bp<0||best<=0) return;
                                                                                      splits.push(sv[bp]); trySplit(lo,bp,depth+1); trySplit(bp,hi,depth+1);
                                                                                    }
                                                                                    trySplit(0,m,0);
                                                                                    splits.sort(function(a,b){return a-b;});
                                                                                    return [sv[0]].concat(splits).concat([sv[m-1]]).filter(function(b,i,arr){return i===0||b>arr[i-1];});
                                                                                  }
                                                                                  // CART-R: recursive variance-reduction splitting for numeric targets
                                                                                  function cartRBreaks(vals, targetVar, maxBins) {
                                                                                    maxBins = maxBins || 5;
                                                                                    var tvals = rawData.map(function(d){ return +d[targetVar]; });
                                                                                    var m = vals.length, idx = []; for (var i = 0; i < m; i++) idx.push(i);
                                                                                    idx.sort(function(a,b){ return vals[a]-vals[b]; });
                                                                                    var sv = idx.map(function(i){ return vals[i]; }), st = idx.map(function(i){ return tvals[i]; });
                                                                                    function variance(lo,hi){
                                                                                      var n=hi-lo,sum=0,sum2=0;
                                                                                      for(var i=lo;i<hi;i++){sum+=st[i];sum2+=st[i]*st[i];}
                                                                                      return n>1 ? sum2/n-(sum/n)*(sum/n) : 0;
                                                                                    }
                                                                                    var splits=[];
                                                                                    function trySplit(lo,hi,depth){
                                                                                      if(depth>=maxBins-1||hi-lo<4) return;
                                                                                      var t=hi-lo,pv=variance(lo,hi),best=-Infinity,bp=-1;
                                                                                      for(var k=lo+1;k<hi;k++){
                                                                                        if(sv[k]===sv[k-1]) continue;
                                                                                        var gain=pv-(k-lo)/t*variance(lo,k)-(hi-k)/t*variance(k,hi);
                                                                                        if(gain>best){best=gain;bp=k;}
                                                                                      }
                                                                                      if(bp<0||best<=0) return;
                                                                                      splits.push(sv[bp]); trySplit(lo,bp,depth+1); trySplit(bp,hi,depth+1);
                                                                                    }
                                                                                    trySplit(0,m,0);
                                                                                    splits.sort(function(a,b){return a-b;});
                                                                                    return [sv[0]].concat(splits).concat([sv[m-1]]).filter(function(b,i,arr){return i===0||b>arr[i-1];});
                                                                                  }
                                                                                  // Chi-Merge (Kerber 1992): bottom-up merging by chi-square homogeneity
                                                                                  function chiMergeBreaks(vals, targetVar, maxBins) {
                                                                                    maxBins = maxBins || 6;
                                                                                    var tvals = rawData.map(function(d){ return String(d[targetVar] == null ? '(NA)' : d[targetVar]); });
                                                                                    var pairs=[];
                                                                                    for(var i=0;i<vals.length;i++) if(vals[i]!=null&&!isNaN(vals[i])) pairs.push({val:vals[i],cls:tvals[i]});
                                                                                    pairs.sort(function(a,b){return a.val-b.val;});
                                                                                    var bins=[];
                                                                                    pairs.forEach(function(p){
                                                                                        if(!bins.length||bins[bins.length-1].val!==p.val) bins.push({val:p.val,counts:{}});
                                                                                        var b=bins[bins.length-1]; b.counts[p.cls]=(b.counts[p.cls]||0)+1;
                                                                                      });
                                                                                      function chi2(b1,b2){
                                                                                        var allCls={};
                                                                                        Object.keys(b1.counts).forEach(function(c){allCls[c]=true;});
                                                                                        Object.keys(b2.counts).forEach(function(c){allCls[c]=true;});
                                                                                        var n1=Object.keys(b1.counts).reduce(function(s,c){return s+b1.counts[c];},0);
                                                                                        var n2=Object.keys(b2.counts).reduce(function(s,c){return s+b2.counts[c];},0);
                                                                                        var N=n1+n2,x2=0;
                                                                                        Object.keys(allCls).forEach(function(c){
                                                                                            var r1=b1.counts[c]||0,r2=b2.counts[c]||0,col=r1+r2; if(!col) return;
                                                                                            var e1=n1*col/N,e2=n2*col/N;
                                                                                            if(e1>0) x2+=(r1-e1)*(r1-e1)/e1;
                                                                                            if(e2>0) x2+=(r2-e2)*(r2-e2)/e2;
                                                                                          });
                                                                                          return x2;
                                                                                        }
                                                                                        while(bins.length>Math.max(maxBins,2)){
                                                                                          var minX2=Infinity,minIdx=0;
                                                                                          for(var i=0;i<bins.length-1;i++){var x=chi2(bins[i],bins[i+1]);if(x<minX2){minX2=x;minIdx=i;}}
                                                                                          var merged={val:bins[minIdx].val,counts:{}};
                                                                                          [bins[minIdx],bins[minIdx+1]].forEach(function(b){Object.keys(b.counts).forEach(function(c){merged.counts[c]=(merged.counts[c]||0)+b.counts[c];});});
                                                                                          bins.splice(minIdx,2,merged);
                                                                                        }
                                                                                        var br=[pairs[0].val].concat(bins.slice(1).map(function(b){return b.val;})).concat([pairs[pairs.length-1].val]);
                                                                                        return br.filter(function(b,i,arr){return i===0||b>arr[i-1];});
                                                                                      }
                                                                                      // CAIM (Kurgan & Cios 2004): greedy forward search maximising CAIM criterion
                                                                                      function caimBreaks(vals, targetVar, maxBins) {
                                                                                        maxBins = maxBins || 6;
                                                                                        var tvals = rawData.map(function(d){ return String(d[targetVar] == null ? '(NA)' : d[targetVar]); });
                                                                                        var pairs=[];
                                                                                        for(var i=0;i<vals.length;i++) if(vals[i]!=null&&!isNaN(vals[i])) pairs.push({val:vals[i],cls:tvals[i]});
                                                                                        pairs.sort(function(a,b){return a.val-b.val;});
                                                                                        var n=pairs.length;
                                                                                        var cuts=[];
                                                                                        for(var i=1;i<n;i++) if(pairs[i].val!==pairs[i-1].val) cuts.push((pairs[i].val+pairs[i-1].val)/2);
                                                                                        function caimScore(bps){
                                                                                          var r=bps.length-1,score=0;
                                                                                          for(var i=0;i<r;i++){
                                                                                            var lo=bps[i],hi=bps[i+1],cnt={};
                                                                                            pairs.forEach(function(p){ if(p.val>=lo&&p.val<=hi) cnt[p.cls]=(cnt[p.cls]||0)+1; });
                                                                                            var ni=Object.keys(cnt).reduce(function(s,c){return s+cnt[c];},0);
                                                                                            if(!ni) continue;
                                                                                            var maxq=Math.max.apply(null,Object.keys(cnt).map(function(c){return cnt[c];}));
                                                                                            score+=maxq*maxq/ni;
                                                                                          }
                                                                                          return score/r;
                                                                                        }
                                                                                        var mn=pairs[0].val,mx=pairs[n-1].val,bps=[mn,mx],prev=caimScore(bps);
                                                                                        while(bps.length-1<maxBins&&cuts.length){
                                                                                          var bestSc=-Infinity,bestCut=null;
                                                                                          cuts.forEach(function(c){
                                                                                              if(bps.indexOf(c)>=0) return;
                                                                                              var nb=bps.concat([c]).sort(function(a,b){return a-b;}),sc=caimScore(nb);
                                                                                              if(sc>bestSc){bestSc=sc;bestCut=c;}
                                                                                            });
                                                                                            if(bestCut===null||bestSc<=prev) break;
                                                                                            bps.push(bestCut); bps.sort(function(a,b){return a-b;}); prev=bestSc;
                                                                                          }
                                                                                          return bps.filter(function(b,i,arr){return i===0||b>arr[i-1];});
                                                                                        }
                                                                                        // CACC (Tsai et al. 2008): greedy forward search maximising contingency-coefficient criterion
                                                                                        function caccBreaks(vals, targetVar, maxBins) {
                                                                                          maxBins = maxBins || 6;
                                                                                          var tvals = rawData.map(function(d){ return String(d[targetVar] == null ? '(NA)' : d[targetVar]); });
                                                                                          var pairs=[];
                                                                                          for(var i=0;i<vals.length;i++) if(vals[i]!=null&&!isNaN(vals[i])) pairs.push({val:vals[i],cls:tvals[i]});
                                                                                          pairs.sort(function(a,b){return a.val-b.val;});
                                                                                          var n=pairs.length,allCls={};
                                                                                          pairs.forEach(function(p){allCls[p.cls]=true;});
                                                                                          var k=Object.keys(allCls).length;
                                                                                          var cuts=[];
                                                                                          for(var i=1;i<n;i++) if(pairs[i].val!==pairs[i-1].val) cuts.push((pairs[i].val+pairs[i-1].val)/2);
                                                                                          function caccScore(bps){
                                                                                            var r=bps.length-1,x2=0,colSums={},table=[],rowSums=[];
                                                                                            for(var i=0;i<r;i++){
                                                                                              var lo=bps[i],hi=bps[i+1],cnt={};
                                                                                              pairs.forEach(function(p){ if(p.val>=lo&&p.val<=hi) cnt[p.cls]=(cnt[p.cls]||0)+1; });
                                                                                              table.push(cnt);
                                                                                              var ni=Object.keys(cnt).reduce(function(s,c){return s+cnt[c];},0);
                                                                                              rowSums.push(ni);
                                                                                              Object.keys(cnt).forEach(function(c){colSums[c]=(colSums[c]||0)+cnt[c];});
                                                                                            }
                                                                                            for(var i=0;i<r;i++){
                                                                                              Object.keys(colSums).forEach(function(c){
                                                                                                  var obs=table[i][c]||0,exp=rowSums[i]*colSums[c]/n;
                                                                                                  if(exp>0) x2+=(obs-exp)*(obs-exp)/exp;
                                                                                                });
                                                                                              }
                                                                                              var minDim=Math.min(r,k)-1; if(minDim<=0) return 0;
                                                                                              return Math.sqrt(x2/(n*minDim));
                                                                                            }
                                                                                            var mn=pairs[0].val,mx=pairs[n-1].val,bps=[mn,mx],prev=caccScore(bps);
                                                                                            while(bps.length-1<maxBins&&cuts.length){
                                                                                              var bestSc=-Infinity,bestCut=null;
                                                                                              cuts.forEach(function(c){
                                                                                                  if(bps.indexOf(c)>=0) return;
                                                                                                  var nb=bps.concat([c]).sort(function(a,b){return a-b;}),sc=caccScore(nb);
                                                                                                  if(sc>bestSc){bestSc=sc;bestCut=c;}
                                                                                                });
                                                                                                if(bestCut===null||bestSc<=prev) break;
                                                                                                bps.push(bestCut); bps.sort(function(a,b){return a-b;}); prev=bestSc;
                                                                                              }
                                                                                              return bps.filter(function(b,i,arr){return i===0||b>arr[i-1];});
                                                                                            }
                                                                                            // Best-KS supervised binning (maximizes KS statistic between bins)
                                                                                            function bestKSBreaks(vals, targetVar, maxBins) {
                                                                                              maxBins = maxBins || 5;
                                                                                              // target values: binary 0/1 (bad/good) or any two distinct values?
                                                                                              // We treat the target variable as categorical; we need its two levels.
                                                                                              // Here we assume target is binary (0/1 or yes/no). If multiclass, we binarize by the most frequent? For simplicity, require binary.
                                                                                              var tgtSet = {};
                                                                                              workData.forEach(function(row){ var t = row[targetVar]; if (t != null) tgtSet[t] = true; });
                                                                                              var tgtLevels = Object.keys(tgtSet);
                                                                                              if (tgtLevels.length !== 2) {
                                                                                                console.warn('Best-KS requires binary target variable. Using equal-frequency as fallback.');
                                                                                                return equalFreqBreaks(vals, maxBins);
                                                                                              }
                                                                                              // Map target values to 0/1 for KS calculation
                                                                                              var level0 = tgtLevels[0];
                                                                                              var level1 = tgtLevels[1];
                                                                                              // Pair value and target
                                                                                              var pairs = [];
                                                                                              for (var i = 0; i < vals.length; i++) {
                                                                                                var v = vals[i];
                                                                                                var t = workData[i][targetVar];
                                                                                                if (t == null || isNaN(v)) continue;
                                                                                                var tBin = (t === level1) ? 1 : 0; // we consider level1 as 'event'
                                                                                                pairs.push({val: v, target: tBin});
                                                                                              }
                                                                                              if (pairs.length === 0) return [vals[0], vals[vals.length-1]];
                                                                                              pairs.sort(function(a,b){ return a.val - b.val; });
                                                                                              var totalPos = pairs.reduce(function(s,p){ return s + p.target; }, 0);
                                                                                              var totalNeg = pairs.length - totalPos;
                                                                                              if (totalPos === 0 || totalNeg === 0) return [pairs[0].val, pairs[pairs.length-1].val];

                                                                                              // Recursive split: find cut that maximizes KS, then split left and right
                                                                                              function ksCut(start, end) {
                                                                                                if (end - start <= 1) return null;
                                                                                                var bestKS = -1, bestIdx = -1;
                                                                                                var leftPos = 0, leftNeg = 0;
                                                                                                for (var i = start; i < end-1; i++) {
                                                                                                  if (pairs[i].target === 1) leftPos++;
                                                                                                  else leftNeg++;
                                                                                                  var rightPos = totalPos - leftPos;
                                                                                                  var rightNeg = totalNeg - leftNeg;
                                                                                                  var leftRate = leftPos / (leftPos + leftNeg);
                                                                                                  var rightRate = rightPos / (rightPos + rightNeg);
                                                                                                  var ks = Math.abs(leftRate - rightRate);
                                                                                                  if (ks > bestKS) {
                                                                                                    bestKS = ks;
                                                                                                    bestIdx = i;
                                                                                                  }
                                                                                                }
                                                                                                if (bestIdx === -1) return null;
                                                                                                var cutVal = (pairs[bestIdx].val + pairs[bestIdx+1].val) / 2;
                                                                                                return {cut: cutVal, leftStart: start, leftEnd: bestIdx+1, rightStart: bestIdx+1, rightEnd: end, ks: bestKS};
                                                                                              }

                                                                                              var splits = [];
                                                                                              function recursiveSplit(start, end, depth) {
                                                                                                if (depth >= maxBins-1) return;
                                                                                                var cutInfo = ksCut(start, end);
                                                                                                if (!cutInfo) return;
                                                                                                splits.push(cutInfo.cut);
                                                                                                recursiveSplit(cutInfo.leftStart, cutInfo.leftEnd, depth+1);
                                                                                                recursiveSplit(cutInfo.rightStart, cutInfo.rightEnd, depth+1);
                                                                                              }
                                                                                              recursiveSplit(0, pairs.length, 0);
                                                                                              splits.sort(function(a,b){ return a-b; });
                                                                                              var br = [pairs[0].val];
                                                                                              splits.forEach(function(s){ br.push(s); });
                                                                                              br.push(pairs[pairs.length-1].val);
                                                                                              // Remove duplicates and ensure monotonic
                                                                                              br = br.filter(function(v,i,a){ return i===0 || v > a[i-1]; });
                                                                                              return br;
                                                                                            }

                                                                                            function getBinMutateCode(outCol, cfg) {
                                                                                              var rv = rColName(cfg.source), bn = rColName(outCol);
                                                                                              var br = cfg.breaks.map(function(b){ return fmtB(b); }).join(', ');
                                                                                              return 'mutate(' + bn + ' = cut(' + rv + ', breaks = c(' + br + '), include.lowest = TRUE))';
                                                                                            }
                                                                                            function allBinMutateSteps() {
                                                                                              if (!lastCfg) return '';
                                                                                              var used = Object.keys(binConfigs).filter(function(outCol) {
                                                                                                  return (lastCfg.rows||[]).concat(lastCfg.cols||[]).indexOf(outCol) !== -1;
                                                                                                });
                                                                                                return used.map(function(outCol){ return '  ' + getBinMutateCode(outCol, binConfigs[outCol]) + ' |>\\n'; }).join('');
                                                                                              }
                                                                                              function updateBinSection() {
                                                                                                var $sec = $('#__UID__-bin-section');
                                                                                                var numV = Object.keys(numericVars).filter(function(v){ return uniqueCounts[v] > CAT_UNIQUE_THRESH; });
                                                                                                if (!numV.length) { $sec.hide(); return; }
                                                                                                $sec.show().empty();
                                                                                                $sec.append('<div class=\"pv-bin-hdr\">Binning Numeric Variables <span style=\"font-weight:normal;font-size:11px;color:#888;\">  (adds <em>var</em>_bins column to field list)</span></div>');
                                                                                                var methodLabels = { equal_width:'Equal-width', equal_freq:'Equal-freq', log_equal_width:'Log Equal-width',
                                                                                                  sd:'Std-dev breaks', domain:'Domain breaks', jenks:'Natural breaks (Jenks)', entropy:'MDLP/Entropy (supervised)',
                                                                                                  cart:'CART (supervised)', cart_r:'CART-R (regression)', chi_merge:'Chi-Merge (supervised)',
                                                                                                  caim:'CAIM (supervised)', cacc:'CACC (supervised)', best_ks:'Best-KS (supervised)' };
                                                                                                  numV.forEach(function(v) {
                                                                                                      // -- Applied bin rows for this source variable --
                                                                                                      var existingBins = Object.keys(binConfigs)
                                                                                                      .filter(function(outCol){ return binConfigs[outCol].source === v; })
                                                                                                      .sort();
                                                                                                      existingBins.forEach(function(outCol) {
                                                                                                          var cfg = binConfigs[outCol];
                                                                                                          var $row = $('<div class=\"pv-bin-row\"></div>');
                                                                                                          $row.append('<span class=\"pv-bin-badge\" style=\"background:#5a9a6f;color:#fff;\">' + outCol + '</span>');
                                                                                                          $row.append('<span style=\"font-size:11px;color:#555;margin-right:4px;\">' + (methodLabels[cfg.method]||cfg.method) + '</span>');
                                                                                                          var $rm = $('<button class=\"pv-bin-remove\">Remove</button>');
                                                                                                          (function(oc) {
                                                                                                              $rm.on('click', function() {
                                                                                                                  delete binConfigs[oc];
                                                                                                                  rebuildWorkData(); refreshRegGroupDropdown();
                                                                                                                  reinitPivot();
                                                                                                                  setTimeout(function() { saveStateToHash(); }, 100);
                                                                                                                });
                                                                                                              })(outCol);
                                                                                                              $row.append($rm);
                                                                                                              var brStr = cfg.breaks.map(fmtB).join(', ');
                                                                                                              $row.append($('<span style=\"font-size:10px;color:#888;margin-left:4px;\">breaks:[' + brStr + ']</span>'));
                                                                                                              $sec.append($row);
                                                                                                            });
                                                                                                            // -- Fresh setup row for next bin of this variable --
                                                                                                            (function(srcV) {
                                                                                                                var $row = $('<div class=\"pv-bin-row\"></div>');
                                                                                                                $row.append('<span class=\"pv-bin-badge\">' + srcV + '</span>');
                                                                                                                var $msel = $('<select style=\"font-size:12px;width:213px;\">');
                                                                                                                [['equal_width','Equal-width'],
                                                                                                                  ['equal_freq','Equal-freq'],
                                                                                                                  ['log_equal_width','Log Equal-width'],
                                                                                                                  ['sd','Std-dev breaks'],
                                                                                                                  ['domain','Domain breaks'],
                                                                                                                  ['jenks','Natural breaks (Jenks)'],
                                                                                                                  ['entropy','MDLP/Entropy (supervised)'],
                                                                                                                  ['cart','CART (supervised)'],
                                                                                                                  ['cart_r','CART-R (regression)'],
                                                                                                                  ['chi_merge','Chi-Merge (supervised)'],
                                                                                                                  ['caim','CAIM (supervised)'],
                                                                                                                  ['cacc','CACC (supervised)'],
                                                                                                                  ['best_ks','Best-KS (supervised)']
                                                                                                                ].forEach(function(m){ $msel.append($('<option>').val(m[0]).text(m[1])); });
                                                                                                                $row.append($msel);
                                                                                                                var $parea = $('<span style=\"display:inline-flex;align-items:center;gap:4px;\">');
                                                                                                                function buildParam(method) {
                                                                                                                  $parea.empty();
                                                                                                                  var catV = ALL_VARS.filter(function(r){ return r !== srcV && !isBinVar(r) && catVars.indexOf(r) !== -1; });
                                                                                                                  if (method === 'domain') {
                                                                                                                    $parea.append($('<input type=\"text\" class=\"rp-input\" placeholder=\"e.g. 1,5,10\" style=\"width:100px;\">'));
                                                                                                                  } else if (method === 'entropy') {
