                                                                                                                    $tsel.append($('<option>').val('').text('— target —'));
                                                                                                                    catV.forEach(function(r){ $tsel.append($('<option>').val(r).text(r)); });
                                                                                                                    var $strict = $('<input type=\"checkbox\" title=\"Strict MDLP: let MDL criterion alone decide (no depth cap)\" style=\"margin-left:4px;\">');
                                                                                                                    $parea.append($('<span style=\"font-size:11px;\">target:</span>'), $tsel,
                                                                                                                      $('<span style=\"font-size:11px;margin-left:6px;\">strict:</span>'), $strict);
                                                                                                                    } else if (method === 'cart_r') {
