                                                                                                                          catV.forEach(function(r){ $tsel.append($('<option>').val(r).text(r)); });
                                                                                                                          $parea.append($('<span style=\"font-size:11px;\">target:</span>'), $tsel);
                                                                                                                        } else if (method === 'log_equal_width') {
                                                                                                                          $parea.append($('<span style=\"font-size:11px;\">n=</span>'),
                                                                                                                            $('<input type=\"number\" class=\"rp-input\" min=\"2\" max=\"20\" style=\"width:45px;\">').val(5));
                                                                                                                          } else if (method === 'best_ks') {
                                                                                                                            var binaryTargets = ALL_VARS.filter(function(r) {
                                                                                                                                if (r === srcV) return false;
                                                                                                                                var uq = {};
                                                                                                                                data.forEach(function(d){ if (d[r] != null) uq[d[r]] = true; });
                                                                                                                                return Object.keys(uq).length === 2;
                                                                                                                              });
                                                                                                                              var $tsel = $('<select style=\"font-size:12px;\">');
                                                                                                                              $tsel.append($('<option>').val('').text('— target (binary) —'));
                                                                                                                              binaryTargets.forEach(function(r){ $tsel.append($('<option>').val(r).text(r)); });
                                                                                                                              $parea.append($('<span style=\"font-size:11px;\">target:</span>'), $tsel,
                                                                                                                                $('<span style=\"margin-left:6px;font-size:11px;\">max bins:</span>'),
                                                                                                                                $('<input type=\"number\" class=\"rp-input\" min=\"2\" max=\"10\" style=\"width:45px;\">').val(5));
                                                                                                                              } else {
                                                                                                                                $parea.append($('<span style=\"font-size:11px;\">n=</span>'), $('<input type=\"number\" class=\"rp-input\" min=\"2\" max=\"20\" style=\"width:45px;\">').val(5));
                                                                                                                              }
                                                                                                                            }
                                                                                                                            buildParam($msel.val());
                                                                                                                            $msel.on('change', function(){ buildParam($(this).val()); });
                                                                                                                            $row.append($parea);
                                                                                                                            var $apply = $('<button class=\"pv-bin-apply\">Apply</button>');
                                                                                                                            $apply.on('click', function() {
                                                                                                                                var method = $msel.val(), vals = getNumVals(srcV); if (!vals.length) return;
                                                                                                                                var breaks, param, strict = false;
                                                                                                                                if (method === 'equal_width') { var n=parseInt($parea.find('input').val())||5; breaks=equalWidthBreaks(vals,n); param=n; }
                                                                                                                                else if (method === 'equal_freq') { var n=parseInt($parea.find('input').val())||5; breaks=equalFreqBreaks(vals,n); param=n; }
                                                                                                                                else if (method === 'sd') { var n=parseInt($parea.find('input').val())||3; breaks=sdBreaks(vals,n); param=n; }
                                                                                                                                else if (method === 'domain') { var str=$parea.find('input').val(); breaks=domainBreaks(vals,str); param=str; }
                                                                                                                                else if (method === 'jenks') { var n=parseInt($parea.find('input').val())||5; breaks=jenksBreaks(vals,n); param=n; }
                                                                                                                                else if (method === 'entropy') {
                                                                                                                                  var tgt=$parea.find('select').val(); if(!tgt) return;
                                                                                                                                  strict=$parea.find('input[type=\"checkbox\"]').prop('checked');
                                                                                                                                  breaks=entropyBreaks(vals,tgt,strict); param=tgt;
