                                                                                                                                  var n=parseInt($parea.find('input[type=\"number\"]').val())||5; breaks=cartBreaks(vals,tgt,n); param=tgt;
                                                                                                                                }
                                                                                                                                else if (method === 'cart_r') {
                                                                                                                                  var tgt=$parea.find('select').val(); if(!tgt){ alert('Please select a numeric target variable for CART-R binning.'); return; }
                                                                                                                                  var n=parseInt($parea.find('input[type=\"number\"]').val())||5; breaks=cartRBreaks(vals,tgt,n); param=tgt;
                                                                                                                                }
                                                                                                                                else if (method === 'chi_merge') {
                                                                                                                                  var tgt=$parea.find('select').val(); if(!tgt){ alert('Please select a target variable for Chi-Merge binning.'); return; }
                                                                                                                                  var n=parseInt($parea.find('input[type=\"number\"]').val())||6; breaks=chiMergeBreaks(vals,tgt,n); param=tgt;
                                                                                                                                }
                                                                                                                                else if (method === 'caim') {
                                                                                                                                  var tgt=$parea.find('select').val(); if(!tgt){ alert('Please select a target variable for CAIM binning.'); return; }
                                                                                                                                  breaks=caimBreaks(vals,tgt,20); param=tgt;
                                                                                                                                }
                                                                                                                                else if (method === 'cacc') {
                                                                                                                                  var tgt=$parea.find('select').val(); if(!tgt){ alert('Please select a target variable for CACC binning.'); return; }
                                                                                                                                  breaks=caccBreaks(vals,tgt,20); param=tgt;
                                                                                                                                }
                                                                                                                                else if (method === 'log_equal_width') {
                                                                                                                                  var n = parseInt($parea.find('input[type=\"number\"]').val()) || 5;
                                                                                                                                  breaks = logEqualWidthBreaks(vals, n); param = n;
                                                                                                                                }
                                                                                                                                else if (method === 'best_ks') {
                                                                                                                                  var tgt = $parea.find('select').first().val();
                                                                                                                                  if (!tgt) { alert('Please select a binary target variable for Best-KS binning.'); return; }
                                                                                                                                  var maxBins = parseInt($parea.find('input[type=\"number\"]').val()) || 5;
                                                                                                                                  breaks = bestKSBreaks(vals, tgt, maxBins); param = tgt;
                                                                                                                                }
                                                                                                                                if (!breaks || breaks.length < 2) return;
                                                                                                                                var outCol = nextBinColName(srcV);
                                                                                                                                binConfigs[outCol] = { source: srcV, method: method, n: typeof param==='number'?param:5, param: param, strict: strict, breaks: breaks };
                                                                                                                                rebuildWorkData(); refreshRegGroupDropdown(); reinitPivot();
                                                                                                                              });
                                                                                                                              $row.append($apply);
                                                                                                                              $sec.append($row);
                                                                                                                            })(v);
                                                                                                                          });
                                                                                                                        }

                                                                                                                        // 更新 View 下拉框：删除无用的 Table Barchart，并为 heatmap 项添加说明
                                                                                                                        // Update View dropdown: remove Table Barchart and add note to Heatmap options
                                                                                                                        function updateRendererOptions() {
                                                                                                                          var $select = $('#__UID__-renderer').find('select.pvtRenderer');
                                                                                                                          if (!$select.length) return;
                                                                                                                          // Remove Table Barchart option
                                                                                                                          $select.find('option').each(function() {
                                                                                                                              if ($(this).text() === 'Table Barchart') {
                                                                                                                                $(this).remove();
                                                                                                                              }
                                                                                                                            });
                                                                                                                            // Add note to heatmap options (count only)
                                                                                                                            $select.find('option').each(function() {
                                                                                                                                var text = $(this).text();
                                                                                                                                if (text === 'Heatmap') {
                                                                                                                                  $(this).text('Heatmap (count only)');
                                                                                                                                } else if (text === 'Row Heatmap') {
                                                                                                                                  $(this).text('Row Heatmap (count only)');
                                                                                                                                } else if (text === 'Col Heatmap') {
                                                                                                                                  $(this).text('Col Heatmap (count only)');
                                                                                                                                }
                                                                                                                              });
                                                                                                                            }

                                                                                                                            function repositionUnused() {
                                                                                                                              var $pv = $('#__UID__');
                                                                                                                              var $pvtTable = $pv.find('table.pvtUi').first();
                                                                                                                              if (!$pvtTable.length) return;

                                                                                                                              if (!$('#__UID__-pv-scope').length) {
                                                                                                                                $('head').append('<style id=\"__UID__-pv-scope\">' +
                                                                                                                                  '#__UID__ td.pvtCols {' +
                                                                                                                                    ' min-height:90px !important; padding:15px 8px !important;' +
                                                                                                                                    ' vertical-align:middle !important; }' +
                                                                                                                                    '#__UID__ td.pvtRows {' +
                                                                                                                                      ' min-width:200px !important; padding:8px 15px !important; }' +
                                                                                                                                      '</style>');
                                                                                                                                    }

                                                                                                                                    var $unused = $pvtTable.find('td.pvtUnused').first();
                                                                                                                                    if (!$unused.length) return;

                                                                                                                                    $unused.removeClass('pvtHorizList pvtVertList');
                                                                                                                                    $unused.css({
                                                                                                                                        display: 'flex', flexWrap: 'wrap', alignContent: 'flex-start',
                                                                                                                                        gap: '1px', width: '100%', height: '100%',
                                                                                                                                        background: 'transparent', border: 'none',
                                                                                                                                        padding: '0', boxSizing: 'border-box', margin: '0'
                                                                                                                                      });

                                                                                                                                      if (!$unused.find('.pv-attr-panel-hdr').length) {
                                                                                                                                        $unused.prepend($('<div class=\"stat-slots-lbl\" style=\"flex-basis:100%;flex-shrink:0;\">Fields:</div>'));
                                                                                                                                      }

                                                                                                                                      var $rsel = $pvtTable.find('select.pvtRenderer').first();
                                                                                                                                      var $slot = $('#__UID__-renderer');
                                                                                                                                      if ($rsel.length && $slot.length) {
                                                                                                                                        var $rendTd = $rsel.closest('td');
                                                                                                                                        $slot.empty().append($('<span>View:</span>')).append($rsel.detach());
                                                                                                                                        $rendTd.hide();
                                                                                                                                      }

                                                                                                                                      $pvtTable.find('td.pvtVals').hide();
                                                                                                                                      $pvtTable.find('td.pvtCols').attr('colspan', 2);

                                                                                                                                      var $varMatrix = $('#__UID__-varmatrix');
                                                                                                                                      if ($varMatrix.length) {
                                                                                                                                        $varMatrix.empty().append($unused.detach());
                                                                                                                                      }
                                                                                                                                    }

                                                                                                                                    function quoteKeep(p) {
                                                                                                                                      return p.replace(/[\"']/g,'').split(',')
                                                                                                                                      .map(function(s){var t=s.trim();return t?'\"'+t+'\"':''})
                                                                                                                                      .filter(Boolean).join(', ');
                                                                                                                                    }

                                                                                                                                    // -- Aggregation engine ----------------------------------------------------
                                                                                                                                    function buildGroups(fd, rowVars, colVars, slots) {
                                                                                                                                      var groups = {};
                                                                                                                                      var hasRows = rowVars.length > 0, hasCols = colVars.length > 0;
                                                                                                                                      function pushRow(rk, ck, row) {
                                                                                                                                        if (!groups[rk]) groups[rk] = {};
                                                                                                                                        if (!groups[rk][ck]) groups[rk][ck] = slots.map(function(){return [];});
                                                                                                                                        slots.forEach(function(slot,i) {
                                                                                                                                            if (slot.aggName==='Count') {
                                                                                                                                              groups[rk][ck][i].push(1);
                                                                                                                                            } else if (slot.aggName==='NA Ratio' && slot.varName) {
                                                                                                                                              var x = row[slot.varName];
                                                                                                                                              groups[rk][ck][i].push((x==null||(typeof x==='number'&&isNaN(x)))?1:0);
                                                                                                                                            } else if (['Count Unique','Variation Ratio','Entropy'].indexOf(slot.aggName)!==-1 && slot.varName) {
                                                                                                                                              var x = row[slot.varName];
                                                                                                                                              if (x!=null && !(typeof x==='number' && isNaN(x))) groups[rk][ck][i].push(String(x));
                                                                                                                                            } else if (slot.varName) {
                                                                                                                                              var x = row[slot.varName];
                                                                                                                                              if (x!=null && !isNaN(+x)) groups[rk][ck][i].push(+x);
                                                                                                                                            }
                                                                                                                                          });
                                                                                                                                        }
                                                                                                                                        fd.forEach(function(row) {
                                                                                                                                            var rk = hasRows
                                                                                                                                            ? rowVars.map(function(v){return row[v]==null?'(NA)':String(row[v]);}).join('||')
                                                                                                                                            : '__ALL__';
                                                                                                                                            var ck = hasCols
                                                                                                                                            ? colVars.map(function(v){return row[v]==null?'(NA)':String(row[v]);}).join('||')
                                                                                                                                            : '__ALL__';
                                                                                                                                            pushRow(rk, ck, row);
                                                                                                                                            if (hasRows && hasCols) {
                                                                                                                                              pushRow(rk, '__ALL__', row);        // row marginal total
                                                                                                                                              pushRow('__ALL__', ck, row);        // col marginal total
                                                                                                                                              pushRow('__ALL__', '__ALL__', row); // grand total
                                                                                                                                            } else if (rk !== '__ALL__' || ck !== '__ALL__') {
                                                                                                                                              pushRow('__ALL__', '__ALL__', row); // grand total for single-dimension case
                                                                                                                                            }
                                                                                                                                          });
                                                                                                                                          return groups;
                                                                                                                                        }

                                                                                                                                        function applyAgg(vals, aggName) {
                                                                                                                                          if (!vals.length) return null;
                                                                                                                                          var fn = AGG_FNS[aggName];
                                                                                                                                          if (!fn) return vals.length;
                                                                                                                                          var v = fn(vals);
                                                                                                                                          return (v==null||isNaN(v)) ? null : v;
                                                                                                                                        }

                                                                                                                                        function fmtVal(x) {
                                                                                                                                          if (x===null||x===undefined) return '';
                                                                                                                                          if (x===Math.floor(x)) return String(x);
                                                                                                                                          return (Math.round(x*1000)/1000).toString();
                                                                                                                                        }

                                                                                                                                        // -- Extract column group keys from rendered table header -----------------
                                                                                                                                        function extractColKeys($table) {
                                                                                                                                          var cols = (lastCfg&&lastCfg.cols)||[], rows = (lastCfg&&lastCfg.rows)||[];
                                                                                                                                          if (!cols.length) return ['__ALL__'];
                                                                                                                                          var $hRows = $table.find('thead tr');
                                                                                                                                          var nR = $hRows.length;
                                                                                                                                          var grid = [];
                                                                                                                                          for (var i=0;i<nR;i++) grid.push([]);
                                                                                                                                          $hRows.each(function(ri) {
                                                                                                                                              var ci=0;
                                                                                                                                              $(this).find('th').each(function() {
                                                                                                                                                  while(grid[ri][ci]) ci++;
                                                                                                                                                  var rs=parseInt($(this).attr('rowspan')||1);
                                                                                                                                                  var cs=parseInt($(this).attr('colspan')||1);
                                                                                                                                                  var cls=$(this).attr('class')||'';
                                                                                                                                                  var txt=$(this).clone().children().remove().end().text().trim();
                                                                                                                                                  for(var r=ri;r<Math.min(ri+rs,nR);r++)
                                                                                                                                                  for(var c=ci;c<ci+cs;c++) { if(!grid[r]) grid[r]=[]; if(!grid[r][c]) grid[r][c]={text:txt,cls:cls}; }
                                                                                                                                                  ci+=cs;
                                                                                                                                                });
                                                                                                                                              });
                                                                                                                                              var bottom = grid[nR-1]||[], colKeys=[];
                                                                                                                                              for (var ci=rows.length;ci<bottom.length;ci++) {
                                                                                                                                                var cell=bottom[ci];
                                                                                                                                                if(!cell||cell.cls.indexOf('pvtTotalLabel')!==-1) continue;
                                                                                                                                                if(cell.cls.indexOf('pvtColLabel')===-1) continue;
                                                                                                                                                var parts=[];
                                                                                                                                                for(var ri=0;ri<nR;ri++) { var c=grid[ri][ci]; if(c&&c.cls.indexOf('pvtColLabel')!==-1&&(!parts.length||parts[parts.length-1]!==c.text)) parts.push(c.text); }
                                                                                                                                                colKeys.push(parts.join('||'));
                                                                                                                                              }
                                                                                                                                              return colKeys;
                                                                                                                                            }

                                                                                                                                            // -- Replace PivotTable.js cell values with multi-stat results ------------
                                                                                                                                            // Relabel rowVar in data to match DOM labels produced by lump/collapse transforms
                                                                                                                                            function transformDataRows(fd, rowVar, transformState) {
                                                                                                                                              var mode=transformState.mode, p=transformState.param||'';
                                                                                                                                              if(mode==='none') return fd;
                                                                                                                                              var counts={};
                                                                                                                                              fd.forEach(function(row){var v=row[rowVar]==null?'(NA)':String(row[rowVar]);counts[v]=(counts[v]||0)+1;});
                                                                                                                                              var allLevels=Object.keys(counts), total=fd.length, relabelMap={};
                                                                                                                                              if(mode==='lump_n'){
                                                                                                                                                var n=parseInt(p,10);if(isNaN(n)||n<0)n=3;
                                                                                                                                                allLevels.slice().sort(function(a,b){return counts[b]-counts[a];}).slice(n).forEach(function(k){relabelMap[k]='Other';});
                                                                                                                                              } else if(mode==='lump_min'){
                                                                                                                                                var mn=parseFloat(p);if(isNaN(mn))mn=10;
                                                                                                                                                allLevels.forEach(function(k){if(counts[k]<mn)relabelMap[k]='Other';});
                                                                                                                                              } else if(mode==='lump_prop'){
                                                                                                                                                var prop=parseFloat(p);if(isNaN(prop)||prop<=0)prop=0.1;
                                                                                                                                                allLevels.forEach(function(k){if(!total||counts[k]/total<prop)relabelMap[k]='Other';});
                                                                                                                                              } else if(mode==='lowfreq'){
                                                                                                                                                var sortedAsc=allLevels.slice().sort(function(a,b){return counts[a]-counts[b];});
                                                                                                                                                var acc=0;
                                                                                                                                                for(var i=0;i<sortedAsc.length-1;i++){
                                                                                                                                                  var newAcc=acc+counts[sortedAsc[i]];
                                                                                                                                                  if(newAcc<counts[sortedAsc[i+1]]){relabelMap[sortedAsc[i]]='Other';acc=newAcc;}else break;
                                                                                                                                                }
                                                                                                                                              } else if(mode==='other'){
                                                                                                                                                var keepSet={};
                                                                                                                                                p.replace(/[\"']/g,'').split(',').forEach(function(s){var t=s.trim();if(t)keepSet[t]=true;});
                                                                                                                                                allLevels.forEach(function(k){if(!keepSet[k])relabelMap[k]='Other';});
                                                                                                                                              } else if(mode==='collapse'){
                                                                                                                                                var reC=/(\\w+)\\s*=\\s*c\\s*\\(([^)]+)\\)/g,mC;
                                                                                                                                                while((mC=reC.exec(p))!==null){var newName=mC[1].trim();mC[2].replace(/[\"']/g,'').split(',').forEach(function(s){var t=s.trim();if(t)relabelMap[t]=newName;});}
                                                                                                                                              }
                                                                                                                                              if(!Object.keys(relabelMap).length) return fd;
                                                                                                                                              return fd.map(function(row){
                                                                                                                                                  var v=row[rowVar]==null?'(NA)':String(row[rowVar]);
                                                                                                                                                  if(!relabelMap[v]) return row;
                                                                                                                                                  var nr=Object.assign({},row); nr[rowVar]=relabelMap[v]; return nr;
                                                                                                                                                });
                                                                                                                                              }

                                                                                                                                              function replaceTableValues($table) {
                                                                                                                                                var slots = activeSlots();
                                                                                                                                                if (!slots.length) return;
                                                                                                                                                var rowVars = (lastCfg&&lastCfg.rows)||[], colVars=(lastCfg&&lastCfg.cols)||[];
                                                                                                                                                var numRowVars = rowVars.length;
                                                                                                                                                var fd = computeFilteredData();
                                                                                                                                                if (transformState.mode !== 'none' && rowVars.length) {
                                                                                                                                                  fd = transformDataRows(fd, rowVars[0], transformState);
                                                                                                                                                }
                                                                                                                                                var groups = buildGroups(fd, rowVars, colVars, slots);

                                                                                                                                                function writeCell($cell, rowKey, colKey) {
                                                                                                                                                  var cell = groups[rowKey] && groups[rowKey][colKey];
                                                                                                                                                  if (!cell) return;
                                                                                                                                                  var lines = slots.map(function(s,i){return fmtVal(applyAgg(cell[i]||[],s.aggName));}).filter(function(s){return s!=='';});
                                                                                                                                                  $cell.css({'white-space':'pre-line','line-height':'1.5'}).text(lines.join('\\n'));
                                                                                                                                                }

                                                                                                                                                // PivotTable.js uses rowspan on outer row labels, so rows after the first in each
                                                                                                                                                // group are missing those outer <th> cells.  Track the current label for each
                                                                                                                                                // row-variable position; when a row has k < numRowVars labels, the k labels belong
                                                                                                                                                // to the LAST k positions (the outer ones are still spanned from above).
                                                                                                                                                var curLabels = [];
                                                                                                                                                for (var _i=0; _i<Math.max(numRowVars,1); _i++) curLabels.push('');

                                                                                                                                                function getRowKey($tr) {
                                                                                                                                                  var $lbls = $tr.find('.pvtRowLabel');
                                                                                                                                                  var k = $lbls.length;
                                                                                                                                                  if (k === 0) return '__ALL__';
                                                                                                                                                  $lbls.each(function(i) { curLabels[numRowVars - k + i] = $(this).text().trim(); });
                                                                                                                                                  return numRowVars > 0 ? curLabels.slice(0, numRowVars).join('||') : '__ALL__';
                                                                                                                                                }

                                                                                                                                                if (colVars.length === 0) {
                                                                                                                                                  $table.find('tbody tr').each(function() {
                                                                                                                                                      var $tr=$(this), $f=$tr.children(':first');
                                                                                                                                                      if ($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal')) {
                                                                                                                                                        writeCell($tr.find('.pvtGrandTotal'), '__ALL__', '__ALL__');
                                                                                                                                                        return;
                                                                                                                                                      }
                                                                                                                                                      writeCell($tr.find('.pvtTotal'), getRowKey($tr), '__ALL__');
                                                                                                                                                    });
                                                                                                                                                    return;
                                                                                                                                                  }

                                                                                                                                                  // Build sorted col-key array that matches PivotTable.js col{j} indices.
                                                                                                                                                  // PivotTable.js labels each data cell with col{j} where j is the 0-based
                                                                                                                                                  // index into its internally-sorted list of unique column values.
                                                                                                                                                  var colKeysSorted = (function() {
                                                                                                                                                      var seen = {}, keys = [];
                                                                                                                                                      fd.forEach(function(row) {
                                                                                                                                                          var ck = colVars.map(function(v){ return row[v]==null?'(NA)':String(row[v]); }).join('||');
                                                                                                                                                          if (!seen[ck]) { seen[ck] = true; keys.push(ck); }
                                                                                                                                                        });
                                                                                                                                                        var _ns = ($.pivotUtilities && $.pivotUtilities.naturalSort) || function(a,b){return a<b?-1:a>b?1:0;};
                                                                                                                                                        keys.sort(_ns);
                                                                                                                                                        return keys;
                                                                                                                                                      })();
                                                                                                                                                      var colKeysDOM = extractColKeys($table);

                                                                                                                                                      // Data rows: write to pvtVal cells and the row-total cell
                                                                                                                                                      $table.find('tbody tr').each(function() {
                                                                                                                                                          var $tr=$(this), $f=$tr.children(':first');
                                                                                                                                                          if ($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal')) return;
                                                                                                                                                          var rowKey = getRowKey($tr);
                                                                                                                                                          $tr.find('.pvtVal').each(function(ci) {
                                                                                                                                                              var $cell = $(this);
                                                                                                                                                              var m = ($cell.attr('class')||'').match(/\\bcol(\\d+)\\b/);
                                                                                                                                                              var colKey = m ? colKeysSorted[+m[1]] : undefined;
                                                                                                                                                              if (!colKey) colKey = colKeysDOM[ci];
                                                                                                                                                              writeCell($cell, rowKey, colKey || '__ALL__');
                                                                                                                                                            });
                                                                                                                                                            writeCell($tr.find('.pvtTotal'), rowKey, '__ALL__');
                                                                                                                                                          });
                                                                                                                                                          // Column total cells (pvtTotal colTotal, one per col value in the bottom row)
                                                                                                                                                          $table.find('tbody .pvtTotal.colTotal').each(function(ci) {
                                                                                                                                                              writeCell($(this), '__ALL__', colKeysSorted[ci] || colKeysDOM[ci] || '__ALL__');
                                                                                                                                                            });
                                                                                                                                                            // Grand total cell
                                                                                                                                                            writeCell($table.find('.pvtGrandTotal'), '__ALL__', '__ALL__');
                                                                                                                                                          }

                                                                                                                                                          // -- Summarise code builder ------------------------------------------------
                                                                                                                                                          // Returns { str, valNames } where str is the summarise(...) call string
                                                                                                                                                          function buildSummariseResult(slots) {
                                                                                                                                                            if (!slots.length) return { str:'  summarise(n = n())', valNames:['n'] };
                                                                                                                                                            if (slots.length===1) {
                                                                                                                                                              var s=slots[0];
                                                                                                                                                              var fn=s.aggName==='Count'?'n()':AGG_R_TIDY[s.aggName].replace('VAR',rColName(s.varName));
                                                                                                                                                              var nm=slotName(s);
                                                                                                                                                              return { str:'  summarise('+nm+' = '+fn+')', valNames:[nm] };
                                                                                                                                                            }
                                                                                                                                                            var nonCount=slots.filter(function(s){return s.aggName!=='Count';});
                                                                                                                                                            var hasCount=slots.some(function(s){return s.aggName==='Count';});
                                                                                                                                                            if (!hasCount && nonCount.length>=2) {
                                                                                                                                                              var uVars=[], uAggs=[];
                                                                                                                                                              nonCount.forEach(function(s){if(uVars.indexOf(s.varName)===-1)uVars.push(s.varName);});
                                                                                                                                                              nonCount.forEach(function(s){if(uAggs.indexOf(s.aggName)===-1)uAggs.push(s.aggName);});
                                                                                                                                                              // Case A: same variable, multiple aggregators
                                                                                                                                                              if (uVars.length===1 && uAggs.length>1) {
                                                                                                                                                                var v=rColName(uVars[0]);
                                                                                                                                                                var listParts=uAggs.map(function(a){
                                                                                                                                                                    var lbl=a.toLowerCase().replace(/ /g,'_');
                                                                                                                                                                    return '      '+lbl+' = '+BS+'(x) '+AGG_R_TIDY[a].replace('VAR','x');
                                                                                                                                                                  });
                                                                                                                                                                  var str='  summarise(\\n    across(\\n      '+v+',\\n      list(\\n'+listParts.join(',\\n')+'\\n      ),\\n      .names = \"{.fn}_{.col}\"\\n    )\\n  )';
                                                                                                                                                                  var vn=[]; uVars.forEach(function(vv){uAggs.forEach(function(a){vn.push(a.toLowerCase().replace(/ /g,'_')+'_'+vv);});});
                                                                                                                                                                  return { str:str, valNames:vn };
                                                                                                                                                                }
                                                                                                                                                                // Case B: same aggregator, multiple variables
                                                                                                                                                                if (uAggs.length===1 && uVars.length>1) {
                                                                                                                                                                  var vs=uVars.map(rColName).join(', ');
                                                                                                                                                                  var a=uAggs[0], fn=AGG_R_TIDY[a].replace('VAR','x'), pfx=a.toLowerCase().replace(/ /g,'_');
                                                                                                                                                                  var str='  summarise(\\n    across(c('+vs+'), '+BS+'(x) '+fn+', .names = \"'+pfx+'_{.col}\")\\n  )';
                                                                                                                                                                  var vn=uVars.map(function(vv){return pfx+'_'+vv;});
                                                                                                                                                                  return { str:str, valNames:vn };
                                                                                                                                                                }
                                                                                                                                                                // Case C: multiple variables x multiple aggregators
                                                                                                                                                                if (uVars.length>1 && uAggs.length>1) {
                                                                                                                                                                  var vs=uVars.map(rColName).join(', ');
                                                                                                                                                                  var listParts=uAggs.map(function(a){
                                                                                                                                                                      var lbl=a.toLowerCase().replace(/ /g,'_');
                                                                                                                                                                      return '      '+lbl+' = '+BS+'(x) '+AGG_R_TIDY[a].replace('VAR','x');
                                                                                                                                                                    });
                                                                                                                                                                    var str='  summarise(\\n    across(\\n      c('+vs+'),\\n      list(\\n'+listParts.join(',\\n')+'\\n      ),\\n      .names = \"{.fn}_{.col}\"\\n    )\\n  )';
                                                                                                                                                                    var vn=[]; uVars.forEach(function(vv){uAggs.forEach(function(a){vn.push(a.toLowerCase().replace(/ /g,'_')+'_'+vv);});});
                                                                                                                                                                    return { str:str, valNames:vn };
                                                                                                                                                                  }
                                                                                                                                                                }
                                                                                                                                                                // Fallback: explicit named summarise
                                                                                                                                                                var lines=slots.map(function(s){
                                                                                                                                                                    var fn=s.aggName==='Count'?'n()':AGG_R_TIDY[s.aggName].replace('VAR',rColName(s.varName));
                                                                                                                                                                    return '    '+slotName(s)+' = '+fn;
                                                                                                                                                                  });
                                                                                                                                                                  return { str:'  summarise(\\n'+lines.join(',\\n')+'\\n  )', valNames:slots.map(slotName) };
                                                                                                                                                                }

                                                                                                                                                                // -- fct_ mutate strings --------------------------------------------------
                                                                                                                                                                function getReorderMutate(mode, rowVar, param) {
                                                                                                                                                                  var v=rColName(rowVar), p=param||'';
                                                                                                                                                                  switch(mode) {
                                                                                                                                                                    case 'inorder':     return 'mutate('+v+' = fct_inorder(as.factor('+v+')))';
                                                                                                                                                                    case 'alpha':       return 'mutate('+v+' = fct_relevel(as.factor('+v+'), sort(unique(as.character('+v+')))))';
                                                                                                                                                                    case 'alpha-rev':   return 'mutate('+v+' = fct_relevel(as.factor('+v+'), rev(sort(unique(as.character('+v+'))))))';
                                                                                                                                                                    case 'freq':        return 'mutate('+v+' = fct_infreq(as.factor('+v+')))';
                                                                                                                                                                    case 'freq-rev':    return 'mutate('+v+' = fct_rev(fct_infreq(as.factor('+v+'))))';
                                                                                                                                                                    case 'rev':         return 'mutate('+v+' = fct_rev(as.factor('+v+')))';
                                                                                                                                                                    case 'lowfreq':     return 'mutate('+v+' = fct_lump_lowfreq(as.factor('+v+')))';
                                                                                                                                                                    case 'lump_n':      return 'mutate('+v+' = fct_lump_n(as.factor('+v+'), n = '+(p||'3')+'))';
                                                                                                                                                                    case 'lump_min':    return 'mutate('+v+' = fct_lump_min(as.factor('+v+'), min = '+(p||'10')+'))';
                                                                                                                                                                    case 'lump_prop':   return 'mutate('+v+' = fct_lump_prop(as.factor('+v+'), prop = '+(p||'0.1')+'))';
                                                                                                                                                                    case 'other':       return 'mutate('+v+' = fct_other(as.factor('+v+'), keep = c('+(p?quoteKeep(p):'\"level1\"')+')))';
                                                                                                                                                                    case 'collapse':    return 'mutate('+v+' = fct_collapse(as.factor('+v+'), '+(p||'new_level = c(\"old1\", \"old2\")')+'))';
                                                                                                                                                                    case 'explicit_na': return 'mutate('+v+' = fct_explicit_na(as.factor('+v+')))';
                                                                                                                                                                    default:            return '';
                                                                                                                                                                  }
                                                                                                                                                                }

                                                                                                                                                                // -- Code generation ------------------------------------------------------
                                                                                                                                                                function makeFullCode() {
                                                                                                                                                                  if (!lastCfg) return '# Configure stat slots and drag fields.';
                                                                                                                                                                  var rows=lastCfg.rows||[], cols=lastCfg.cols||[];
                                                                                                                                                                  var slots=activeSlots(), allGrp=rows.concat(cols);
                                                                                                                                                                  if (!allGrp.length||!slots.length) return '# Drag fields to Rows/Columns and configure stat slots above.';

                                                                                                                                                                  var numFLines=getNumericFilterCode(lastCfg,true), catFLines=getCategoricalFilterCode(lastCfg,true);
                                                                                                                                                                  var filterSteps=numFLines.concat(catFLines).map(function(l){return '  '+l+' |>\\n';}).join('');
                                                                                                                                                                  var binSteps=allBinMutateSteps();

                                                                                                                                                                  var hasTransform=transformState.mode!=='none'&&rows.length>0;
                                                                                                                                                                  var hasReorder  =reorderState.mode!=='original'&&rows.length>0;
                                                                                                                                                                  var transformStep=hasTransform?'  '+getReorderMutate(transformState.mode,rows[0],transformState.param)+' |>\\n':'';
                                                                                                                                                                  var reorderStep  =hasReorder  ?'  '+getReorderMutate(reorderState.mode,  rows[0],reorderState.param  )+' |>\\n':'';

                                                                                                                                                                  var sr=buildSummariseResult(slots);
                                                                                                                                                                  var code=dfName+' |>\\n'+filterSteps+binSteps+transformStep+reorderStep+
                                                                                                                                                                  '  group_by('+allGrp.join(', ')+') |>\\n'+sr.str;

                                                                                                                                                                  if (cols.length>0) {
                                                                                                                                                                    var vFrom=sr.valNames.length===1?sr.valNames[0]:'c('+sr.valNames.join(', ')+')';
                                                                                                                                                                    if (widerOpts.valuesFn) {
                                                                                                                                                                      var fnCode=buildValuesFnCode(rows,cols,lastCfg);
                                                                                                                                                                      if (fnCode) {
                                                                                                                                                                        if(sortState.colIdx!==-1){
                                                                                                                                                                          var sarg=sortState.colIdx===null?'rowSums(across(where(is.numeric)), na.rm = TRUE)':rColName(sortState.colLabel);
                                                                                                                                                                          if(sortState.dir===-1) sarg='desc('+sarg+')';
                                                                                                                                                                          fnCode+=' |>\\n  arrange('+sarg+')';
                                                                                                                                                                        }
                                                                                                                                                                        return fnCode;
                                                                                                                                                                      }
                                                                                                                                                                    }
                                                                                                                                                                    code+=' |>\\n'+buildPivotWider(cols,vFrom);
                                                                                                                                                                  }
                                                                                                                                                                  if (sortState.colIdx!==-1) {
                                                                                                                                                                    var arg=sortState.colIdx===null?'rowSums(across(where(is.numeric)), na.rm = TRUE)':rColName(sortState.colLabel);
                                                                                                                                                                    if(sortState.dir===-1) arg='desc('+arg+')';
                                                                                                                                                                    code+=' |>\\n  arrange('+arg+')';
                                                                                                                                                                  }
                                                                                                                                                                  return code;
                                                                                                                                                                }

                                                                                                                                                                function updateFullCode() { $('#__FID__').text(makeFullCode()); }

                                                                                                                                                                function makeCode(cfg) {
                                                                                                                                                                  var rows=cfg.rows||[], cols=cfg.cols||[];
                                                                                                                                                                  var slots=activeSlots(), allGrp=rows.concat(cols);
                                                                                                                                                                  if (!allGrp.length||!slots.length) {
                                                                                                                                                                    var hint='# Drag fields to Rows or Columns below to generate code.';
                                                                                                                                                                    return { wide:hint, long:hint };
                                                                                                                                                                  }

                                                                                                                                                                  var numFLines=getNumericFilterCode(cfg,true), catFLines=getCategoricalFilterCode(cfg,true);
                                                                                                                                                                  var filterPipe=numFLines.concat(catFLines).map(function(l){return '  '+l+' |>\\n';}).join('');

                                                                                                                                                                  var sr=buildSummariseResult(slots);

                                                                                                                                                                  var wideCode;
                                                                                                                                                                  if (cols.length===0) {
                                                                                                                                                                    wideCode='# No Columns variable -- result is already in long form.\\n'+
                                                                                                                                                                    '# Drag a variable into Columns to activate pivot_wider().\\n\\n'+
                                                                                                                                                                    dfName+' |>\\n'+filterPipe+'  group_by('+rows.join(', ')+') |>\\n'+sr.str;
                                                                                                                                                                  } else {
                                                                                                                                                                    var vFrom=sr.valNames.length===1?sr.valNames[0]:'c('+sr.valNames.join(', ')+')';
                                                                                                                                                                    if (widerOpts.valuesFn) {
                                                                                                                                                                      wideCode = buildValuesFnCode(rows,cols,cfg) ||
                                                                                                                                                                      dfName+' |>\\n'+filterPipe+'  group_by('+allGrp.join(', ')+') |>\\n'+sr.str+' |>\\n'+buildPivotWider(cols,vFrom);
                                                                                                                                                                    } else {
                                                                                                                                                                      wideCode=dfName+' |>\\n'+filterPipe+
                                                                                                                                                                      '  group_by('+allGrp.join(', ')+') |>\\n'+sr.str+' |>\\n'+
                                                                                                                                                                      buildPivotWider(cols,vFrom);
                                                                                                                                                                    }
                                                                                                                                                                  }

                                                                                                                                                                  var longCode;
                                                                                                                                                                  if (cols.length===0) {
                                                                                                                                                                    longCode='# Drag a variable into Columns first to generate pivot_longer() code.';
                                                                                                                                                                  } else {
                                                                                                                                                                    var keepCols=rows.length>0?'-c('+rows.join(', ')+')':'everything()';
                                                                                                                                                                    longCode='# Reverses the wide multi-stat result to long form:\\n'+
                                                                                                                                                                    '# (names_to uses \".value\" to split stat names from col-variable values)\\n'+
                                                                                                                                                                    'wide_df |>\\n'+
                                                                                                                                                                    '  pivot_longer(\\n'+
                                                                                                                                                                      '    cols      = '+keepCols+',\\n'+
                                                                                                                                                                      '    names_to  = c(\".value\", '+dq(cols[0])+'),\\n'+
                                                                                                                                                                      '    names_sep = \"_(?=[^_]+$)\"\\n'+
                                                                                                                                                                      '  )';
                                                                                                                                                                    }
                                                                                                                                                                    return { wide:wideCode, long:longCode };
                                                                                                                                                                  }

                                                                                                                                                                  // 根据图表选择的统计量索引，获取单元格内第 statIdx 行的数值
                                                                                                                                                                  function getCellValue($cell, statIdx) {
                                                                                                                                                                    var txt = $cell.text().trim();
                                                                                                                                                                    if (!txt) return 0;
                                                                                                                                                                    var lines = txt.split('\\n');
                                                                                                                                                                    if (lines.length === 1) return parseFloat(lines[0]) || 0;
                                                                                                                                                                    var idx = (statIdx !== undefined) ? statIdx : chartStatIdx;
                                                                                                                                                                    if (idx >= lines.length) idx = 0;
                                                                                                                                                                    var val = parseFloat(lines[idx]);
                                                                                                                                                                    return isNaN(val) ? 0 : val;
                                                                                                                                                                  }
                                                                                                                                                                  // -- Utility functions ----------------------------------------------------
                                                                                                                                                                  function parseVal(s) { var n=parseFloat(s.replace(/,/g,'')); return isNaN(n)?s:n; }
                                                                                                                                                                  function firstLabel(row) { return $(row).find('.pvtRowLabel').first().text().trim(); }
                                                                                                                                                                  function rowTotal(row) { return parseFloat($(row).children().last().text().trim().replace(/,/g,''))||0; }

                                                                                                                                                                  function flattenRowSpans($tbody) {
                                                                                                                                                                    var $rows=$tbody.find('tr'), n=$rows.length, grid=[];
                                                                                                                                                                    for(var i=0;i<n;i++) grid.push([]);
                                                                                                                                                                    $rows.each(function(ri){
                                                                                                                                                                        var ci=0;
                                                                                                                                                                        $(this).find('td,th').each(function(){
                                                                                                                                                                            while(grid[ri][ci]) ci++;
                                                                                                                                                                            var rs=parseInt($(this).attr('rowspan')||1);
                                                                                                                                                                            for(var r=ri;r<Math.min(ri+rs,n);r++) grid[r][ci]=this;
                                                                                                                                                                            ci++;
                                                                                                                                                                          });
                                                                                                                                                                        });
                                                                                                                                                                        $rows.each(function(ri){
                                                                                                                                                                            var seen=[],$row=$(this).empty();
                                                                                                                                                                            for(var ci=0;ci<grid[ri].length;ci++){
                                                                                                                                                                              var cell=grid[ri][ci];
                                                                                                                                                                              if(cell&&seen.indexOf(cell)===-1){seen.push(cell);$row.append($(cell).clone().removeAttr('rowspan'));}
                                                                                                                                                                            }
                                                                                                                                                                          });
                                                                                                                                                                        }

                                                                                                                                                                        var DOM_SORT_MODES=['alpha','alpha-rev','freq','freq-rev','rev'];
                                                                                                                                                                        var DOM_LUMP_MODES=['lowfreq','lump_n','lump_min','lump_prop','other'];

                                                                                                                                                                        // -- Numeric-variable row filtering (identical to pivot_teach_tidyverse.R) -
                                                                                                                                                                        // -- Numeric-variable row filtering (modified to keep low-cardinality numeric vars in numericVars)
                                                                                                                                                                        var numericVars={}, varStats={}, filterState={};
                                                                                                                                                                        (function(){
                                                                                                                                                                            // 步骤1：扫描全部数据，判断哪些列是数值类型
                                                                                                                                                                            ALL_VARS.forEach(function(v) {
                                                                                                                                                                                var isNum = false;
                                                                                                                                                                                for (var i = 0; i < data.length; i++) {
                                                                                                                                                                                  if (typeof data[i][v] === 'number') { isNum = true; break; }
                                                                                                                                                                                }
                                                                                                                                                                                if (isNum) numericVars[v] = true;
                                                                                                                                                                              });
                                                                                                                                                                              // 步骤2：为所有数值变量计算统计量（无论基数高低）
                                                                                                                                                                              Object.keys(numericVars).forEach(function(v){
                                                                                                                                                                                  var vals=data.map(function(d){return d[v];}).filter(function(x){return x!=null&&!isNaN(x);}).sort(function(a,b){return a-b;});
                                                                                                                                                                                  if(!vals.length) return;
                                                                                                                                                                                  var n=vals.length;
                                                                                                                                                                                  function pct(p){var idx=p*(n-1),lo=Math.floor(idx),hi=Math.ceil(idx);return lo===hi?vals[lo]:vals[lo]+(vals[hi]-vals[lo])*(idx-lo);}
                                                                                                                                                                                  var q1=pct(0.25),q3=pct(0.75);
                                                                                                                                                                                  varStats[v]={min:vals[0],max:vals[n-1],q1:q1,q3:q3,iqr:q3-q1,median:pct(0.5),mean:vals.reduce(function(a,b){return a+b;},0)/n,sorted:vals,pct:pct};
                                                                                                                                                                                });
                                                                                                                                                                              }());

                                                                                                                                                                              function computeFilteredData(){
                                                                                                                                                                                var ak = Object.keys(filterState);
                                                                                                                                                                                if (!ak.length) return workData;
                                                                                                                                                                                return workData.filter(function(row){
                                                                                                                                                                                    return ak.every(function(v){
                                                                                                                                                                                        var fs = filterState[v];
                                                                                                                                                                                        if (!fs) return true;
                                                                                                                                                                                        var x = row[v];
                                                                                                                                                                                        // 处理分类过滤器
                                                                                                                                                                                        if (fs.mode === 'categorical' || (fs.selected && fs.selected.length)) {
                                                                                                                                                                                          var key = (x == null) ? '(NA)' : String(x);
                                                                                                                                                                                          return fs.selected.indexOf(key) !== -1;
                                                                                                                                                                                        }
                                                                                                                                                                                        // 处理数值过滤器（原有逻辑）
                                                                                                                                                                                        if (x == null || isNaN(x)) return true;
                                                                                                                                                                                        var st = varStats[v], p = fs.param;
                                                                                                                                                                                        if (x < fs.rangeMin || x > fs.rangeMax) return false;
                                                                                                                                                                                        switch(fs.mode){
                                                                                                                                                                                          case 'iqr':{var k=(p!=null&&isFinite(+p))?+p:1.5;return x>=st.q1-k*st.iqr&&x<=st.q3+k*st.iqr;}
                                                                                                                                                                                          case 'quantile':{var lo=Array.isArray(p)?p[0]:0.05,hi=Array.isArray(p)?p[1]:0.95;return x>=st.pct(lo)&&x<=st.pct(hi);}
                                                                                                                                                                                          case 'above_median':return x>st.median; case 'below_median':return x<st.median;
                                                                                                                                                                                          case 'above_mean':return x>st.mean;   case 'below_mean':return x<st.mean;
                                                                                                                                                                                          case 'top_n':{var n2=Math.max(1,parseInt(p)||10);return x>=st.sorted[Math.max(0,st.sorted.length-n2)];}
                                                                                                                                                                                          case 'bottom_n':{var n3=Math.max(1,parseInt(p)||10);return x<=st.sorted[Math.min(st.sorted.length-1,n3-1)];}
                                                                                                                                                                                          default:return true;
                                                                                                                                                                                        }
                                                                                                                                                                                      });
                                                                                                                                                                                    });
                                                                                                                                                                                  }

                                                                                                                                                                                  function reinitPivot(){
                                                                                                                                                                                    var fd=computeFilteredData();
                                                                                                                                                                                    var cfg=lastCfg?Object.assign({},lastCfg,{onRefresh:onRefreshFn}):{onRefresh:onRefreshFn};
                                                                                                                                                                                    $('#__UID__').pivotUI(fd,cfg,true);
                                                                                                                                                                                  }

                                                                                                                                                                                  function updateFilterMarkers(){
                                                                                                                                                                                    $('#__UID__ .pvtAttr,#__UID__ th.pvtAxisLabel').removeClass('pvt-num-filtered');
                                                                                                                                                                                    Object.keys(filterState).forEach(function(v){
                                                                                                                                                                                        var fs = filterState[v];
                                                                                                                                                                                        if (!fs) return;
                                                                                                                                                                                        // 优先处理分类过滤器（包括低基数数值变量）
                                                                                                                                                                                        if (fs.mode === 'categorical') {
                                                                                                                                                                                          // 获取该变量所有可能的值
                                                                                                                                                                                          var allVals = fs.allValues;
                                                                                                                                                                                          if (!allVals || allVals.length === 0) {
                                                                                                                                                                                            allVals = [];
                                                                                                                                                                                            workData.forEach(function(row) {
                                                                                                                                                                                                var key = (row[v]==null) ? '(NA)' : String(row[v]);
                                                                                                                                                                                                if (allVals.indexOf(key) === -1) allVals.push(key);
                                                                                                                                                                                              });
                                                                                                                                                                                            }
                                                                                                                                                                                            // 如果选中的数量小于总数量，说明处于筛选状态，标记为红色斜体
                                                                                                                                                                                            if (fs.selected && fs.selected.length < allVals.length) {
                                                                                                                                                                                              $('#__UID__ th.pvtAxisLabel,#__UID__ .pvtAttr').filter(function(){
                                                                                                                                                                                                  return $(this).clone().children().remove().end().text().trim()===v;
                                                                                                                                                                                                }).addClass('pvt-num-filtered');
                                                                                                                                                                                              }
                                                                                                                                                                                            }
                                                                                                                                                                                            // 处理数值过滤器（连续变量，unique value > 10）
                                                                                                                                                                                            else if (varStats[v]) {
                                                                                                                                                                                              if (fs.rangeMin > varStats[v].min || fs.rangeMax < varStats[v].max || fs.mode !== 'none') {
                                                                                                                                                                                                $('#__UID__ th.pvtAxisLabel,#__UID__ .pvtAttr').filter(function(){
                                                                                                                                                                                                    return $(this).clone().children().remove().end().text().trim()===v;
                                                                                                                                                                                                  }).addClass('pvt-num-filtered');
                                                                                                                                                                                                }
                                                                                                                                                                                              }
                                                                                                                                                                                            });
                                                                                                                                                                                          }

                                                                                                                                                                                          function getNumericFilterCode(cfg,isTidyverse){
                                                                                                                                                                                            var lines=[];
                                                                                                                                                                                            Object.keys(filterState).forEach(function(v){
                                                                                                                                                                                                var fs=filterState[v],st=varStats[v]; if(!fs||!st) return;
                                                                                                                                                                                                var rv=rColName(v),p=fs.param;
                                                                                                                                                                                                function f4(x){return Math.round(x*10000)/10000;}
                                                                                                                                                                                                if(fs.rangeMin>st.min||fs.rangeMax<st.max){
                                                                                                                                                                                                  var parts=[];
                                                                                                                                                                                                  if(fs.rangeMin>st.min) parts.push(rv+' >= '+f4(fs.rangeMin));
                                                                                                                                                                                                  if(fs.rangeMax<st.max) parts.push(rv+' <= '+f4(fs.rangeMax));
                                                                                                                                                                                                  lines.push(isTidyverse?'filter('+parts.join(', ')+')':'dt <- dt['+parts.join(' & ')+']');
                                                                                                                                                                                                }
                                                                                                                                                                                                var k=(p!=null&&isFinite(+p))?+p:1.5;
                                                                                                                                                                                                switch(fs.mode){
                                                                                                                                                                                                  case 'iqr':
                                                                                                                                                                                                  lines.push(isTidyverse
                                                                                                                                                                                                    ?'filter(between('+rv+', quantile('+rv+', 0.25) - '+k+' * IQR('+rv+'), quantile('+rv+', 0.75) + '+k+' * IQR('+rv+')))'
                                                                                                                                                                                                    :'dt <- dt['+rv+' %between% list(quantile('+rv+', 0.25) - '+k+' * IQR('+rv+'), quantile('+rv+', 0.75) + '+k+' * IQR('+rv+'))]'); break;
                                                                                                                                                                                                    case 'quantile':{var ql=Array.isArray(p)?p[0]:0.05,qh=Array.isArray(p)?p[1]:0.95;
                                                                                                                                                                                                      lines.push(isTidyverse?'filter(between('+rv+', quantile('+rv+', '+ql+'), quantile('+rv+', '+qh+')))'
                                                                                                                                                                                                        :'dt <- dt['+rv+' %between% list(quantile('+rv+', '+ql+'), quantile('+rv+', '+qh+'))]'); break;}
                                                                                                                                                                                                        case 'above_median':lines.push(isTidyverse?'filter('+rv+' > median('+rv+'))':'dt <- dt['+rv+' > median('+rv+')]'); break;
                                                                                                                                                                                                        case 'below_median':lines.push(isTidyverse?'filter('+rv+' < median('+rv+'))':'dt <- dt['+rv+' < median('+rv+')]'); break;
                                                                                                                                                                                                        case 'above_mean':  lines.push(isTidyverse?'filter('+rv+' > mean('+rv+'))':'dt <- dt['+rv+' > mean('+rv+')]'); break;
                                                                                                                                                                                                        case 'below_mean':  lines.push(isTidyverse?'filter('+rv+' < mean('+rv+'))':'dt <- dt['+rv+' < mean('+rv+')]'); break;
                                                                                                                                                                                                        case 'top_n':{var nn=Math.max(1,parseInt(p)||10);
                                                                                                                                                                                                          lines.push(isTidyverse?'slice_max('+rv+', n = '+nn+')':'dt <- dt[frank(-'+rv+', ties.method = \"first\") <= '+nn+']'); break;}
                                                                                                                                                                                                          case 'bottom_n':{var nn2=Math.max(1,parseInt(p)||10);
                                                                                                                                                                                                            lines.push(isTidyverse?'slice_min('+rv+', n = '+nn2+')':'dt <- dt[frank('+rv+', ties.method = \"first\") <= '+nn2+']'); break;}
                                                                                                                                                                                                          }
                                                                                                                                                                                                        });
                                                                                                                                                                                                        return lines;
                                                                                                                                                                                                      }

                                                                                                                                                                                                      function getCategoricalFilterCode(cfg,isTidyverse){
                                                                                                                                                                                                        var lines=[];
                                                                                                                                                                                                        // 首先处理自定义的分类过滤器（来自 filterState）
                                                                                                                                                                                                        Object.keys(filterState).forEach(function(v){
                                                                                                                                                                                                            var fs = filterState[v];
                                                                                                                                                                                                            if (!fs || fs.mode !== 'categorical' || !fs.selected || fs.selected.length === 0) return;
                                                                                                                                                                                                            var rv = rColName(v);
                                                                                                                                                                                                            var selectedSet = {};
                                                                                                                                                                                                            fs.selected.forEach(function(s){ selectedSet[s] = true; });
                                                                                                                                                                                                            var allValues = [];
                                                                                                                                                                                                            workData.forEach(function(row){
                                                                                                                                                                                                                var key = (row[v]==null) ? '(NA)' : String(row[v]);
                                                                                                                                                                                                                if (!selectedSet[key]) selectedSet[key] = false; // 只是为了标记所有可能的值
                                                                                                                                                                                                              });
                                                                                                                                                                                                              var keepVals = fs.selected.filter(function(s){ return s !== '(NA)' || s === '(NA)'; });
                                                                                                                                                                                                              if (keepVals.length === 0) return;
                                                                                                                                                                                                              var q = keepVals.map(function(x){ return dq(x); }).join(', ');
                                                                                                                                                                                                              lines.push(isTidyverse ? 'filter(' + rv + ' %in% c(' + q + '))' : 'dt <- dt[' + rv + ' %in% c(' + q + ')]');
                                                                                                                                                                                                            });
                                                                                                                                                                                                            // 如果 cfg 中还有 inclusions/exclusions（来自 PivotTable.js 原生过滤器，不过现在基本不用），也处理
                                                                                                                                                                                                            if (cfg) {
                                                                                                                                                                                                              var inc = cfg.inclusions||{}, exc = cfg.exclusions||{};
                                                                                                                                                                                                              function q(arr){return arr.map(function(x){ return dq(String(x)); }).join(', ');}
                                                                                                                                                                                                              Object.keys(inc).forEach(function(v){
                                                                                                                                                                                                                  if (!inc[v] || !inc[v].length) return; var rv = rColName(v);
                                                                                                                                                                                                                  lines.push(isTidyverse ? 'filter(' + rv + ' %in% c(' + q(inc[v]) + '))' : 'dt <- dt[' + rv + ' %in% c(' + q(inc[v]) + ')]');
                                                                                                                                                                                                                });
                                                                                                                                                                                                                Object.keys(exc).forEach(function(v){
                                                                                                                                                                                                                    if (!exc[v] || !exc[v].length) return; var rv = rColName(v);
                                                                                                                                                                                                                    lines.push(isTidyverse ? 'filter(!' + rv + ' %in% c(' + q(exc[v]) + '))' : 'dt <- dt[!' + rv + ' %in% c(' + q(exc[v]) + ')]');
                                                                                                                                                                                                                  });
                                                                                                                                                                                                                }
                                                                                                                                                                                                                return lines;
                                                                                                                                                                                                              }

                                                                                                                                                                                                              function showNumericFilterPopup(varName,$anchor){
                                                                                                                                                                                                                $('.num-filter-popup').remove();
                                                                                                                                                                                                                var st=varStats[varName]; if(!st) return;
                                                                                                                                                                                                                if(!filterState[varName]) filterState[varName]={rangeMin:st.min,rangeMax:st.max,mode:'none',param:null};
                                                                                                                                                                                                                var fs=filterState[varName];
                                                                                                                                                                                                                function fmt(x){return Math.round(x*1000)/1000;}
                                                                                                                                                                                                                var $popup=$('<div class=\"num-filter-popup\">').css({position:'absolute',zIndex:10001,background:'#fff',border:'1px solid #999',borderRadius:'4px',boxShadow:'2px 4px 12px rgba(0,0,0,0.3)',minWidth:'310px',fontFamily:'Arial, sans-serif',fontSize:'13px',color:'#1F3864'});
                                                                                                                                                                                                                $popup.on('click',function(e){e.stopPropagation();});
                                                                                                                                                                                                                $popup.append($('<div>').css({padding:'6px 12px',fontWeight:'bold',background:'#1F3864',color:'#fff',borderRadius:'4px 4px 0 0'}).text('Filter: '+varName+'   ['+fmt(st.min)+' - '+fmt(st.max)+']'));
                                                                                                                                                                                                                var $body=$('<div>').css({padding:'8px 12px'});
                                                                                                                                                                                                                var step=(st.max-st.min)/200||1;
                                                                                                                                                                                                                $body.append($('<div class=\"rp-section-hdr\">').css({margin:'0 -12px 4px'}).text('Value range'));
                                                                                                                                                                                                                var $minRow=$('<div>').css({display:'flex',alignItems:'center',gap:'6px',margin:'3px 0'});
                                                                                                                                                                                                                var $minSlider=$('<input type=\"range\">').attr({min:st.min,max:st.max,step:step}).val(fs.rangeMin).css({flex:'1'});
                                                                                                                                                                                                                var $minNum=$('<input type=\"number\" class=\"rp-input\">').val(fmt(fs.rangeMin)).css({width:'65px'});
                                                                                                                                                                                                                $minRow.append($('<span>').css({width:'28px'}).text('Min:'),$minSlider,$minNum);
                                                                                                                                                                                                                var $maxRow=$('<div>').css({display:'flex',alignItems:'center',gap:'6px',margin:'3px 0'});
                                                                                                                                                                                                                var $maxSlider=$('<input type=\"range\">').attr({min:st.min,max:st.max,step:step}).val(fs.rangeMax).css({flex:'1'});
                                                                                                                                                                                                                var $maxNum=$('<input type=\"number\" class=\"rp-input\">').val(fmt(fs.rangeMax)).css({width:'65px'});
                                                                                                                                                                                                                $maxRow.append($('<span>').css({width:'28px'}).text('Max:'),$maxSlider,$maxNum);
                                                                                                                                                                                                                var $countDiv=$('<div>').css({fontSize:'11px',color:'#888',margin:'3px 0 6px'});
                                                                                                                                                                                                                function updateCount(){$countDiv.text('Rows kept: '+computeFilteredData().length+' / '+data.length);}
                                                                                                                                                                                                                $body.append($minRow,$maxRow,$countDiv);
                                                                                                                                                                                                                $body.append($('<div class=\"rp-section-hdr\">').css({margin:'0 -12px 4px'}).text('Row selection'));
                                                                                                                                                                                                                var $sel=$('<select class=\"rp-input\">').css({width:'100%',margin:'4px 0 2px'});
                                                                                                                                                                                                                [['none','None'],['iqr','Exclude IQR outliers  (x \\u00d7 IQR)'],['quantile','Keep quantile range  [lo, hi]'],
                                                                                                                                                                                                                  ['above_median','Keep above median  ('+fmt(st.median)+')'],['below_median','Keep below median  ('+fmt(st.median)+')'],
                                                                                                                                                                                                                  ['above_mean',  'Keep above mean  ('+fmt(st.mean)+')'],  ['below_mean',  'Keep below mean  ('+fmt(st.mean)+')'],
                                                                                                                                                                                                                  ['top_n','Keep largest n observations'],['bottom_n','Keep smallest n observations']
                                                                                                                                                                                                                ].forEach(function(m){$sel.append($('<option>').val(m[0]).text(m[1]));});
                                                                                                                                                                                                                $sel.val(fs.mode);
                                                                                                                                                                                                                var $paramArea=$('<div>').css({marginBottom:'4px'});
                                                                                                                                                                                                                function buildParam(mode){
                                                                                                                                                                                                                  $paramArea.empty();
                                                                                                                                                                                                                  var $row=$('<div>').css({display:'flex',alignItems:'center',gap:'6px',margin:'3px 0'});
                                                                                                                                                                                                                  if(mode==='iqr'){
                                                                                                                                                                                                                    var cur=(fs.mode==='iqr'&&fs.param!=null)?fs.param:1.5;
                                                                                                                                                                                                                    var $inp=$('<input type=\"number\" class=\"rp-input\" step=\"0.5\" min=\"0\">').val(cur).css({width:'55px'});
                                                                                                                                                                                                                    var $info=$('<span>').css({fontSize:'11px',color:'#777'});
                                                                                                                                                                                                                    function updFences(){var kk=parseFloat($inp.val())||1.5;$info.text('['+fmt(st.q1-kk*st.iqr)+', '+fmt(st.q3+kk*st.iqr)+']');fs.param=kk;}
                                                                                                                                                                                                                    $inp.on('input',updFences);updFences();$row.append($('<span>').text('x ='),$inp,$info);
                                                                                                                                                                                                                  } else if(mode==='quantile'){
                                                                                                                                                                                                                    var pArr=(fs.mode==='quantile'&&Array.isArray(fs.param))?fs.param:[0.05,0.95];
                                                                                                                                                                                                                    var $lo=$('<input type=\"number\" class=\"rp-input\" step=\"0.01\" min=\"0\" max=\"1\">').val(pArr[0]).css({width:'50px'});
                                                                                                                                                                                                                    var $hi=$('<input type=\"number\" class=\"rp-input\" step=\"0.01\" min=\"0\" max=\"1\">').val(pArr[1]).css({width:'50px'});
                                                                                                                                                                                                                    var $qi=$('<span>').css({fontSize:'11px',color:'#777'});
                                                                                                                                                                                                                    function updQ(){var ql=parseFloat($lo.val())||0.05,qh=parseFloat($hi.val())||0.95;$qi.text('['+fmt(st.pct(ql))+', '+fmt(st.pct(qh))+']');fs.param=[ql,qh];}
                                                                                                                                                                                                                    $lo.on('input',updQ);$hi.on('input',updQ);updQ();$row.append($('<span>').text('lo:'),$lo,$('<span>').text(' hi:'),$hi,$qi);
                                                                                                                                                                                                                  } else if(mode==='top_n'||mode==='bottom_n'){
                                                                                                                                                                                                                    var curN=(['top_n','bottom_n'].indexOf(fs.mode)!==-1&&fs.param)?fs.param:10;
                                                                                                                                                                                                                    var $ni=$('<input type=\"number\" class=\"rp-input\" step=\"1\" min=\"1\">').val(curN).css({width:'55px'});
                                                                                                                                                                                                                    $ni.on('input',function(){fs.param=parseInt($(this).val())||10;});
                                                                                                                                                                                                                    $row.append($('<span>').text('n ='),$ni);
                                                                                                                                                                                                                  }
                                                                                                                                                                                                                  $paramArea.append($row);
                                                                                                                                                                                                                }
                                                                                                                                                                                                                $sel.on('change',function(){fs.mode=$(this).val();buildParam(fs.mode);updateCount();});
                                                                                                                                                                                                                buildParam(fs.mode);$body.append($sel,$paramArea);
                                                                                                                                                                                                                var $btnRow=$('<div>').css({display:'flex',gap:'6px',marginTop:'8px'});
                                                                                                                                                                                                                var $apply=$('<button>').text('Apply').css({flex:1,padding:'4px 0',cursor:'pointer',border:'none',borderRadius:'3px',background:'#4472C4',color:'#fff',fontWeight:'bold'});
                                                                                                                                                                                                                var $reset=$('<button>').text('Reset').css({flex:1,padding:'4px 0',cursor:'pointer',border:'1px solid #aaa',borderRadius:'3px',background:'#f0f0f0',color:'#333'});
                                                                                                                                                                                                                $btnRow.append($apply,$reset);$body.append($btnRow);$popup.append($body);
                                                                                                                                                                                                                $('body').append($popup);
                                                                                                                                                                                                                var br=$anchor[0].getBoundingClientRect();
                                                                                                                                                                                                                var pl=Math.max(0,Math.min(br.left,window.innerWidth-$popup.outerWidth()-10));
                                                                                                                                                                                                                $popup.css({top:br.bottom+window.scrollY+4,left:pl+window.scrollX});
                                                                                                                                                                                                                updateCount();
                                                                                                                                                                                                                var debTimer=null;
                                                                                                                                                                                                                $minSlider.on('input',function(){var v2=Math.min(parseFloat($(this).val()),fs.rangeMax);fs.rangeMin=v2;$minNum.val(fmt(v2));clearTimeout(debTimer);debTimer=setTimeout(updateCount,180);});
                                                                                                                                                                                                                $minNum.on('change',function(){var v2=Math.max(st.min,Math.min(parseFloat($(this).val())||st.min,fs.rangeMax));fs.rangeMin=v2;$minSlider.val(v2);$minNum.val(fmt(v2));updateCount();});
                                                                                                                                                                                                                $maxSlider.on('input',function(){var v2=Math.max(parseFloat($(this).val()),fs.rangeMin);fs.rangeMax=v2;$maxNum.val(fmt(v2));clearTimeout(debTimer);debTimer=setTimeout(updateCount,180);});
                                                                                                                                                                                                                $maxNum.on('change',function(){var v2=Math.min(st.max,Math.max(parseFloat($(this).val())||st.max,fs.rangeMin));fs.rangeMax=v2;$maxSlider.val(v2);$maxNum.val(fmt(v2));updateCount();});
                                                                                                                                                                                                                $apply.on('click',function(){$('.num-filter-popup').remove();reinitPivot();});
                                                                                                                                                                                                                $reset.on('click',function(){filterState[varName]={rangeMin:st.min,rangeMax:st.max,mode:'none',param:null};$('.num-filter-popup').remove();reinitPivot();});
                                                                                                                                                                                                                setTimeout(function(){$(document).one('click.numfilterpop',function(){$('.num-filter-popup').remove();});},0);
                                                                                                                                                                                                              }
                                                                                                                                                                                                              // Returns the current display order of the first row variable's levels from the pivot table DOM.
                                                                                                                                                                                                              function getRowOrder() {
                                                                                                                                                                                                                var rows = (lastCfg && lastCfg.rows) || [];
                                                                                                                                                                                                                if (!rows.length) return null;
                                                                                                                                                                                                                var $tbody = $('#__UID__ .pvtTable tbody');
                                                                                                                                                                                                                if (!$tbody.length) return null;
                                                                                                                                                                                                                var nRows = rows.length;
                                                                                                                                                                                                                var order = [], seen = {};
                                                                                                                                                                                                                $tbody.find('tr').each(function() {
                                                                                                                                                                                                                    var $labels = $(this).find('.pvtRowLabel');
                                                                                                                                                                                                                    if (!$labels.length || $labels.length < nRows) return;
                                                                                                                                                                                                                    var val = $labels.first().clone().find('.sort-arrow').remove().end().text().trim();
                                                                                                                                                                                                                    if (val && !seen[val]) { seen[val] = true; order.push(val); }
                                                                                                                                                                                                                  });
                                                                                                                                                                                                                  return order.length ? order : null;
                                                                                                                                                                                                                }

                                                                                                                                                                                                                // -- Categorical filter popup (checkboxes for low-cardinality numeric & string variables)
                                                                                                                                                                                                                function showCategoricalFilterPopup(varName, $anchor) {
                                                                                                                                                                                                                  $('.cat-filter-popup').remove();
                                                                                                                                                                                                                  // 获取该变量的所有唯一值（按出现顺序，保留NA）
                                                                                                                                                                                                                  var allValues = [];
                                                                                                                                                                                                                  var valueSet = {};
                                                                                                                                                                                                                  workData.forEach(function(row) {
                                                                                                                                                                                                                      var val = row[varName];
                                                                                                                                                                                                                      var key = (val == null) ? '(NA)' : String(val);
                                                                                                                                                                                                                      if (!valueSet[key]) {
                                                                                                                                                                                                                        valueSet[key] = true;
                                                                                                                                                                                                                        allValues.push(key);
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                    });
                                                                                                                                                                                                                    // 获取当前已选中的值（存储在 filterState 中）
                                                                                                                                                                                                                    if (!filterState[varName]) {
                                                                                                                                                                                                                      filterState[varName] = { mode: 'categorical', selected: allValues.slice() }; // 默认全选
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                    var fs = filterState[varName];
                                                                                                                                                                                                                    fs.allValues = allValues.slice(); // 存储所有可能的值
                                                                                                                                                                                                                    if (!fs.selected) fs.selected = allValues.slice();
                                                                                                                                                                                                                    // 辅助函数：更新计数
                                                                                                                                                                                                                    function updateCount() {
                                                                                                                                                                                                                      var kept = workData.filter(function(row) {
                                                                                                                                                                                                                          var val = row[varName];
                                                                                                                                                                                                                          var key = (val == null) ? '(NA)' : String(val);
                                                                                                                                                                                                                          return fs.selected.indexOf(key) !== -1;
                                                                                                                                                                                                                        }).length;
                                                                                                                                                                                                                        $countDiv.text('Rows kept: ' + kept + ' / ' + workData.length);
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                      // 创建弹窗
                                                                                                                                                                                                                      var $popup = $('<div class=\"cat-filter-popup\">').css({
                                                                                                                                                                                                                          position: 'absolute', zIndex: 10001, background: '#fff', border: '1px solid #999',
                                                                                                                                                                                                                          borderRadius: '4px', boxShadow: '2px 4px 12px rgba(0,0,0,0.3)',
                                                                                                                                                                                                                          minWidth: '320px', maxHeight: '600px', fontFamily: 'Arial, sans-serif', fontSize: '13px', color: '#1F3864'
                                                                                                                                                                                                                        });
                                                                                                                                                                                                                        $popup.on('click', function(e) { e.stopPropagation(); });
                                                                                                                                                                                                                        $popup.append($('<div>').css({ padding: '6px 12px', fontWeight: 'bold', background: '#1F3864', color: '#fff', borderRadius: '4px 4px 0 0' })
                                                                                                                                                                                                                          .text('Filter: ' + varName));
                                                                                                                                                                                                                          var $body = $('<div>').css({ padding: '8px 12px', maxHeight: '300px', overflowY: 'auto' });
                                                                                                                                                                                                                          var $countDiv = $('<div>').css({ fontSize: '11px', color: '#888', margin: '0 0 8px 0' });
                                                                                                                                                                                                                          $body.append($countDiv);
                                                                                                                                                                                                                          // 全选/反选按钮行
                                                                                                                                                                                                                          var $btnRow = $('<div>').css({ display: 'flex', gap: '8px', marginBottom: '10px' });
                                                                                                                                                                                                                          var $selectAll = $('<button>').text('Select All').css({ flex: 1, padding: '3px 0', cursor: 'pointer', border: '1px solid #aaa', borderRadius: '3px', background: '#f0f0f0' });
                                                                                                                                                                                                                          var $deselectAll = $('<button>').text('Deselect All').css({ flex: 1, padding: '3px 0', cursor: 'pointer', border: '1px solid #aaa', borderRadius: '3px', background: '#f0f0f0' });
                                                                                                                                                                                                                          $btnRow.append($selectAll, $deselectAll);
                                                                                                                                                                                                                          $body.append($btnRow);
                                                                                                                                                                                                                          // 复选框列表容器
                                                                                                                                                                                                                          var $checkList = $('<div>').css({ marginBottom: '12px', border: '1px solid #ddd', maxHeight: '150px', overflowY: 'auto', padding: '5px' });
                                                                                                                                                                                                                          var checkboxes = {};
                                                                                                                                                                                                                          // If this is the first row variable, reorder levels to match current pivot table sort order
                                                                                                                                                                                                                          var _rows0 = (lastCfg && lastCfg.rows) || [];
                                                                                                                                                                                                                          if (varName === _rows0[0] && !isBinVar(varName) && !isDateVar(varName)) {
                                                                                                                                                                                                                            var _tableOrder = getRowOrder();
                                                                                                                                                                                                                            if (_tableOrder && _tableOrder.length) {
                                                                                                                                                                                                                              var _inTable = {};
                                                                                                                                                                                                                              _tableOrder.forEach(function(v) { _inTable[v] = true; });
                                                                                                                                                                                                                              var _extra = allValues.filter(function(v) { return !_inTable[v]; });
                                                                                                                                                                                                                              allValues = _tableOrder.filter(function(v) { return allValues.indexOf(v) !== -1; }).concat(_extra);
                                                                                                                                                                                                                            }
                                                                                                                                                                                                                          }
                                                                                                                                                                                                                          allValues.forEach(function(val) {
                                                                                                                                                                                                                              var $label = $('<label>').css({ display: 'block', margin: '3px 0', fontSize: '12px' });
                                                                                                                                                                                                                              var $cb = $('<input type=\"checkbox\">').val(val).css({ marginRight: '6px' });
                                                                                                                                                                                                                              $cb.prop('checked', fs.selected.indexOf(val) !== -1);
                                                                                                                                                                                                                              $label.append($cb).append($('<span>').text(val));
                                                                                                                                                                                                                              $checkList.append($label);
                                                                                                                                                                                                                              checkboxes[val] = $cb;
                                                                                                                                                                                                                            });
                                                                                                                                                                                                                            $body.append($checkList);
                                                                                                                                                                                                                            // 更新计数的函数
                                                                                                                                                                                                                            function updateCheckCount() {
                                                                                                                                                                                                                              var checkedVals = [];
                                                                                                                                                                                                                              for (var v in checkboxes) {
                                                                                                                                                                                                                                if (checkboxes[v].prop('checked')) checkedVals.push(v);
                                                                                                                                                                                                                              }
                                                                                                                                                                                                                              fs.selected = checkedVals;
                                                                                                                                                                                                                              updateCount();
                                                                                                                                                                                                                            }
                                                                                                                                                                                                                            $selectAll.on('click', function() {
                                                                                                                                                                                                                                for (var v in checkboxes) checkboxes[v].prop('checked', true);
                                                                                                                                                                                                                                updateCheckCount();
                                                                                                                                                                                                                              });
                                                                                                                                                                                                                              $deselectAll.on('click', function() {
                                                                                                                                                                                                                                  for (var v in checkboxes) checkboxes[v].prop('checked', false);
                                                                                                                                                                                                                                  updateCheckCount();
                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                for (var v in checkboxes) {
                                                                                                                                                                                                                                  checkboxes[v].on('change', updateCheckCount);
                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                var $btnRow2 = $('<div>').css({ display: 'flex', gap: '8px', marginTop: '8px' });
                                                                                                                                                                                                                                var $apply = $('<button>').text('Apply').css({ flex: 1, padding: '5px 0', cursor: 'pointer', border: 'none', borderRadius: '3px', background: '#4472C4', color: '#fff', fontWeight: 'bold' });
                                                                                                                                                                                                                                var $reset = $('<button>').text('Reset').css({ flex: 1, padding: '5px 0', cursor: 'pointer', border: '1px solid #aaa', borderRadius: '3px', background: '#f0f0f0', color: '#333' });
                                                                                                                                                                                                                                $btnRow2.append($apply, $reset);
                                                                                                                                                                                                                                $body.append($btnRow2);
                                                                                                                                                                                                                                $popup.append($body);
                                                                                                                                                                                                                                $('body').append($popup);
                                                                                                                                                                                                                                // 定位弹窗
                                                                                                                                                                                                                                var br = $anchor[0].getBoundingClientRect();
                                                                                                                                                                                                                                var pl = Math.max(0, Math.min(br.left, window.innerWidth - $popup.outerWidth() - 10));
                                                                                                                                                                                                                                $popup.css({ top: br.bottom + window.scrollY + 4, left: pl + window.scrollX });
                                                                                                                                                                                                                                // 初始计数
                                                                                                                                                                                                                                updateCount();
                                                                                                                                                                                                                                // Apply 按钮：保存当前选中状态，关闭弹窗，刷新 pivot
                                                                                                                                                                                                                                $apply.on('click', function() {
                                                                                                                                                                                                                                    $('.cat-filter-popup').remove();
                                                                                                                                                                                                                                    reinitPivot();
                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                  // Reset 按钮：选中全部值，刷新计数，但不关闭（用户可以继续调整）
                                                                                                                                                                                                                                  $reset.on('click', function() {
                                                                                                                                                                                                                                      for (var v in checkboxes) checkboxes[v].prop('checked', true);
                                                                                                                                                                                                                                      updateCheckCount();
                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                    // 点击外部关闭
                                                                                                                                                                                                                                    setTimeout(function() {
                                                                                                                                                                                                                                        $(document).one('click.catfilterpop', function() { $('.cat-filter-popup').remove(); });
                                                                                                                                                                                                                                      }, 0);
                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                    // -- Row DOM operations (identical to pivot_teach_tidyverse.R) ------------
                                                                                                                                                                                                                                    function applyInorderRows($table){
                                                                                                                                                                                                                                      if(!lastCfg||!lastCfg.rows||!lastCfg.rows.length) return;
                                                                                                                                                                                                                                      var rowVar=lastCfg.rows[0],seen={},inorderKeys=[];
                                                                                                                                                                                                                                      data.forEach(function(d){var v=d[rowVar],s=(v==null)?'(NA)':String(v);if(!seen[s]){seen[s]=true;inorderKeys.push(s);}});
                                                                                                                                                                                                                                      var $tbody=$table.find('tbody');flattenRowSpans($tbody);$tbody=$table.find('tbody');
                                                                                                                                                                                                                                      var dataRows=[],totalRows=[];
                                                                                                                                                                                                                                      $tbody.find('tr').each(function(){var $f=$(this).children(':first');if($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal'))totalRows.push(this);else dataRows.push(this);});
                                                                                                                                                                                                                                      var groups={};dataRows.forEach(function(row){var k=firstLabel(row);(groups[k]=groups[k]||[]).push(row);});
                                                                                                                                                                                                                                      var ordered=[];inorderKeys.forEach(function(k){if(groups[k])ordered.push(k);});
                                                                                                                                                                                                                                      Object.keys(groups).forEach(function(k){if(ordered.indexOf(k)===-1)ordered.push(k);});
                                                                                                                                                                                                                                      $tbody.empty();ordered.forEach(function(k){groups[k].forEach(function(r){$tbody.append(r);});});totalRows.forEach(function(r){$tbody.append(r);});
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    function applyLumpRows($table){
                                                                                                                                                                                                                                      if(!lastCfg||!lastCfg.rows||!lastCfg.rows.length) return;
                                                                                                                                                                                                                                      var mode=transformState.mode,p=transformState.param||'';
                                                                                                                                                                                                                                      var $tbody=$table.find('tbody');flattenRowSpans($tbody);$tbody=$table.find('tbody');
                                                                                                                                                                                                                                      var dataRows=[],totalRows=[];
                                                                                                                                                                                                                                      $tbody.find('tr').each(function(){var $f=$(this).children(':first');if($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal'))totalRows.push(this);else dataRows.push(this);});
                                                                                                                                                                                                                                      if(!dataRows.length) return;
                                                                                                                                                                                                                                      var seen={},orderedFirstKeys=[],firstTotals={};
                                                                                                                                                                                                                                      dataRows.forEach(function(row){var k=firstLabel(row);if(!seen[k]){seen[k]=true;orderedFirstKeys.push(k);}firstTotals[k]=(firstTotals[k]||0)+rowTotal(row);});
                                                                                                                                                                                                                                      var grandTotal=0;orderedFirstKeys.forEach(function(k){grandTotal+=firstTotals[k];});
                                                                                                                                                                                                                                      var lumpKeys=[];
                                                                                                                                                                                                                                      if(mode==='lump_n'){var n=parseInt(p,10);if(isNaN(n)||n<0)n=3;var byFreq=orderedFirstKeys.slice().sort(function(a,b){return firstTotals[b]-firstTotals[a];});lumpKeys=byFreq.slice(n);}
                                                                                                                                                                                                                                      else if(mode==='lump_min'){var mn=parseFloat(p);if(isNaN(mn))mn=10;lumpKeys=orderedFirstKeys.filter(function(k){return firstTotals[k]<mn;});}
                                                                                                                                                                                                                                      else if(mode==='lump_prop'){var prop=parseFloat(p);if(isNaN(prop)||prop<=0)prop=0.1;lumpKeys=orderedFirstKeys.filter(function(k){return grandTotal<=0||firstTotals[k]/grandTotal<prop;});}
                                                                                                                                                                                                                                      else if(mode==='lowfreq'){var sortedAsc=orderedFirstKeys.slice().sort(function(a,b){return firstTotals[a]-firstTotals[b];});var otherAcc=0;for(var i=0;i<sortedAsc.length-1;i++){var newOther=otherAcc+firstTotals[sortedAsc[i]];if(newOther<firstTotals[sortedAsc[i+1]]){lumpKeys.push(sortedAsc[i]);otherAcc=newOther;}else break;}}
                                                                                                                                                                                                                                      else if(mode==='other'){var keepLevels=p.replace(/[\"']/g,'').split(',').map(function(s){return s.trim();}).filter(Boolean);lumpKeys=orderedFirstKeys.filter(function(k){return keepLevels.indexOf(k)===-1;});}
                                                                                                                                                                                                                                      else return;
                                                                                                                                                                                                                                      if(!lumpKeys.length) return;
                                                                                                                                                                                                                                      var numRowCols=$(dataRows[0]).find('.pvtRowLabel').length;
                                                                                                                                                                                                                                      function rowKey(row){var lbls=$(row).find('.pvtRowLabel').map(function(){return $(this).text().trim();}).get();var first=lumpKeys.indexOf(lbls[0])!==-1?'Other':lbls[0];return [first].concat(lbls.slice(1)).join('||');}
                                                                                                                                                                                                                                      var seenKey={},orderedKeys=[],groups={};
                                                                                                                                                                                                                                      dataRows.forEach(function(row){var k=rowKey(row);if(!seenKey[k]){seenKey[k]=true;orderedKeys.push(k);}(groups[k]=groups[k]||[]).push(row);});
                                                                                                                                                                                                                                      var keepKeys=orderedKeys.filter(function(k){return k.split('||')[0]!=='Other';});
                                                                                                                                                                                                                                      var otherKeys=orderedKeys.filter(function(k){return k.split('||')[0]==='Other';});
                                                                                                                                                                                                                                      $tbody.empty();
                                                                                                                                                                                                                                      keepKeys.forEach(function(k){$tbody.append(groups[k][0]);});
                                                                                                                                                                                                                                      otherKeys.forEach(function(k){var gRows=groups[k];if(gRows.length===1){$(gRows[0]).find('.pvtRowLabel').first().text('Other');$tbody.append(gRows[0]);}else{var $mg=$(gRows[0]).clone();$mg.find('.pvtRowLabel').first().text('Other');$mg.children().each(function(ci){if(ci<numRowCols)return;var sum=0,hasNum=false;gRows.forEach(function(row){var n=parseFloat($(row).children().eq(ci).text().replace(/,/g,''));if(!isNaN(n)){sum+=n;hasNum=true;}});if(hasNum)$(this).text(sum);});$tbody.append($mg[0]);}});
                                                                                                                                                                                                                                      totalRows.forEach(function(r){$tbody.append(r);});
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    function applyCollapseRows($table){
                                                                                                                                                                                                                                      if(!lastCfg||!lastCfg.rows||!lastCfg.rows.length) return;
                                                                                                                                                                                                                                      var p=transformState.param||'',collapseMap={};
                                                                                                                                                                                                                                      var re=/(\\w+)\\s*=\\s*c\\s*\\(([^)]+)\\)/g,m;
                                                                                                                                                                                                                                      while((m=re.exec(p))!==null){var newName=m[1].trim();m[2].replace(/[\"']/g,'').split(',').forEach(function(s){var t=s.trim();if(t)collapseMap[t]=newName;});}
                                                                                                                                                                                                                                      if(!Object.keys(collapseMap).length) return;
                                                                                                                                                                                                                                      var $tbody=$table.find('tbody');flattenRowSpans($tbody);$tbody=$table.find('tbody');
                                                                                                                                                                                                                                      var dataRows=[],totalRows=[];
                                                                                                                                                                                                                                      $tbody.find('tr').each(function(){var $f=$(this).children(':first');if($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal'))totalRows.push(this);else dataRows.push(this);});
                                                                                                                                                                                                                                      if(!dataRows.length) return;
                                                                                                                                                                                                                                      var numRowCols=$(dataRows[0]).find('.pvtRowLabel').length;
                                                                                                                                                                                                                                      function rowKey(row){var lbls=$(row).find('.pvtRowLabel').map(function(){return $(this).text().trim();}).get();return [collapseMap[lbls[0]]||lbls[0]].concat(lbls.slice(1)).join('||');}
                                                                                                                                                                                                                                      var seenKey={},orderedKeys=[],groups={};
                                                                                                                                                                                                                                      dataRows.forEach(function(row){var k=rowKey(row);if(!seenKey[k]){seenKey[k]=true;orderedKeys.push(k);}(groups[k]=groups[k]||[]).push(row);});
                                                                                                                                                                                                                                      $tbody.empty();
                                                                                                                                                                                                                                      orderedKeys.forEach(function(k){var gRows=groups[k],newFirst=k.split('||')[0];if(gRows.length===1){$(gRows[0]).find('.pvtRowLabel').first().text(newFirst);$tbody.append(gRows[0]);}else{var $mg=$(gRows[0]).clone();$mg.find('.pvtRowLabel').first().text(newFirst);$mg.children().each(function(ci){if(ci<numRowCols)return;var sum=0,hasNum=false;gRows.forEach(function(row){var n=parseFloat($(row).children().eq(ci).text().replace(/,/g,''));if(!isNaN(n)){sum+=n;hasNum=true;}});if(hasNum)$(this).text(sum);});$tbody.append($mg[0]);}});
                                                                                                                                                                                                                                      totalRows.forEach(function(r){$tbody.append(r);});
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    function applyReorder($table){
                                                                                                                                                                                                                                      var $tbody=$table.find('tbody');
                                                                                                                                                                                                                                      if(pristineTbodyHTML) $tbody.replaceWith($(pristineTbodyHTML));
                                                                                                                                                                                                                                      var tMode=transformState.mode;
                                                                                                                                                                                                                                      if(tMode!=='none'){
                                                                                                                                                                                                                                        if(DOM_LUMP_MODES.indexOf(tMode)!==-1)applyLumpRows($table);
                                                                                                                                                                                                                                        else if(tMode==='collapse')applyCollapseRows($table);
                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                      var rMode=reorderState.mode; if(rMode==='original') return;
                                                                                                                                                                                                                                      if(rMode==='inorder'){applyInorderRows($table);return;}
                                                                                                                                                                                                                                      var $tb=$table.find('tbody');flattenRowSpans($tb);$tb=$table.find('tbody');
                                                                                                                                                                                                                                      var dataRows=[],totalRows=[];
                                                                                                                                                                                                                                      $tb.find('tr').each(function(){var $f=$(this).children(':first');if($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal'))totalRows.push(this);else dataRows.push(this);});
                                                                                                                                                                                                                                      if(!dataRows.length) return;
                                                                                                                                                                                                                                      var seen={},orderedKeys=[],rowTotals={};
                                                                                                                                                                                                                                      dataRows.forEach(function(row){var k=firstLabel(row);if(!seen[k]){seen[k]=true;orderedKeys.push(k);}rowTotals[k]=(rowTotals[k]||0)+rowTotal(row);});
                                                                                                                                                                                                                                      var sorted;
                                                                                                                                                                                                                                      switch(rMode){
                                                                                                                                                                                                                                        case 'alpha':    sorted=orderedKeys.slice().sort(function(a,b){return a.localeCompare(b);}); break;
                                                                                                                                                                                                                                        case 'alpha-rev':sorted=orderedKeys.slice().sort(function(a,b){return b.localeCompare(a);}); break;
                                                                                                                                                                                                                                        case 'freq':     sorted=orderedKeys.slice().sort(function(a,b){return rowTotals[b]-rowTotals[a];}); break;
                                                                                                                                                                                                                                        case 'freq-rev': sorted=orderedKeys.slice().sort(function(a,b){return rowTotals[a]-rowTotals[b];}); break;
                                                                                                                                                                                                                                        case 'rev':      sorted=orderedKeys.slice().reverse(); break;
                                                                                                                                                                                                                                        default: return;
                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                      var groups={};dataRows.forEach(function(row){var k=firstLabel(row);(groups[k]=groups[k]||[]).push(row);});
                                                                                                                                                                                                                                      $tb.empty();sorted.forEach(function(k){(groups[k]||[]).forEach(function(r){$tb.append(r);});});totalRows.forEach(function(r){$tb.append(r);});
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                    function sortRows($table,colIdx,dir){
                                                                                                                                                                                                                                      var $tbody=$table.find('tbody');flattenRowSpans($tbody);
                                                                                                                                                                                                                                      var dataRows=[],totalRows=[];
                                                                                                                                                                                                                                      $tbody.find('tr').each(function(){var $f=$(this).children(':first');if($f.hasClass('pvtTotalLabel')||$f.hasClass('pvtGrandTotal'))totalRows.push(this);else dataRows.push(this);});
                                                                                                                                                                                                                                      var numRowCols=dataRows.length>0?$(dataRows[0]).find('.pvtRowLabel').length:0;
                                                                                                                                                                                                                                      dataRows.sort(function(a,b){
                                                                                                                                                                                                                                          var $ac=(colIdx===null)?$(a).children().last():$(a).children().eq(colIdx+numRowCols);
                                                                                                                                                                                                                                          var $bc=(colIdx===null)?$(b).children().last():$(b).children().eq(colIdx+numRowCols);
                                                                                                                                                                                                                                          var av = getCellValue($ac);
                                                                                                                                                                                                                                          var bv = getCellValue($bc);
                                                                                                                                                                                                                                          if(typeof av==='number'&&typeof bv==='number') return dir*(av-bv);
                                                                                                                                                                                                                                          return dir*String(av).localeCompare(String(bv));
                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                        $tbody.empty();$.each(dataRows,function(_,r){$tbody.append(r);});$.each(totalRows,function(_,r){$tbody.append(r);});
                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                      function applyRowSort($tbl, rowIdx, dir) {
                                                                                                                                                                                                                                        // --- 【新增：排序方向切換邏輯】 ---
                                                                                                                                                                                                                                        var lastSortIdx = $tbl.data('lastRowSortIdx');
                                                                                                                                                                                                                                        var lastSortDir = $tbl.data('lastSortDir');
                                                                                                                                                                                                                                        var currentDir;

                                                                                                                                                                                                                                        if (rowIdx === lastSortIdx) {
                                                                                                                                                                                                                                          // 如果點擊的是同一行，反轉方向
                                                                                                                                                                                                                                          currentDir = lastSortDir === 1 ? -1 : 1;
                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                          // 如果點擊的是新行，預設由小到大 (1)
                                                                                                                                                                                                                                          currentDir = 1;
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        // 儲存目前狀態，供下次點擊使用
                                                                                                                                                                                                                                        $tbl.data('lastRowSortIdx', rowIdx);
                                                                                                                                                                                                                                        $tbl.data('lastSortDir', currentDir);
                                                                                                                                                                                                                                        // --------------------------------

                                                                                                                                                                                                                                        var $tbody = $tbl.find('tbody').first();
                                                                                                                                                                                                                                        var $rows = $tbody.find('tr');
                                                                                                                                                                                                                                        var $targetRow = $rows.eq(rowIdx);

                                                                                                                                                                                                                                        // 取得基準欄位數量 (以第一行資料列為準)
                                                                                                                                                                                                                                        var expectedNumCols = $rows.first().find('td.pvtVal').length;
                                                                                                                                                                                                                                        if (expectedNumCols === 0) return;

                                                                                                                                                                                                                                        // 取得當前點擊列的數據格
                                                                                                                                                                                                                                        var $vals = $targetRow.find('td.pvtVal');
                                                                                                                                                                                                                                        if ($vals.length === 0) {
                                                                                                                                                                                                                                          $vals = $targetRow.find('td.pvtTotal');
                                                                                                                                                                                                                                          if ($vals.length > expectedNumCols) {
                                                                                                                                                                                                                                            $vals = $vals.slice(0, expectedNumCols);
                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        var numCols = $vals.length;
                                                                                                                                                                                                                                        if (numCols === 0) return;

                                                                                                                                                                                                                                        // 1. 取得表頭路徑矩陣
                                                                                                                                                                                                                                        var $theadRows = $tbl.find('thead tr').filter(function() {
                                                                                                                                                                                                                                            return $(this).find('.pvtColLabel').length > 0;
                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                          if ($theadRows.length === 0) return;

                                                                                                                                                                                                                                          var headerMatrix = [];
                                                                                                                                                                                                                                          $theadRows.each(function(rIdx) {
                                                                                                                                                                                                                                              headerMatrix[rIdx] = new Array(numCols);
                                                                                                                                                                                                                                              var currentPos = 0;
                                                                                                                                                                                                                                              $(this).find('.pvtColLabel').each(function() {
                                                                                                                                                                                                                                                  var $th = $(this);
                                                                                                                                                                                                                                                  var txt = $th.text().trim();
                                                                                                                                                                                                                                                  var span = parseInt($th.attr('colspan')) || 1;
                                                                                                                                                                                                                                                  for (var i = 0; i < span; i++) {
                                                                                                                                                                                                                                                    if (currentPos + i < numCols) {
                                                                                                                                                                                                                                                      headerMatrix[rIdx][currentPos + i] = (txt === '' ? ' ' : txt);
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                  currentPos += span;
                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                              // 2. 綁定路徑與數值
                                                                                                                                                                                                                                              var colData = [];
                                                                                                                                                                                                                                              for (var j = 0; j < numCols; j++) {
                                                                                                                                                                                                                                                var path = [];
                                                                                                                                                                                                                                                for (var i = 0; i < $theadRows.length; i++) {
                                                                                                                                                                                                                                                  path.push(headerMatrix[i][j] || ' ');
                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                var v = getCellValue($vals.eq(j));
                                                                                                                                                                                                                                                colData.push({ originalIdx: j, val: isNaN(v) ? 0 : v, fullPath: path });    }

                                                                                                                                                                                                                                                // 3. 執行排序 (使用我們剛剛計算出的 currentDir)
                                                                                                                                                                                                                                                colData.sort(function(a, b) {
                                                                                                                                                                                                                                                    return (a.val - b.val) * currentDir;
                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                  // 4. 更新數據行 - 三段式組裝
                                                                                                                                                                                                                                                  $rows.each(function() {
                                                                                                                                                                                                                                                      var $tr = $(this);
                                                                                                                                                                                                                                                      var $allCells = $tr.children().toArray();

                                                                                                                                                                                                                                                      var $currentRowData = $tr.find('td.pvtVal');
                                                                                                                                                                                                                                                      if ($currentRowData.length === 0) {
                                                                                                                                                                                                                                                        $currentRowData = $tr.find('td.pvtTotal');
                                                                                                                                                                                                                                                        if ($currentRowData.length > expectedNumCols) {
                                                                                                                                                                                                                                                          $currentRowData = $currentRowData.slice(0, expectedNumCols);
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                        $currentRowData = $currentRowData.slice(0, expectedNumCols);
                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                      var dataArray = $currentRowData.toArray();
                                                                                                                                                                                                                                                      if (dataArray.length === 0) return;

                                                                                                                                                                                                                                                      var startIndex = $allCells.indexOf(dataArray[0]);
                                                                                                                                                                                                                                                      if (startIndex === -1) return;

                                                                                                                                                                                                                                                      var beforeCells = $allCells.slice(0, startIndex);
                                                                                                                                                                                                                                                      var afterCells = $allCells.slice(startIndex + expectedNumCols);

                                                                                                                                                                                                                                                      $tr.empty();
                                                                                                                                                                                                                                                      $(beforeCells).appendTo($tr);
                                                                                                                                                                                                                                                      colData.forEach(function(item) {
                                                                                                                                                                                                                                                          if (dataArray[item.originalIdx]) $(dataArray[item.originalIdx]).appendTo($tr);
                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                        $(afterCells).appendTo($tr);
                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                      // 5. 重構表頭 (使用模板拷貝法)
                                                                                                                                                                                                                                                      $theadRows.each(function(rIdx) {
                                                                                                                                                                                                                                                          var $tr = $(this);
                                                                                                                                                                                                                                                          var $oldLabels = $tr.find('.pvtColLabel');
                                                                                                                                                                                                                                                          if ($oldLabels.length === 0) return;

                                                                                                                                                                                                                                                          var $anchor = $oldLabels.first().prev();
                                                                                                                                                                                                                                                          var hasAnchor = ($anchor.length > 0);

                                                                                                                                                                                                                                                          var $template = $oldLabels.last().clone();
                                                                                                                                                                                                                                                          $template.attr('colspan', 1).css('width', '').removeClass('pvtHover pvtActive');

                                                                                                                                                                                                                                                          $oldLabels.remove();

                                                                                                                                                                                                                                                          var $lastInserted = $anchor;
                                                                                                                                                                                                                                                          colData.forEach(function(item) {
                                                                                                                                                                                                                                                              var labelText = item.fullPath[rIdx];
                                                                                                                                                                                                                                                              var $newTh = $template.clone().text(labelText);
                                                                                                                                                                                                                                                              if (hasAnchor) {
                                                                                                                                                                                                                                                                $lastInserted.after($newTh);
                                                                                                                                                                                                                                                                $lastInserted = $newTh;
                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                $tr.prepend($newTh);
                                                                                                                                                                                                                                                                $lastInserted = $tr.find('.pvtColLabel').last();
                                                                                                                                                                                                                                                                hasAnchor = true;
                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                          // 最後恢復排序事件綁定
                                                                                                                                                                                                                                                          if (typeof attachSort === 'function') attachSort($tbl);
                                                                                                                                                                                                                                                          return currentDir;
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                        function fixColspans($tbl) {
                                                                                                                                                                                                                                                          // 排序後維持分解狀態，不再合併
                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                        }


                                                                                                                                                                                                                                                        function attachSort($table){
                                                                                                                                                                                                                                                          sortState={colIdx:-1,dir:1,colLabel:null};
                                                                                                                                                                                                                                                          rowSortState={rowIdx:-1,dir:1};
                                                                                                                                                                                                                                                          var $leafRow=$table.find('thead tr').filter(function(){return $(this).find('th.pvtColLabel').length>0;}).last();
                                                                                                                                                                                                                                                          var leafKeys=extractColKeys($table);
                                                                                                                                                                                                                                                          $leafRow.find('th.pvtColLabel').each(function(i){
                                                                                                                                                                                                                                                              var $th=$(this);
                                                                                                                                                                                                                                                              var label=leafKeys[i]?leafKeys[i].replace(/[|][|]/g,'_'):$th.text().trim();
                                                                                                                                                                                                                                                              $th.off('click.pvtsort').on('click.pvtsort',function(){
                                                                                                                                                                                                                                                                  $table.find('.sort-arrow').remove();
                                                                                                                                                                                                                                                                  if(sortState.colIdx===i){sortState.dir*=-1;}else{sortState.colIdx=i;sortState.dir=1;sortState.colLabel=label;}
                                                                                                                                                                                                                                                                  $th.append('<span class=\"sort-arrow\">'+(sortState.dir===1?' \\u25b2':' \\u25bc')+'</span>');
                                                                                                                                                                                                                                                                  sortRows($table,i,sortState.dir);updateFullCode();renderBarChart();saveStateToHash();
                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                              var $colRow=$table.find('th.pvtColLabel,th.pvtAxisLabel').first().closest('tr');
                                                                                                                                                                                                                                                              var $totalHdr=$colRow.find('th.pvtTotalLabel');
                                                                                                                                                                                                                                                              if($totalHdr.length){
                                                                                                                                                                                                                                                                $totalHdr.off('click.pvtsort').on('click.pvtsort',function(){
                                                                                                                                                                                                                                                                    $table.find('.sort-arrow').remove();
                                                                                                                                                                                                                                                                    if(sortState.colIdx===null){sortState.dir*=-1;}else{sortState.colIdx=null;sortState.dir=1;sortState.colLabel=null;}
                                                                                                                                                                                                                                                                    $totalHdr.append('<span class=\"sort-arrow\">'+(sortState.dir===1?' \\u25b2':' \\u25bc')+'</span>');
                                                                                                                                                                                                                                                                    sortRows($table,null,sortState.dir);updateFullCode();renderBarChart();saveStateToHash();
                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                $table.off('click.pvtrowsort').on('click.pvtrowsort','.pvtRowLabel,.pvtTotalLabel',function(){
                                                                                                                                                                                                                                                                    var $th=$(this);
                                                                                                                                                                                                                                                                    if(!$th.closest('tbody').length) return;
                                                                                                                                                                                                                                                                    var $tbody=$table.find('tbody'),$rows=$tbody.find('tr'),n=$rows.length,grid=[];
                                                                                                                                                                                                                                                                    for(var gi=0;gi<n;gi++) grid.push([]);
                                                                                                                                                                                                                                                                    $rows.each(function(ri){
                                                                                                                                                                                                                                                                        var ci=0;
                                                                                                                                                                                                                                                                        $(this).find('td,th').each(function(){
                                                                                                                                                                                                                                                                            while(grid[ri][ci]) ci++;
                                                                                                                                                                                                                                                                            var rs=parseInt($(this).attr('rowspan')||1);
                                                                                                                                                                                                                                                                            for(var r=ri;r<Math.min(ri+rs,n);r++){if(!grid[r])grid[r]=[];if(!grid[r][ci])grid[r][ci]=this;}
                                                                                                                                                                                                                                                                            ci++;
                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                        var rowIdx=$rows.index($th.closest('tr')[0]),varIdx=0,grow=grid[rowIdx]||[];
                                                                                                                                                                                                                                                                        for(var c=0;c<grow.length;c++){if(grow[c]===$th[0]){varIdx=c;break;}}
                                                                                                                                                                                                                                                                        var nRowVars=((lastCfg&&lastCfg.rows)||[]).length,isTotals=$th.hasClass('pvtTotalLabel');
                                                                                                                                                                                                                                                                        if(!isTotals&&varIdx!==nRowVars-1) return;
                                                                                                                                                                                                                                                                        // 先决定预期的方向（用于传入 applyRowSort）
                                                                                                                                                                                                                                                                        if(rowSortState.rowIdx===rowIdx){
                                                                                                                                                                                                                                                                          var expectedDir = rowSortState.dir * -1;
                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                          var expectedDir = 1;
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                        // 调用 applyRowSort，获取实际排序后的方向
                                                                                                                                                                                                                                                                        var actualDir = applyRowSort($table, rowIdx, expectedDir);
                                                                                                                                                                                                                                                                        // 同步外部状态
                                                                                                                                                                                                                                                                        rowSortState.rowIdx = rowIdx;
                                                                                                                                                                                                                                                                        rowSortState.dir = actualDir;

                                                                                                                                                                                                                                                                        $table.find('.sort-arrow').remove();
                                                                                                                                                                                                                                                                        var $rowsAfter=$table.find('tbody tr');
                                                                                                                                                                                                                                                                        if(isTotals){
                                                                                                                                                                                                                                                                          $rowsAfter.eq(rowIdx).find('.pvtTotalLabel').first().append('<span class=\"sort-arrow\">'+(actualDir===1?' \\u25b2':' \\u25bc')+'</span>');
                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                          $rowsAfter.eq(rowIdx).find('.pvtRowLabel').eq(varIdx).append('<span class=\"sort-arrow\">'+(actualDir===1?' \\u25b2':' \\u25bc')+'</span>');
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                        updateFullCode();renderBarChart();saveStateToHash();
                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    function showReorderPopup($btn){
                                                                                                                                                                                                                                                                      $('.reorder-popup').remove();
                                                                                                                                                                                                                                                                      var $popup=$('<div class=\"reorder-popup\"></div>').css({position:'absolute',zIndex:10000,display:'flex',flexDirection:'row',background:'#ffffff',border:'1px solid #999',borderRadius:'4px',boxShadow:'2px 4px 12px rgba(0,0,0,0.3)',fontFamily:'Arial, sans-serif',fontSize:'13px',color:'#1F3864'});
                                                                                                                                                                                                                                                                      $popup.on('click',function(e){e.stopPropagation();});
                                                                                                                                                                                                                                                                      var $L=$('<div></div>').css({flex:'0 0 auto',borderRight:'1px solid #ddd',padding:'4px 0'});
                                                                                                                                                                                                                                                                      var $R=$('<div></div>').css({flex:'0 0 auto',padding:'4px 0'});
                                                                                                                                                                                                                                                                      $popup.append($L,$R);
                                                                                                                                                                                                                                                                      function secHdr($col,txt){$col.append($('<div class=\"rp-section-hdr\"></div>').text(txt));}
                                                                                                                                                                                                                                                                      function simpleItem($col,stateObj,mode,label){
                                                                                                                                                                                                                                                                        var $it=$('<div class=\"reorder-popup-item\"></div>').text(label);
                                                                                                                                                                                                                                                                        if(mode===stateObj.mode)$it.addClass('rp-active');
                                                                                                                                                                                                                                                                        $it.on('click',function(){stateObj.mode=mode;stateObj.param='';$('.reorder-popup').remove();var $tbl=$('#__UID__').find('table.pvtTable');applyReorder($tbl);replaceTableValues($tbl);updateFullCode();renderBarChart();});
                                                                                                                                                                                                                                                                        $col.append($it);
                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                      function paramItem($col,stateObj,mode,before,pdef,after,w){
                                                                                                                                                                                                                                                                        var $it=$('<div class=\"reorder-popup-item\"></div>');
                                                                                                                                                                                                                                                                        if(mode===stateObj.mode)$it.addClass('rp-active');
                                                                                                                                                                                                                                                                        var curP=(stateObj.mode===mode&&stateObj.param)?stateObj.param:pdef;
                                                                                                                                                                                                                                                                        var $inp=$('<input type=\"text\" class=\"rp-input\" spellcheck=\"false\">').val(curP).css({width:(w||60)+'px'});
                                                                                                                                                                                                                                                                        var $ok=$('<span class=\"rp-apply\">\\u2713</span>');
                                                                                                                                                                                                                                                                        function apply(){stateObj.mode=mode;stateObj.param=$inp.val().trim();$('.reorder-popup').remove();var $tbl=$('#__UID__').find('table.pvtTable');applyReorder($tbl);replaceTableValues($tbl);updateFullCode();renderBarChart();}
                                                                                                                                                                                                                                                                        $inp.on('keydown',function(e){if(e.key==='Enter')apply();});$inp.on('click',function(e){e.stopPropagation();});$it.on('click',function(){apply();});
                                                                                                                                                                                                                                                                        $it.append($('<span></span>').text(before),$inp,$('<span></span>').text(after),$ok);$col.append($it);
                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                      secHdr($L,'Reorder levels');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'original','Original order (reset)');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'inorder','fct_inorder()  🡒 first appearance');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'alpha','A 🡒 Z   (fct_relevel ... sort)');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'alpha-rev','Z 🡒 A   (fct_relevel ... rev.sort)');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'freq','fct_infreq()  🡒 most frequent first');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'freq-rev','fct_rev(fct_infreq())  🡒 least frequent');
                                                                                                                                                                                                                                                                      simpleItem($L,reorderState,'rev','fct_rev()  🡒 reverse current order');
                                                                                                                                                                                                                                                                      secHdr($R,'Transform levels  (edit param -> Enter / \\u2713)');
                                                                                                                                                                                                                                                                      simpleItem($R,transformState,'none','None (reset transform)');
                                                                                                                                                                                                                                                                      simpleItem($R,transformState,'lowfreq','fct_lump_lowfreq()  🡒 lump infrequent');
                                                                                                                                                                                                                                                                      paramItem($R,transformState,'lump_n',  'fct_lump_n( n = ',      '3',           ' )',    45);
                                                                                                                                                                                                                                                                      paramItem($R,transformState,'lump_min','fct_lump_min( min = ',  '10',          ' )',    45);
                                                                                                                                                                                                                                                                      paramItem($R,transformState,'lump_prop','fct_lump_prop( prop = ','0.1',         ' )',   45);
                                                                                                                                                                                                                                                                      paramItem($R,transformState,'other',   'fct_other( keep = c( ', '\"a\", \"b\"',' ) )', 90);
                                                                                                                                                                                                                                                                      paramItem($R,transformState,'collapse','fct_collapse( ',        'new=c(\"a\",\"b\")',' )',120);
                                                                                                                                                                                                                                                                      simpleItem($R,transformState,'explicit_na','fct_explicit_na()  🡒 NA as a level');
                                                                                                                                                                                                                                                                      $('body').append($popup);
                                                                                                                                                                                                                                                                      var r=$btn[0].getBoundingClientRect();
                                                                                                                                                                                                                                                                      var pivotTop=$('#__UID__')[0].getBoundingClientRect().top;
                                                                                                                                                                                                                                                                      var left=Math.max(0,Math.min(r.left,window.innerWidth-$popup.outerWidth()-10));
                                                                                                                                                                                                                                                                      var top=Math.max(10+window.scrollY,pivotTop+window.scrollY-$popup.outerHeight());
                                                                                                                                                                                                                                                                      $popup.css({top:top,left:left+window.scrollX});
                                                                                                                                                                                                                                                                      setTimeout(function(){$(document).one('click.reorderpop',function(){$('.reorder-popup').remove();});},0);
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    function attachReorderButton($table){
                                                                                                                                                                                                                                                                      $table.find('.reorder-btn').remove();
                                                                                                                                                                                                                                                                      if(!lastCfg||!lastCfg.rows||lastCfg.rows.length===0) return;
                                                                                                                                                                                                                                                                      var firstRowVar=lastCfg.rows[0];
                                                                                                                                                                                                                                                                      var $axis=$table.find('th.pvtAxisLabel').filter(function(){return $(this).text().trim()===firstRowVar;}).first();
                                                                                                                                                                                                                                                                      if(!$axis.length) return;
                                                                                                                                                                                                                                                                      $('<span class=\"reorder-btn\" title=\"Reorder rows (forcats)\"> \\u21c5</span>').appendTo($axis).on('click',function(e){e.stopPropagation();showReorderPopup($(this));});
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                    // -- Stat slot UI ---------------------------------------------------------
                                                                                                                                                                                                                                                                    function buildStatSlotUI(){
                                                                                                                                                                                                                                                                      var $panel=$('#__UID__-slots');
                                                                                                                                                                                                                                                                      $panel.empty();
                                                                                                                                                                                                                                                                      $('<span class=\"stat-slots-lbl\">Statistics:</span>').appendTo($panel);
                                                                                                                                                                                                                                                                      statSlots.forEach(function(slot,idx){
                                                                                                                                                                                                                                                                          var $slot=$('<div class=\"stat-slot\">');
                                                                                                                                                                                                                                                                          $('<span>').css({fontSize:'14px',color:'#888',minWidth:'38px'}).text('Stat '+(idx+1)+':').appendTo($slot);

                                                                                                                                                                                                                                                                          var $vsel=$('<select>');
                                                                                                                                                                                                                                                                          $('<option>').val('').text('--').appendTo($vsel);
                                                                                                                                                                                                                                                                          ALL_VARS.forEach(function(v){$('<option>').val(v).text(v).appendTo($vsel);});
                                                                                                                                                                                                                                                                          $vsel.val(slot.varName);
                                                                                                                                                                                                                                                                          $slot.append($vsel);

                                                                                                                                                                                                                                                                          $('<span class=\"stat-slot-sep\">').text('\\u25b8').appendTo($slot);

                                                                                                                                                                                                                                                                          var $asel=$('<select>');
                                                                                                                                                                                                                                                                          ALL_AGGS.forEach(function(a){$('<option>').val(a).text(a).appendTo($asel);});
                                                                                                                                                                                                                                                                          $asel.val(slot.aggName);
                                                                                                                                                                                                                                                                          $slot.append($asel);

                                                                                                                                                                                                                                                                          function applySlot(){
                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                              slot.varName=$vsel.val(); slot.aggName=$asel.val();
                                                                                                                                                                                                                                                                              if(lastCfg){
                                                                                                                                                                                                                                                                                var $tbl=$('#__UID__').find('table.pvtTable');
                                                                                                                                                                                                                                                                                if(!$tbl.length){ console.warn('pvtTable not found for __UID__'); return; }
                                                                                                                                                                                                                                                                                applyReorder($tbl); replaceTableValues($tbl);
                                                                                                                                                                                                                                                                                updateFullCode(); renderBarChart();
                                                                                                                                                                                                                                                                                var c=makeCode(lastCfg); $('#__WID__').text(c.wide); $('#__LID__').text(c.long);
                                                                                                                                                                                                                                                                                if ($('#__UID__-longform-popup').is(':visible')) _refreshLongForm(lastCfg);
                                                                                                                                                                                                                                                                                saveStateToHash();
                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                            } catch(e) {
                                                                                                                                                                                                                                                                              var dbg=document.getElementById('__UID__-dbg');
                                                                                                                                                                                                                                                                              if(dbg) dbg.textContent='Stat error: '+(e&&(e.stack||e.message)||String(e));
                                                                                                                                                                                                                                                                              console.error('applySlot error',e);
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                          $vsel.on('change',applySlot); $asel.on('change',applySlot);
                                                                                                                                                                                                                                                                          $panel.append($slot);
                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                      // -- Column-role annotations (llm_hints) ----------------------------------
                                                                                                                                                                                                                                                                      var _roleColor = {
                                                                                                                                                                                                                                                                        'measure':       '#4472C4',
                                                                                                                                                                                                                                                                        'grouping':      '#70AD47',
                                                                                                                                                                                                                                                                        'bin-candidate': '#ED7D31',
                                                                                                                                                                                                                                                                        'id':            '#A0A0A0',
                                                                                                                                                                                                                                                                        'datetime':      '#7030A0'
                                                                                                                                                                                                                                                                      };
                                                                                                                                                                                                                                                                      function applyColAnnotations() {
                                                                                                                                                                                                                                                                        if (!colAnnotations || !Object.keys(colAnnotations).length) return;
                                                                                                                                                                                                                                                                        $('#__UID__ .pvtAttr, #__UID__-varmatrix .pvtAttr').each(function() {
                                                                                                                                                                                                                                                                            var $el = $(this);
                                                                                                                                                                                                                                                                            var name = $el.clone().children().remove().end().text().trim();
                                                                                                                                                                                                                                                                            var ann = colAnnotations[name];
                                                                                                                                                                                                                                                                            if (!ann) return;
                                                                                                                                                                                                                                                                            var color = _roleColor[ann.role] || '#888';
                                                                                                                                                                                                                                                                            $el.attr('data-pv-hint', '[' + ann.role + '] ' + (ann.hint || ''));
                                                                                                                                                                                                                                                                            if (!$el.find('.pv-role-dot').length) {
                                                                                                                                                                                                                                                                              $el.prepend('<span class=\"pv-role-dot\" style=\"background:' + color + '\"></span>');
                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        // -- Undo / redo ----------------------------------------------------------
                                                                                                                                                                                                                                                                        function updateUndoRedoButtons() {
                                                                                                                                                                                                                                                                          var $u = $('#__UID__-undo-btn'), $r = $('#__UID__-redo-btn'), $l = $('#__UID__-undoredo-lbl');
                                                                                                                                                                                                                                                                          $u.prop('disabled', historyIdx <= 0);
                                                                                                                                                                                                                                                                          $r.prop('disabled', historyIdx >= stateHistory.length - 1);
                                                                                                                                                                                                                                                                          if (stateHistory.length > 0) {
                                                                                                                                                                                                                                                                            $l.text((historyIdx + 1) + '/' + stateHistory.length);
                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                            $l.text('');
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        function pushHistory(st) {
                                                                                                                                                                                                                                                                          var snap = JSON.parse(JSON.stringify(st));
                                                                                                                                                                                                                                                                          var head = stateHistory[historyIdx];
                                                                                                                                                                                                                                                                          if (head && JSON.stringify(head) === JSON.stringify(snap)) return;
                                                                                                                                                                                                                                                                          stateHistory = stateHistory.slice(0, historyIdx + 1);
                                                                                                                                                                                                                                                                          stateHistory.push(snap);
                                                                                                                                                                                                                                                                          if (stateHistory.length > 50) stateHistory.shift();
                                                                                                                                                                                                                                                                          historyIdx = stateHistory.length - 1;
                                                                                                                                                                                                                                                                          updateUndoRedoButtons();
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        function applyState(st) {
                                                                                                                                                                                                                                                                          if (Array.isArray(st.statSlots)) statSlots = JSON.parse(JSON.stringify(st.statSlots));
                                                                                                                                                                                                                                                                          if (st.filterState && typeof st.filterState === 'object') filterState = JSON.parse(JSON.stringify(st.filterState));
                                                                                                                                                                                                                                                                          if (st.binConfigs && typeof st.binConfigs === 'object') { binConfigs = JSON.parse(JSON.stringify(st.binConfigs)); rebuildWorkData(); }
                                                                                                                                                                                                                                                                          if (st.sortState && typeof st.sortState === 'object') _restoreSortState = st.sortState.colIdx !== -1 ? JSON.parse(JSON.stringify(st.sortState)) : null;
                                                                                                                                                                                                                                                                          if (st.rowSortState && typeof st.rowSortState === 'object') _restoreRowSortState = st.rowSortState.rowIdx >= 0 ? JSON.parse(JSON.stringify(st.rowSortState)) : null;
                                                                                                                                                                                                                                                                          if (st.reorderState && typeof st.reorderState === 'object') reorderState = JSON.parse(JSON.stringify(st.reorderState));
                                                                                                                                                                                                                                                                          if (st.transformState && typeof st.transformState === 'object') transformState = JSON.parse(JSON.stringify(st.transformState));
                                                                                                                                                                                                                                                                          if (typeof st.chartStatIdx === 'number') chartStatIdx = st.chartStatIdx;
                                                                                                                                                                                                                                                                          if (typeof st.chartFacet === 'boolean') chartFacet = st.chartFacet;
                                                                                                                                                                                                                                                                          if (typeof st.chartFreeY === 'boolean') chartFreeY = st.chartFreeY;
                                                                                                                                                                                                                                                                          if (typeof st.chartRowFacet === 'boolean') chartRowFacet = st.chartRowFacet;
                                                                                                                                                                                                                                                                          if (typeof st.binscatterMode === 'boolean') binscatterMode = st.binscatterMode;
                                                                                                                                                                                                                                                                          if (typeof st.numBinscatterMode === 'boolean') numBinscatterMode = st.numBinscatterMode;
                                                                                                                                                                                                                                                                          if (typeof st.boxplotMode === 'boolean') boxplotMode = st.boxplotMode;
                                                                                                                                                                                                                                                                          if (typeof st.regGroupVar === 'string') { regGroupVar = st.regGroupVar; $('#__UID__-reg-group').val(regGroupVar); }
                                                                                                                                                                                                                                                                          if (typeof st.regXVar === 'string') { regXVar = st.regXVar; $('#__UID__-reg-x').val(regXVar); }
                                                                                                                                                                                                                                                                          if (typeof st.regYVar === 'string') { regYVar = st.regYVar; $('#__UID__-reg-y').val(regYVar); }
                                                                                                                                                                                                                                                                          if (typeof st.activeTab === 'string' && st.activeTab === 'regression') {
                                                                                                                                                                                                                                                                            activeTab = 'regression';
                                                                                                                                                                                                                                                                            $('#__UID__-tab-pivot').removeClass('active');
                                                                                                                                                                                                                                                                            $('#__UID__-tab-reg').addClass('active');
                                                                                                                                                                                                                                                                            $('#__UID__-pivot-tab-content').hide();
                                                                                                                                                                                                                                                                            $('#__UID__-reg-tab-content').show();
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                          if (typeof st.horizontal === 'boolean') horizontal = st.horizontal;
                                                                                                                                                                                                                                                                          if (st.widerOpts && typeof st.widerOpts === 'object') {
                                                                                                                                                                                                                                                                            widerOpts = JSON.parse(JSON.stringify(st.widerOpts));
                                                                                                                                                                                                                                                                            $('#__UID__-names-sort').prop('checked', !!widerOpts.namesSort);
                                                                                                                                                                                                                                                                            $('#__UID__-values-fill').val(widerOpts.valuesFill || '');
                                                                                                                                                                                                                                                                            $('#__UID__-names-glue').val(widerOpts.namesGlue || '');
                                                                                                                                                                                                                                                                            $('#__UID__-values-fn').prop('checked', !!widerOpts.valuesFn);
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                          updateFilterMarkers();
                                                                                                                                                                                                                                                                          buildStatSlotUI();
                                                                                                                                                                                                                                                                          var cfg = { rows: [], cols: [], onRefresh: onRefreshFn };
                                                                                                                                                                                                                                                                          if (Array.isArray(st.rows)) cfg.rows = JSON.parse(JSON.stringify(st.rows));
                                                                                                                                                                                                                                                                          if (Array.isArray(st.cols)) cfg.cols = JSON.parse(JSON.stringify(st.cols));
                                                                                                                                                                                                                                                                          if (st.rendererName) cfg.rendererName = st.rendererName;
                                                                                                                                                                                                                                                                          if (st.inclusions && typeof st.inclusions === 'object') cfg.inclusions = JSON.parse(JSON.stringify(st.inclusions));
                                                                                                                                                                                                                                                                          if (st.exclusions && typeof st.exclusions === 'object') cfg.exclusions = JSON.parse(JSON.stringify(st.exclusions));
                                                                                                                                                                                                                                                                          $('#__UID__').pivotUI(computeFilteredData(), cfg, true);
                                                                                                                                                                                                                                                                          updateBinSection();
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        function undoState() {
                                                                                                                                                                                                                                                                          if (historyIdx <= 0) return;
                                                                                                                                                                                                                                                                          _historyMuted = true;
                                                                                                                                                                                                                                                                          historyIdx--;
                                                                                                                                                                                                                                                                          applyState(stateHistory[historyIdx]);
                                                                                                                                                                                                                                                                          _historyMuted = false;
                                                                                                                                                                                                                                                                          updateUndoRedoButtons();
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        function redoState() {
                                                                                                                                                                                                                                                                          if (historyIdx >= stateHistory.length - 1) return;
                                                                                                                                                                                                                                                                          _historyMuted = true;
                                                                                                                                                                                                                                                                          historyIdx++;
                                                                                                                                                                                                                                                                          applyState(stateHistory[historyIdx]);
                                                                                                                                                                                                                                                                          _historyMuted = false;
                                                                                                                                                                                                                                                                          updateUndoRedoButtons();
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        // -- URL hash state persistence -------------------------------------------
                                                                                                                                                                                                                                                                        function saveStateToHash() {
                                                                                                                                                                                                                                                                          var st = {
                                                                                                                                                                                                                                                                            v: 1,
                                                                                                                                                                                                                                                                            statSlots: statSlots,
                                                                                                                                                                                                                                                                            filterState: filterState,
                                                                                                                                                                                                                                                                            binConfigs: binConfigs,
                                                                                                                                                                                                                                                                            sortState: sortState,
                                                                                                                                                                                                                                                                            rowSortState: rowSortState,
                                                                                                                                                                                                                                                                            reorderState: reorderState,
                                                                                                                                                                                                                                                                            transformState: transformState,
                                                                                                                                                                                                                                                                            chartStatIdx: chartStatIdx,
                                                                                                                                                                                                                                                                            chartFacet: chartFacet,
                                                                                                                                                                                                                                                                            chartFreeY: chartFreeY,
                                                                                                                                                                                                                                                                            chartRowFacet: chartRowFacet,
                                                                                                                                                                                                                                                                            binscatterMode: binscatterMode,
                                                                                                                                                                                                                                                                            numBinscatterMode: numBinscatterMode,
                                                                                                                                                                                                                                                                            boxplotMode: boxplotMode,
                                                                                                                                                                                                                                                                            regGroupVar: regGroupVar,
                                                                                                                                                                                                                                                                            regXVar: regXVar,
                                                                                                                                                                                                                                                                            regYVar: regYVar,
                                                                                                                                                                                                                                                                            activeTab: activeTab,
                                                                                                                                                                                                                                                                            horizontal: horizontal,
                                                                                                                                                                                                                                                                            widerOpts: widerOpts
                                                                                                                                                                                                                                                                          };
                                                                                                                                                                                                                                                                          if (lastCfg) {
                                                                                                                                                                                                                                                                            st.rows = lastCfg.rows || [];
                                                                                                                                                                                                                                                                            st.cols = lastCfg.cols || [];
                                                                                                                                                                                                                                                                            st.rendererName = lastCfg.rendererName || '';
                                                                                                                                                                                                                                                                            st.inclusions = lastCfg.inclusions || {};
                                                                                                                                                                                                                                                                            st.exclusions = lastCfg.exclusions || {};
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                          if (!_historyMuted) pushHistory(st);
                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                            var enc = btoa(unescape(encodeURIComponent(JSON.stringify(st))));
                                                                                                                                                                                                                                                                            window.history.replaceState(null, '', '#pv__UID__=' + enc);
                                                                                                                                                                                                                                                                          } catch(e) {}
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        function loadStateFromHash() {
                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                            var hash = window.location.hash.slice(1);
                                                                                                                                                                                                                                                                            if (!hash) return null;
                                                                                                                                                                                                                                                                            var prefix = 'pv__UID__=';
                                                                                                                                                                                                                                                                            if (hash.indexOf(prefix) !== 0) return null;
                                                                                                                                                                                                                                                                            var st = JSON.parse(decodeURIComponent(escape(atob(hash.slice(prefix.length)))));
                                                                                                                                                                                                                                                                            // 清洗 binConfigs：移除那些原始数据中已经不存在的变量对应的分箱配置
                                                                                                                                                                                                                                                                            if (st.binConfigs && typeof st.binConfigs === 'object') {
                                                                                                                                                                                                                                                                              var validBinConfigs = {};
                                                                                                                                                                                                                                                                              Object.keys(st.binConfigs).forEach(function(outCol) {
                                                                                                                                                                                                                                                                                  var cfg = st.binConfigs[outCol];
                                                                                                                                                                                                                                                                                  var src = cfg && cfg.source;
                                                                                                                                                                                                                                                                                  if (src && data.length > 0 && data[0].hasOwnProperty(src)) {
                                                                                                                                                                                                                                                                                    validBinConfigs[outCol] = cfg;
                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                st.binConfigs = validBinConfigs;
                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                              // 可选：清洗 filterState 中可能引用了无效变量的条目（防止残留）
                                                                                                                                                                                                                                                                              if (st.filterState && typeof st.filterState === 'object') {
                                                                                                                                                                                                                                                                                var validFilterState = {};
                                                                                                                                                                                                                                                                                Object.keys(st.filterState).forEach(function(v) {
                                                                                                                                                                                                                                                                                    if (data.length > 0 && data[0].hasOwnProperty(v)) {
                                                                                                                                                                                                                                                                                      validFilterState[v] = st.filterState[v];
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                  st.filterState = validFilterState;
                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                return st;
                                                                                                                                                                                                                                                                              } catch(e) { return null; }
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                            // -- onRefresh ------------------------------------------------------------
                                                                                                                                                                                                                                                                            function onRefreshFn(cfg){
                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                $('#__UID__ .pvtVals, #__UID__ .pvtAggregator').css({opacity:0,pointerEvents:'none'});
                                                                                                                                                                                                                                                                                lastCfg=cfg;
                                                                                                                                                                                                                                                                                var c=makeCode(cfg);
                                                                                                                                                                                                                                                                                $('#__WID__').text(c.wide); $('#__LID__').text(c.long);
                                                                                                                                                                                                                                                                                var $tbl=$('#__UID__').find('table.pvtTable');
                                                                                                                                                                                                                                                                                var $tb=$tbl.find('tbody');
                                                                                                                                                                                                                                                                                pristineTbodyHTML=$tb.length?$tb[0].outerHTML:null;
                                                                                                                                                                                                                                                                                attachSort($tbl);
                                                                                                                                                                                                                                                                                applyReorder($tbl);
                                                                                                                                                                                                                                                                                replaceTableValues($tbl);
                                                                                                                                                                                                                                                                                attachReorderButton($tbl);

                                                                                                                                                                                                                                                                                if (_restoreSortState) {
                                                                                                                                                                                                                                                                                  var _psr = _restoreSortState; _restoreSortState = null;
                                                                                                                                                                                                                                                                                  if (_psr.colIdx === null) {
                                                                                                                                                                                                                                                                                    var $colRow_r = $tbl.find('th.pvtColLabel,th.pvtAxisLabel').first().closest('tr');
                                                                                                                                                                                                                                                                                    var $th0 = $colRow_r.length ? $colRow_r.find('th.pvtTotalLabel') : $tbl.find('th.pvtTotalLabel').first();
