                                                                                                                                                                                                                                                                                              if (_savedState && _savedState.v === 1) {
                                                                                                                                                                                                                                                                                                if (Array.isArray(_savedState.rows)) _pvCfg.rows = _savedState.rows;
                                                                                                                                                                                                                                                                                                if (Array.isArray(_savedState.cols)) _pvCfg.cols = _savedState.cols;
                                                                                                                                                                                                                                                                                                if (_savedState.rendererName) _pvCfg.rendererName = _savedState.rendererName;
                                                                                                                                                                                                                                                                                                if (_savedState.inclusions && typeof _savedState.inclusions === 'object') _pvCfg.inclusions = _savedState.inclusions;
