                                                                                                                                                                                                                                                                                                showCategoricalFilterPopup(varName, $tri);
                                                                                                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                              // -- Boxplot renderer --------------------------------------------------------
                                                                                                                                                                                                                                                                                              function renderBoxplot(slot) {
                                                                                                                                                                                                                                                                                                var rows = (lastCfg && lastCfg.rows) || [];
                                                                                                                                                                                                                                                                                                var cols = (lastCfg && lastCfg.cols) || [];
                                                                                                                                                                                                                                                                                                var yKey = slot.varName;
                                                                                                                                                                                                                                                                                                var PALETTE = ['#4472C4','#70AD47','#C55A11','#FFC000','#5B9BD5','#A5A5A5','#FF0000','#7030A0'];
                                                                                                                                                                                                                                                                                                var fd = computeFilteredData();
                                                                                                                                                                                                                                                                                                var inc = (lastCfg && lastCfg.inclusions) || {};
                                                                                                                                                                                                                                                                                                var exc = (lastCfg && lastCfg.exclusions) || {};
                                                                                                                                                                                                                                                                                                fd = fd.filter(function(row) {
                                                                                                                                                                                                                                                                                                    return Object.keys(inc).every(function(v) {
                                                                                                                                                                                                                                                                                                        return !inc[v] || !inc[v].length || inc[v].indexOf(String(row[v])) !== -1;
                                                                                                                                                                                                                                                                                                      }) && Object.keys(exc).every(function(v) {
                                                                                                                                                                                                                                                                                                          return !exc[v] || !exc[v].length || exc[v].indexOf(String(row[v])) === -1;
                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                      if (rows.length && transformState.mode !== 'none') {
                                                                                                                                                                                                                                                                                                        fd = transformDataRows(fd, rows[0], transformState);
                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                      function _bpFmt(v) {
                                                                                                                                                                                                                                                                                                        return typeof v === 'number' ? (Math.round(v * 1000) / 1000) + '' : String(v);
                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                      function _bpStats(raw) {
                                                                                                                                                                                                                                                                                                        var vals = raw.filter(function(v){ return typeof v === 'number' && isFinite(v); }).sort(function(a,b){ return a-b; });
                                                                                                                                                                                                                                                                                                        var n = vals.length;
                                                                                                                                                                                                                                                                                                        if (!n) return null;
                                                                                                                                                                                                                                                                                                        var pct = function(p) { var i = p * (n-1), lo = Math.floor(i), hi = Math.ceil(i); return lo===hi ? vals[lo] : vals[lo] + (vals[hi]-vals[lo])*(i-lo); };
                                                                                                                                                                                                                                                                                                        var q1 = pct(0.25), q3 = pct(0.75), iqr = q3-q1, fence = 1.5*iqr;
                                                                                                                                                                                                                                                                                                        var inner = vals.filter(function(v){ return v >= q1-fence && v <= q3+fence; });
                                                                                                                                                                                                                                                                                                        var out = vals.filter(function(v){ return v < q1-fence || v > q3+fence; });
                                                                                                                                                                                                                                                                                                        return { min: inner.length ? inner[0] : vals[0], q1: q1, median: pct(0.5),
                                                                                                                                                                                                                                                                                                          mean: vals.reduce(function(a,b){ return a+b; },0)/n,
                                                                                                                                                                                                                                                                                                          q3: q3, max: inner.length ? inner[inner.length-1] : vals[n-1], outliers: out };
                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                        var bpTooltip = { callbacks: { label: function(ctx) {
                                                                                                                                                                                                                                                                                                              var r = ctx.raw;
                                                                                                                                                                                                                                                                                                              if (Array.isArray(r)) r = _bpStats(r);
                                                                                                                                                                                                                                                                                                              if (!r || typeof r !== 'object') return String(ctx.dataset.label || '');
                                                                                                                                                                                                                                                                                                              var lines = [String(ctx.dataset.label || '') + ':'];
                                                                                                                                                                                                                                                                                                              if (r.max    != null) lines.push('  Max:    ' + _bpFmt(r.max));
                                                                                                                                                                                                                                                                                                              if (r.q3     != null) lines.push('  Q3:     ' + _bpFmt(r.q3));
                                                                                                                                                                                                                                                                                                              if (r.median != null) lines.push('  Median: ' + _bpFmt(r.median));
                                                                                                                                                                                                                                                                                                              if (r.mean   != null) lines.push('  Mean:   ' + _bpFmt(r.mean));
                                                                                                                                                                                                                                                                                                              if (r.q1     != null) lines.push('  Q1:     ' + _bpFmt(r.q1));
                                                                                                                                                                                                                                                                                                              if (r.min    != null) lines.push('  Min:    ' + _bpFmt(r.min));
                                                                                                                                                                                                                                                                                                              if (Array.isArray(r.outliers) && r.outliers.length) {
                                                                                                                                                                                                                                                                                                                lines.push('  Outliers (' + r.outliers.length + '):');
                                                                                                                                                                                                                                                                                                                var strs = r.outliers.map(_bpFmt);
                                                                                                                                                                                                                                                                                                                var cur = '    ';
                                                                                                                                                                                                                                                                                                                strs.forEach(function(s, i) {
                                                                                                                                                                                                                                                                                                                    var sep = i === 0 ? '' : ', ';
                                                                                                                                                                                                                                                                                                                    if (cur.length + sep.length + s.length > 48 && cur.trim().length > 0) {
                                                                                                                                                                                                                                                                                                                      lines.push(cur); cur = '    ' + s;
                                                                                                                                                                                                                                                                                                                    } else { cur += sep + s; }
                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                  if (cur.trim().length) lines.push(cur);
                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                return lines;
                                                                                                                                                                                                                                                                                                              }}};

                                                                                                                                                                                                                                                                                                              // 获取 DOM 中当前的行标签键（使用 '||' 分隔，与 replaceTableValues 一致）
                                                                                                                                                                                                                                                                                                              function getDisplayRowKeys() {
                                                                                                                                                                                                                                                                                                                var $tbl = $('#__UID__ .pvtTable');
                                                                                                                                                                                                                                                                                                                var keys = [];
                                                                                                                                                                                                                                                                                                                $tbl.find('tbody tr').each(function() {
                                                                                                                                                                                                                                                                                                                    var $tr = $(this);
                                                                                                                                                                                                                                                                                                                    var $lbls = $tr.find('.pvtRowLabel');
                                                                                                                                                                                                                                                                                                                    if (!$lbls.length) return;
                                                                                                                                                                                                                                                                                                                    var key = $lbls.map(function(){
                                                                                                                                                                                                                                                                                                                        return $(this).clone().find('.sort-arrow').remove().end().text().trim();
                                                                                                                                                                                                                                                                                                                      }).get().join('||');
                                                                                                                                                                                                                                                                                                                      if (keys.indexOf(key) === -1) keys.push(key);
                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                    return keys;
                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                  // 聚合数据：按显示行键和栏变量分组
                                                                                                                                                                                                                                                                                                                  function aggregateData(fd, displayRowKeys, colKeys) {
                                                                                                                                                                                                                                                                                                                    var dataMap = {};
                                                                                                                                                                                                                                                                                                                    colKeys.forEach(function(ck) {
                                                                                                                                                                                                                                                                                                                        dataMap[ck] = {};
                                                                                                                                                                                                                                                                                                                        displayRowKeys.forEach(function(key) {
                                                                                                                                                                                                                                                                                                                            dataMap[ck][key] = [];
                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                        fd.forEach(function(row) {
                                                                                                                                                                                                                                                                                                                            var val = row[yKey];
                                                                                                                                                                                                                                                                                                                            if (val == null || isNaN(+val)) return;
                                                                                                                                                                                                                                                                                                                            // 构造行键（与 DOM 中的键一致）
                                                                                                                                                                                                                                                                                                                            var rowParts = rows.map(function(v) {
                                                                                                                                                                                                                                                                                                                                var raw = row[v];
                                                                                                                                                                                                                                                                                                                                return (raw == null) ? '(NA)' : String(raw);
                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                              var rowKey = rowParts.join('||');
                                                                                                                                                                                                                                                                                                                              // 构造栏键
                                                                                                                                                                                                                                                                                                                              var colKey = cols.length ? cols.map(function(v){
                                                                                                                                                                                                                                                                                                                                  var raw = row[v];
                                                                                                                                                                                                                                                                                                                                  return (raw == null) ? '(NA)' : String(raw);
                                                                                                                                                                                                                                                                                                                                }).join('||') : '__ALL__';
                                                                                                                                                                                                                                                                                                                                if (dataMap[colKey] && dataMap[colKey][rowKey] !== undefined) {
                                                                                                                                                                                                                                                                                                                                  dataMap[colKey][rowKey].push(+val);
                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                              return dataMap;
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                            // --- 分面处理 (chartFacet) ---
                                                                                                                                                                                                                                                                                                                            if (chartFacet && cols.length >= 1) {
                                                                                                                                                                                                                                                                                                                              var colGroups = {}, colOrder2 = [];
                                                                                                                                                                                                                                                                                                                              fd.forEach(function(row) {
                                                                                                                                                                                                                                                                                                                                  var ck = cols.map(function(v){ return String(row[v]!=null?row[v]:'(NA)'); }).join(' / ');
                                                                                                                                                                                                                                                                                                                                  if (!colGroups[ck]) { colGroups[ck] = []; colOrder2.push(ck); }
                                                                                                                                                                                                                                                                                                                                  colGroups[ck].push(row);
                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                var $c2 = $('#__UID__-chart-container');
                                                                                                                                                                                                                                                                                                                                $c2.empty().removeClass('pv-facet-grid').css({position:'',height:''});
                                                                                                                                                                                                                                                                                                                                if (!colOrder2.length) { $c2.html('<p class=\"pv-boxplot-note\">No data to display.</p>'); return; }
                                                                                                                                                                                                                                                                                                                                $c2.addClass('pv-facet-grid');
                                                                                                                                                                                                                                                                                                                                var bpH2 = Math.max(180, Math.min(260, 320 - colOrder2.length * 8));
                                                                                                                                                                                                                                                                                                                                var displayRowKeys = getDisplayRowKeys();
                                                                                                                                                                                                                                                                                                                                colOrder2.forEach(function(ck) {
                                                                                                                                                                                                                                                                                                                                    var colRows = colGroups[ck];
                                                                                                                                                                                                                                                                                                                                    var dataMap = {};
                                                                                                                                                                                                                                                                                                                                    displayRowKeys.forEach(function(key) { dataMap[key] = []; });
                                                                                                                                                                                                                                                                                                                                    colRows.forEach(function(row) {
                                                                                                                                                                                                                                                                                                                                        var val = row[yKey];
                                                                                                                                                                                                                                                                                                                                        if (val == null || isNaN(+val)) return;
                                                                                                                                                                                                                                                                                                                                        var rowParts = rows.map(function(v) {
                                                                                                                                                                                                                                                                                                                                            var raw = row[v];
                                                                                                                                                                                                                                                                                                                                            return (raw == null) ? '(NA)' : String(raw);
                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                          var rowKey = rowParts.join('||');
                                                                                                                                                                                                                                                                                                                                          if (dataMap[rowKey] !== undefined) dataMap[rowKey].push(+val);
                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                        var $panel2 = $('<div class=\"pv-facet-panel\"></div>');
                                                                                                                                                                                                                                                                                                                                        $panel2.append('<div class=\"pv-facet-lbl\">' + ck + '</div>');
                                                                                                                                                                                                                                                                                                                                        var $cw2 = $('<div>').css({position:'relative', height:bpH2+'px'});
                                                                                                                                                                                                                                                                                                                                        var cv2 = $('<canvas>')[0]; $cw2.append(cv2); $panel2.append($cw2);
                                                                                                                                                                                                                                                                                                                                        $c2.append($panel2);
                                                                                                                                                                                                                                                                                                                                        chartInstances.push(new Chart(cv2, {
                                                                                                                                                                                                                                                                                                                                              type: 'boxplot',
                                                                                                                                                                                                                                                                                                                                              data: { labels: displayRowKeys, datasets: [{ label: yKey,
                                                                                                                                                                                                                                                                                                                                                    data: displayRowKeys.map(function(key) { return dataMap[key] || []; }),
                                                                                                                                                                                                                                                                                                                                                    backgroundColor: PALETTE[0]+'88', borderColor: PALETTE[0], borderWidth: 1,
                                                                                                                                                                                                                                                                                                                                                    outlierBackgroundColor: PALETTE[0], outlierRadius: 3 }] },
                                                                                                                                                                                                                                                                                                                                                    options: {
                                                                                                                                                                                                                                                                                                                                                      indexAxis: horizontal ? 'y' : 'x', maintainAspectRatio: false, responsive: true,
                                                                                                                                                                                                                                                                                                                                                      plugins: { legend: { display: false }, title: { display: false }, tooltip: bpTooltip },
                                                                                                                                                                                                                                                                                                                                                      scales: { x: { ticks: { font: { size: 10 }, maxRotation: horizontal ? 0 : 45 } }, y: { ticks: { font: { size: 10 } } } }
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                  }));
                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                var _r = _chartDataRange(); if (_r) _updateYSlider(_r.min,_r.max); _applyYAxisLimits();
                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                              // --- 行分面 (chartRowFacet) ---
                                                                                                                                                                                                                                                                                                                                              if (chartRowFacet && rows.length >= 2) {
                                                                                                                                                                                                                                                                                                                                                var $pvtTbl = $('#__UID__ .pvtTable');
                                                                                                                                                                                                                                                                                                                                                var bpOuter = {}, bpOuterOrder = [], bpCurOuter = null;
                                                                                                                                                                                                                                                                                                                                                if ($pvtTbl.length) {
                                                                                                                                                                                                                                                                                                                                                  $pvtTbl.find('tbody tr').each(function() {
                                                                                                                                                                                                                                                                                                                                                      var $tr = $(this);
                                                                                                                                                                                                                                                                                                                                                      var $rl = $tr.find('.pvtRowLabel');
                                                                                                                                                                                                                                                                                                                                                      if (!$rl.length) return;
                                                                                                                                                                                                                                                                                                                                                      var rlArr = $rl.map(function(){
                                                                                                                                                                                                                                                                                                                                                          return $(this).clone().find('.sort-arrow').remove().end().text().trim();
                                                                                                                                                                                                                                                                                                                                                        }).get();
                                                                                                                                                                                                                                                                                                                                                        var innerLbl;
                                                                                                                                                                                                                                                                                                                                                        if (rlArr.length >= 2) { bpCurOuter = rlArr[0]; innerLbl = rlArr.slice(1).join('||'); }
                                                                                                                                                                                                                                                                                                                                                        else { innerLbl = rlArr[0]; }
                                                                                                                                                                                                                                                                                                                                                        if (bpCurOuter === null) return;
                                                                                                                                                                                                                                                                                                                                                        if (!bpOuter[bpCurOuter]) { bpOuter[bpCurOuter] = { innerKeys: [], innerSet: {}, colData: {} }; bpOuterOrder.push(bpCurOuter); }
                                                                                                                                                                                                                                                                                                                                                        var og = bpOuter[bpCurOuter];
                                                                                                                                                                                                                                                                                                                                                        if (!og.innerSet[innerLbl]) { og.innerSet[innerLbl] = true; og.innerKeys.push(innerLbl); }
                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                    var bpColOrder = {}, bpColKeys = [];
                                                                                                                                                                                                                                                                                                                                                    fd.forEach(function(row) {
                                                                                                                                                                                                                                                                                                                                                        var val = row[yKey]; if (val == null || isNaN(+val)) return;
                                                                                                                                                                                                                                                                                                                                                        var outerKey = String(row[rows[0]] != null ? row[rows[0]] : '(NA)');
                                                                                                                                                                                                                                                                                                                                                        var innerParts = rows.slice(1).map(function(v){ return String(row[v]!=null?row[v]:'(NA)'); });
                                                                                                                                                                                                                                                                                                                                                        var innerKey = innerParts.join('||');
                                                                                                                                                                                                                                                                                                                                                        var ck = cols.length ? cols.map(function(v){ return String(row[v]!=null?row[v]:'(NA)'); }).join('||') : '__ALL__';
                                                                                                                                                                                                                                                                                                                                                        if (!bpColOrder.hasOwnProperty(ck)) { bpColOrder[ck] = bpColKeys.length; bpColKeys.push(ck); }
                                                                                                                                                                                                                                                                                                                                                        if (!bpOuter[outerKey]) return;
                                                                                                                                                                                                                                                                                                                                                        var og = bpOuter[outerKey];
                                                                                                                                                                                                                                                                                                                                                        if (!og.colData[ck]) og.colData[ck] = {};
                                                                                                                                                                                                                                                                                                                                                        if (!og.colData[ck][innerKey]) og.colData[ck][innerKey] = [];
                                                                                                                                                                                                                                                                                                                                                        og.colData[ck][innerKey].push(+val);
                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                      var $c = $('#__UID__-chart-container');
                                                                                                                                                                                                                                                                                                                                                      $c.empty().removeClass('pv-facet-grid').css({position:'',height:''});
                                                                                                                                                                                                                                                                                                                                                      if (!bpOuterOrder.length) { $c.html('<p class=\"pv-boxplot-note\">No data to display.</p>'); return; }
                                                                                                                                                                                                                                                                                                                                                      $c.addClass('pv-facet-grid');
                                                                                                                                                                                                                                                                                                                                                      var bpH = Math.max(180, Math.min(260, 320 - bpOuterOrder.length * 8));
                                                                                                                                                                                                                                                                                                                                                      bpOuterOrder.forEach(function(outerKey) {
                                                                                                                                                                                                                                                                                                                                                          var og = bpOuter[outerKey];
                                                                                                                                                                                                                                                                                                                                                          var $panel = $('<div class=\"pv-facet-panel\"></div>');
                                                                                                                                                                                                                                                                                                                                                          $panel.append('<div class=\"pv-facet-lbl\">' + outerKey + '</div>');
                                                                                                                                                                                                                                                                                                                                                          var $cw = $('<div>').css({position:'relative', height:bpH+'px'});
                                                                                                                                                                                                                                                                                                                                                          var cv = $('<canvas>')[0]; $cw.append(cv); $panel.append($cw);
                                                                                                                                                                                                                                                                                                                                                          $c.append($panel);
                                                                                                                                                                                                                                                                                                                                                          var dsets;
                                                                                                                                                                                                                                                                                                                                                          if (cols.length === 0) {
                                                                                                                                                                                                                                                                                                                                                            dsets = [{ label: yKey,
                                                                                                                                                                                                                                                                                                                                                                data: og.innerKeys.map(function(ik){ return (og.colData['__ALL__'] && og.colData['__ALL__'][ik]) || []; }),
                                                                                                                                                                                                                                                                                                                                                                backgroundColor: PALETTE[0]+'88', borderColor: PALETTE[0], borderWidth: 1,
                                                                                                                                                                                                                                                                                                                                                                outlierBackgroundColor: PALETTE[0], outlierRadius: 3 }];
                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                dsets = bpColKeys.map(function(ck,ci){
                                                                                                                                                                                                                                                                                                                                                                    return { label: ck,
                                                                                                                                                                                                                                                                                                                                                                      data: og.innerKeys.map(function(ik){ return (og.colData[ck] && og.colData[ck][ik]) || []; }),
                                                                                                                                                                                                                                                                                                                                                                      backgroundColor: PALETTE[ci%PALETTE.length]+'88',
                                                                                                                                                                                                                                                                                                                                                                      borderColor: PALETTE[ci%PALETTE.length], borderWidth: 1,
                                                                                                                                                                                                                                                                                                                                                                      outlierBackgroundColor: PALETTE[ci%PALETTE.length], outlierRadius: 3 };
                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                  chartInstances.push(new Chart(cv, {
                                                                                                                                                                                                                                                                                                                                                                        type: 'boxplot',
                                                                                                                                                                                                                                                                                                                                                                        data: { labels: og.innerKeys, datasets: dsets },
                                                                                                                                                                                                                                                                                                                                                                        options: {
                                                                                                                                                                                                                                                                                                                                                                          indexAxis: horizontal ? 'y' : 'x',
                                                                                                                                                                                                                                                                                                                                                                          maintainAspectRatio: false, responsive: true,
                                                                                                                                                                                                                                                                                                                                                                          plugins: {
                                                                                                                                                                                                                                                                                                                                                                            legend: { display: dsets.length > 1, position: 'top' },
                                                                                                                                                                                                                                                                                                                                                                            title: { display: false },
                                                                                                                                                                                                                                                                                                                                                                            tooltip: bpTooltip
                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                          scales: { x: { ticks: { font: { size: 10 }, maxRotation: horizontal ? 0 : 45 } }, y: { ticks: { font: { size: 10 } } } }
                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                      }));
                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                    var _r = _chartDataRange(); if (_r) _updateYSlider(_r.min,_r.max); _applyYAxisLimits();
                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                  // --- 普通情况（无分面）---
                                                                                                                                                                                                                                                                                                                                                                  var displayRowKeys = getDisplayRowKeys();
                                                                                                                                                                                                                                                                                                                                                                  if (!displayRowKeys.length) {
                                                                                                                                                                                                                                                                                                                                                                    $('#__UID__-chart-container').css({position:'',height:''}).html('<p class=\"pv-boxplot-note\">No data to display.</p>');
                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                  // 获取所有栏变量组合键
                                                                                                                                                                                                                                                                                                                                                                  var colKeys = [];
                                                                                                                                                                                                                                                                                                                                                                  if (cols.length) {
                                                                                                                                                                                                                                                                                                                                                                    var seen = {};
                                                                                                                                                                                                                                                                                                                                                                    fd.forEach(function(row) {
                                                                                                                                                                                                                                                                                                                                                                        var ck = cols.map(function(v){ return String(row[v]!=null?row[v]:'(NA)'); }).join('||');
                                                                                                                                                                                                                                                                                                                                                                        if (!seen[ck]) { seen[ck] = true; colKeys.push(ck); }
                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                      if (colKeys.length === 0) colKeys = ['__ALL__'];
                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                      colKeys = ['__ALL__'];
                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                    var dataMap = aggregateData(fd, displayRowKeys, colKeys);
                                                                                                                                                                                                                                                                                                                                                                    var datasets = [];
                                                                                                                                                                                                                                                                                                                                                                    if (colKeys.length === 1 && colKeys[0] === '__ALL__') {
                                                                                                                                                                                                                                                                                                                                                                      datasets.push({
                                                                                                                                                                                                                                                                                                                                                                          label: yKey,
                                                                                                                                                                                                                                                                                                                                                                          data: displayRowKeys.map(function(key) { return dataMap['__ALL__'][key] || []; }),
                                                                                                                                                                                                                                                                                                                                                                          backgroundColor: PALETTE[0]+'88', borderColor: PALETTE[0], borderWidth: 1,
                                                                                                                                                                                                                                                                                                                                                                          outlierBackgroundColor: PALETTE[0], outlierRadius: 3
                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                        colKeys.forEach(function(ck, ci) {
                                                                                                                                                                                                                                                                                                                                                                            datasets.push({
                                                                                                                                                                                                                                                                                                                                                                                label: ck,
                                                                                                                                                                                                                                                                                                                                                                                data: displayRowKeys.map(function(key) { return (dataMap[ck] && dataMap[ck][key]) || []; }),
                                                                                                                                                                                                                                                                                                                                                                                backgroundColor: PALETTE[ci % PALETTE.length]+'88',
                                                                                                                                                                                                                                                                                                                                                                                borderColor: PALETTE[ci % PALETTE.length], borderWidth: 1,
                                                                                                                                                                                                                                                                                                                                                                                outlierBackgroundColor: PALETTE[ci % PALETTE.length], outlierRadius: 3
                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                          var _pvH = $('#__UID__-yaxis-panel').outerHeight() || 340;
                                                                                                                                                                                                                                                                                                                                                                          var $container = $('#__UID__-chart-container');
                                                                                                                                                                                                                                                                                                                                                                          $container.css({position:'relative', height: _pvH + 'px'}).empty();
                                                                                                                                                                                                                                                                                                                                                                          var cv = $('<canvas>')[0];
                                                                                                                                                                                                                                                                                                                                                                          $container.append(cv);
                                                                                                                                                                                                                                                                                                                                                                          chartInstances.push(new Chart(cv, {
                                                                                                                                                                                                                                                                                                                                                                                type: 'boxplot',
                                                                                                                                                                                                                                                                                                                                                                                data: { labels: displayRowKeys, datasets: datasets },
                                                                                                                                                                                                                                                                                                                                                                                options: {
                                                                                                                                                                                                                                                                                                                                                                                  indexAxis: horizontal ? 'y' : 'x',
                                                                                                                                                                                                                                                                                                                                                                                  maintainAspectRatio: false, responsive: true,
                                                                                                                                                                                                                                                                                                                                                                                  plugins: {
                                                                                                                                                                                                                                                                                                                                                                                    legend: { display: datasets.length > 1, position: 'top' },
                                                                                                                                                                                                                                                                                                                                                                                    title: { display: true, text: yKey + ' by ' + (rows.join(' / ') || '(all)'), font: { size: 13 } },
                                                                                                                                                                                                                                                                                                                                                                                    tooltip: bpTooltip
                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                  scales: {
                                                                                                                                                                                                                                                                                                                                                                                    x: { ticks: { font: { size: 11 }, maxRotation: horizontal ? 0 : 45 } },
                                                                                                                                                                                                                                                                                                                                                                                    y: { ticks: { font: { size: 11 } } }
                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                              }));
                                                                                                                                                                                                                                                                                                                                                                              var _r = _chartDataRange(); if (_r) _updateYSlider(_r.min,_r.max); _applyYAxisLimits();
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                            // -- Y-axis slider helpers --------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                            function _chartDataRange() {
                                                                                                                                                                                                                                                                                                                                                                              var allVals = [];
                                                                                                                                                                                                                                                                                                                                                                              chartInstances.forEach(function(c) {
                                                                                                                                                                                                                                                                                                                                                                                  (c.data.datasets || []).forEach(function(ds) {
                                                                                                                                                                                                                                                                                                                                                                                      (ds.data || []).forEach(function(v) {
                                                                                                                                                                                                                                                                                                                                                                                          if (Array.isArray(v)) { v.forEach(function(n){ if(typeof n==='number'&&isFinite(n)) allVals.push(n); }); }
                                                                                                                                                                                                                                                                                                                                                                                          else if (typeof v === 'number' && isFinite(v)) allVals.push(v);
                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                    if (!allVals.length) return null;
                                                                                                                                                                                                                                                                                                                                                                                    return { min: Math.min.apply(null, allVals), max: Math.max.apply(null, allVals) };
                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                  function _fmtAxisVal(v) {
                                                                                                                                                                                                                                                                                                                                                                                    var n = parseFloat(v); if (!isFinite(n)) return '';
                                                                                                                                                                                                                                                                                                                                                                                    if (Math.abs(n) >= 10000) return Math.round(n/1000)+'k';
                                                                                                                                                                                                                                                                                                                                                                                    if (Math.abs(n) >= 1000) return Math.round(n)+'';
                                                                                                                                                                                                                                                                                                                                                                                    if (Math.abs(n) >= 10) return Math.round(n*10)/10+'';
                                                                                                                                                                                                                                                                                                                                                                                    return Math.round(n*100)/100+'';
                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                  function _updateYSlider(dMin, dMax) {
                                                                                                                                                                                                                                                                                                                                                                                    var $maxS = $('#__UID__-ymax-slider'), $minS = $('#__UID__-ymin-slider');
                                                                                                                                                                                                                                                                                                                                                                                    if (!$maxS.length) return;
                                                                                                                                                                                                                                                                                                                                                                                    var lo = dMin - 0.5 * Math.abs(dMin), hi = dMax + 0.2 * Math.abs(dMax) || 1;
                                                                                                                                                                                                                                                                                                                                                                                    var step = (hi - lo) / 200 || 0.01;
                                                                                                                                                                                                                                                                                                                                                                                    $maxS.attr({ min: lo, max: hi, step: step });
                                                                                                                                                                                                                                                                                                                                                                                    $minS.attr({ min: lo, max: hi, step: step });
                                                                                                                                                                                                                                                                                                                                                                                    var curMax = yAxisMax !== null ? yAxisMax : hi;
                                                                                                                                                                                                                                                                                                                                                                                    var curMin = yAxisMin !== null ? yAxisMin : lo;
                                                                                                                                                                                                                                                                                                                                                                                    $maxS.val(curMax); $minS.val(curMin);
                                                                                                                                                                                                                                                                                                                                                                                    $('#__UID__-ymax-val').text(_fmtAxisVal(curMax));
                                                                                                                                                                                                                                                                                                                                                                                    $('#__UID__-ymin-val').text(_fmtAxisVal(curMin));
                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                  function _applyYAxisLimits() {
                                                                                                                                                                                                                                                                                                                                                                                    var axisKey = horizontal ? 'x' : 'y';
                                                                                                                                                                                                                                                                                                                                                                                    chartInstances.forEach(function(c) {
                                                                                                                                                                                                                                                                                                                                                                                        if (c.options && c.options.scales && c.options.scales[axisKey]) {
                                                                                                                                                                                                                                                                                                                                                                                          c.options.scales[axisKey].min = (yAxisMin !== null) ? yAxisMin : undefined;
                                                                                                                                                                                                                                                                                                                                                                                          c.options.scales[axisKey].max = (yAxisMax !== null) ? yAxisMax : undefined;
                                                                                                                                                                                                                                                                                                                                                                                          c.update('none');
                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                    // -- Bar chart renderer -----------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                    // -- Bar chart renderer -----------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                    function renderBarChart() {
                                                                                                                                                                                                                                                                                                                                                                                      chartInstances.forEach(function(c) { c.destroy(); });
                                                                                                                                                                                                                                                                                                                                                                                      chartInstances = [];
                                                                                                                                                                                                                                                                                                                                                                                      var $wrap = $('#__UID__-chart-wrap');
                                                                                                                                                                                                                                                                                                                                                                                      var slots = activeSlots();
                                                                                                                                                                                                                                                                                                                                                                                      var rowVars = (lastCfg && lastCfg.rows) || [];
                                                                                                                                                                                                                                                                                                                                                                                      var colVars = (lastCfg && lastCfg.cols) || [];
                                                                                                                                                                                                                                                                                                                                                                                      if (!rowVars.length) {
                                                                                                                                                                                                                                                                                                                                                                                        $wrap.hide(); updateGGPlotCode(); updateHeatmapCode(); saveStateToHash(); return;
                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                      $wrap.show();
                                                                                                                                                                                                                                                                                                                                                                                      // -- Non-regression path requires at least one stat slot --------------------
                                                                                                                                                                                                                                                                                                                                                                                      if (!slots.length) {
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-chart-container').empty().css({height:'', position:''});
                                                                                                                                                                                                                                                                                                                                                                                        updateGGPlotCode(); updateHeatmapCode(); saveStateToHash(); return;
                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                      var $sel = $('#__UID__-chart-stat');
                                                                                                                                                                                                                                                                                                                                                                                      var prevIdx = chartStatIdx;
                                                                                                                                                                                                                                                                                                                                                                                      $sel.empty();
                                                                                                                                                                                                                                                                                                                                                                                      slots.forEach(function(s, i) {
                                                                                                                                                                                                                                                                                                                                                                                          var lbl = s.aggName === 'Count' ? 'Count' : s.aggName + '(' + s.varName + ')';
                                                                                                                                                                                                                                                                                                                                                                                          $sel.append($('<option>').val(i).text(lbl));
                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                        chartStatIdx = Math.min(prevIdx, slots.length - 1);
                                                                                                                                                                                                                                                                                                                                                                                        $sel.val(chartStatIdx);
                                                                                                                                                                                                                                                                                                                                                                                        var canFacet = colVars.length >= 1;
                                                                                                                                                                                                                                                                                                                                                                                        if (!canFacet) { chartFacet = false; }
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-facet-wrap').toggle(canFacet);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-facet-btn').text(chartFacet ? 'Facets' : 'Grouped')
                                                                                                                                                                                                                                                                                                                                                                                        .toggleClass('active', chartFacet);
                                                                                                                                                                                                                                                                                                                                                                                        var canRowFacet = rowVars.length >= 2;
                                                                                                                                                                                                                                                                                                                                                                                        if (!canRowFacet) chartRowFacet = false;
                                                                                                                                                                                                                                                                                                                                                                                        if (!chartFacet && !chartRowFacet) chartFreeY = false;
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-rowfacet-wrap').toggle(canRowFacet);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-rowfacet-btn').text(chartRowFacet ? 'Row Facets' : 'Row Grouped')
                                                                                                                                                                                                                                                                                                                                                                                        .toggleClass('active', chartRowFacet);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-freey-wrap').toggle((canFacet && chartFacet) || (canRowFacet && chartRowFacet));
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-freey-chk').prop('checked', chartFreeY);
                                                                                                                                                                                                                                                                                                                                                                                        var PALETTE    = ['#4472C4','#70AD47','#C55A11','#FFC000','#5B9BD5','#A5A5A5','#FF0000','#7030A0'];
                                                                                                                                                                                                                                                                                                                                                                                        var NB_PALETTE = ['#32CD32','#FF8C00','#9400D3','#FF1493','#00CED1','#FF4500','#1E90FF','#FFD700'];
                                                                                                                                                                                                                                                                                                                                                                                        var $table = $('#__UID__ .pvtTable');
                                                                                                                                                                                                                                                                                                                                                                                        if (!$table.length) {
                                                                                                                                                                                                                                                                                                                                                                                          $('#__UID__-chart-container').empty().css({height:'', position:''});
                                                                                                                                                                                                                                                                                                                                                                                          updateGGPlotCode(); updateHeatmapCode(); saveStateToHash(); return;
                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                        var curSlot = slots[chartStatIdx] || slots[0];
                                                                                                                                                                                                                                                                                                                                                                                        var slotLbl = curSlot.aggName === 'Count' ? 'Count' : curSlot.aggName + '(' + curSlot.varName + ')';
                                                                                                                                                                                                                                                                                                                                                                                        var $container = $('#__UID__-chart-container');
                                                                                                                                                                                                                                                                                                                                                                                        $container.empty().removeClass('pv-facet-grid').css({position:'',height:''});
                                                                                                                                                                                                                                                                                                                                                                                        function cellVal($cell) {
                                                                                                                                                                                                                                                                                                                                                                                          var lines = $cell.text().trim().split('\\n');
                                                                                                                                                                                                                                                                                                                                                                                          var v = parseFloat(lines[chartStatIdx] !== undefined ? lines[chartStatIdx] : lines[0]);
                                                                                                                                                                                                                                                                                                                                                                                          return isNaN(v) ? 0 : v;
                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                        function cellValAt($cell, idx) {
                                                                                                                                                                                                                                                                                                                                                                                          var lines = $cell.text().trim().split('\\n');
                                                                                                                                                                                                                                                                                                                                                                                          var v = parseFloat(lines[idx] !== undefined ? lines[idx] : lines[0]);
                                                                                                                                                                                                                                                                                                                                                                                          return isNaN(v) ? 0 : v;
                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                        var hasBins = rowVars.some(isBinVar);
                                                                                                                                                                                                                                                                                                                                                                                        var xAxisVar    = (chartRowFacet && rowVars.length >= 2) ? rowVars[1] : rowVars[0];
                                                                                                                                                                                                                                                                                                                                                                                        var useLineChart = isDateVar(xAxisVar);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-binscat-wrap').toggle(hasBins);
                                                                                                                                                                                                                                                                                                                                                                                        if (!hasBins) binscatterMode = false;
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-binscat-chk').prop('checked', binscatterMode);
                                                                                                                                                                                                                                                                                                                                                                                        var _isMeanMedian = curSlot.aggName === 'Mean' || curSlot.aggName === 'Median';
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-numbinscat-wrap').toggle(hasBins && _isMeanMedian);
                                                                                                                                                                                                                                                                                                                                                                                        if (!hasBins || !_isMeanMedian) numBinscatterMode = false;
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-numbinscat-chk').prop('checked', numBinscatterMode);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-boxplot-wrap').toggle(rowVars.length > 0);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-boxplot-chk').prop('checked', boxplotMode);
                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-orient-btn').show().text(horizontal ? 'Horizontal' : 'Vertical').toggleClass('active', horizontal);
                                                                                                                                                                                                                                                                                                                                                                                        if (boxplotMode) {
                                                                                                                                                                                                                                                                                                                                                                                          var bpSlots = activeSlots();
                                                                                                                                                                                                                                                                                                                                                                                          var bpSlot = bpSlots[Math.min(chartStatIdx, bpSlots.length - 1)];
                                                                                                                                                                                                                                                                                                                                                                                          if (!bpSlot || bpSlot.aggName === 'Count') {
                                                                                                                                                                                                                                                                                                                                                                                            $container.css({position:'',height:''}).html('<p class=\"pv-boxplot-note\">Boxplot requires a numeric variable — select Mean, Median, Sum, SD, Min, or Max.</p>');
                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                            renderBoxplot(bpSlot);
                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                          updateGGPlotCode(); updateHeatmapCode(); saveStateToHash(); return;
                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                        var useNumBinscat = numBinscatterMode && hasBins && rowVars.length > 0 && isBinVar(rowVars[0]) &&
                                                                                                                                                                                                                                                                                                                                                                                        (curSlot.aggName === 'Mean' || curSlot.aggName === 'Median') && curSlot.varName;
                                                                                                                                                                                                                                                                                                                                                                                        var nbSlot = useNumBinscat ? curSlot : null;
                                                                                                                                                                                                                                                                                                                                                                                        var nbSlotIdx = useNumBinscat ? chartStatIdx : -1;
                                                                                                                                                                                                                                                                                                                                                                                        function makeChart(canvas, labels, datasets, yMax, title, isLine) {
                                                                                                                                                                                                                                                                                                                                                                                          var tp = isLine ? 'line' : 'bar';
                                                                                                                                                                                                                                                                                                                                                                                          var valOpts = { beginAtZero: true, ticks: { font: { size: 11 } } };
                                                                                                                                                                                                                                                                                                                                                                                          if (yMax !== undefined) valOpts.suggestedMax = yMax;
                                                                                                                                                                                                                                                                                                                                                                                          var catOpts = { ticks: { font: { size: isLine ? 10 : 11 }, maxRotation: isLine ? 45 : 0 } };
                                                                                                                                                                                                                                                                                                                                                                                          var scalesOpts = horizontal ? { x: valOpts, y: catOpts } : { x: catOpts, y: valOpts };
                                                                                                                                                                                                                                                                                                                                                                                          var dsets = isLine ? datasets.map(function(ds) {
                                                                                                                                                                                                                                                                                                                                                                                              return Object.assign({}, ds, { pointRadius: 5/2, pointHoverRadius: 7/2, fill: false, tension: 0 });
                                                                                                                                                                                                                                                                                                                                                                                            }) : datasets;
                                                                                                                                                                                                                                                                                                                                                                                            chartInstances.push(new Chart(canvas, {
                                                                                                                                                                                                                                                                                                                                                                                                  type: tp,
                                                                                                                                                                                                                                                                                                                                                                                                  data: { labels: labels, datasets: dsets },
                                                                                                                                                                                                                                                                                                                                                                                                  options: {
                                                                                                                                                                                                                                                                                                                                                                                                    indexAxis: horizontal ? 'y' : 'x',
                                                                                                                                                                                                                                                                                                                                                                                                    maintainAspectRatio: false, responsive: true,
                                                                                                                                                                                                                                                                                                                                                                                                    plugins: {
                                                                                                                                                                                                                                                                                                                                                                                                      legend: { display: datasets.length > 1, position: 'top' },
                                                                                                                                                                                                                                                                                                                                                                                                      title: { display: !!title, text: title || '', font: { size: 13 } }
                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                    scales: scalesOpts
                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                }));
                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                              function makeNumericBinChart(canvas, rowLabels, datasets, rawPts, title, yMax) {
                                                                                                                                                                                                                                                                                                                                                                                                var mids = rowLabels.map(parseBinMidpoint);
                                                                                                                                                                                                                                                                                                                                                                                                var pt = horizontal ? function(num, val) { return { x: val, y: num }; }
                                                                                                                                                                                                                                                                                                                                                                                                : function(num, val) { return { x: num, y: val }; };
                                                                                                                                                                                                                                                                                                                                                                                                var dsets = datasets.map(function(ds) {
                                                                                                                                                                                                                                                                                                                                                                                                    return Object.assign({}, ds, {
                                                                                                                                                                                                                                                                                                                                                                                                        data: mids.map(function(x, i) { return pt(x, ds.data[i]); }),
                                                                                                                                                                                                                                                                                                                                                                                                        pointRadius: 6/3, pointHoverRadius: 8/3, showLine: true, tension: 0, fill: false
                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                    if (rawPts && rawPts.length) {
                                                                                                                                                                                                                                                                                                                                                                                                      dsets.push({ label: 'Raw data',
                                                                                                                                                                                                                                                                                                                                                                                                          data: rawPts.map(function(p) { return pt(p.x, p.y); }),
                                                                                                                                                                                                                                                                                                                                                                                                          pointRadius: 3, pointHoverRadius: 5, showLine: false, fill: false,
                                                                                                                                                                                                                                                                                                                                                                                                          backgroundColor: 'rgba(120,120,120,0.25)', borderColor: 'transparent' });
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                        datasets.forEach(function(ds, di) {
                                                                                                                                                                                                                                                                                                                                                                                                            var xs = [], ys = [];
                                                                                                                                                                                                                                                                                                                                                                                                            mids.forEach(function(x, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                if (!isNaN(x) && i < ds.data.length && !isNaN(ds.data[i])) { xs.push(x); ys.push(ds.data[i]); }
                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                              if (xs.length < 2) return;
                                                                                                                                                                                                                                                                                                                                                                                                              var n = xs.length;
                                                                                                                                                                                                                                                                                                                                                                                                              var sumX = xs.reduce(function(a,b){return a+b;},0);
                                                                                                                                                                                                                                                                                                                                                                                                              var sumY = ys.reduce(function(a,b){return a+b;},0);
                                                                                                                                                                                                                                                                                                                                                                                                              var sumXY = xs.reduce(function(s,x,i){return s+x*ys[i];},0);
                                                                                                                                                                                                                                                                                                                                                                                                              var sumX2 = xs.reduce(function(s,x){return s+x*x;},0);
                                                                                                                                                                                                                                                                                                                                                                                                              var denom = n*sumX2 - sumX*sumX;
                                                                                                                                                                                                                                                                                                                                                                                                              if (Math.abs(denom) < 1e-10) return;
                                                                                                                                                                                                                                                                                                                                                                                                              var slope = (n*sumXY - sumX*sumY) / denom;
                                                                                                                                                                                                                                                                                                                                                                                                              var intercept = (sumY - slope*sumX) / n;
                                                                                                                                                                                                                                                                                                                                                                                                              var xMin = 0.9*Math.min.apply(null,xs), xMax = 1.1*Math.max.apply(null,xs);
                                                                                                                                                                                                                                                                                                                                                                                                              dsets.push({ label: 'Fit',
                                                                                                                                                                                                                                                                                                                                                                                                                  data: [pt(xMin, intercept+slope*xMin), pt(xMax, intercept+slope*xMax)],
                                                                                                                                                                                                                                                                                                                                                                                                                  showLine: true, fill: false, pointRadius: 0, tension: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                  borderColor: 'orangered', borderWidth: 1.5 });
                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                var numOpts = { type: 'linear', ticks: { font: { size: 10 } } };
                                                                                                                                                                                                                                                                                                                                                                                                                var valOpts = { beginAtZero: true, ticks: { font: { size: 11 } } };
                                                                                                                                                                                                                                                                                                                                                                                                                if (yMax !== undefined) valOpts.suggestedMax = yMax;
                                                                                                                                                                                                                                                                                                                                                                                                                chartInstances.push(new Chart(canvas, {
                                                                                                                                                                                                                                                                                                                                                                                                                      type: 'scatter',
                                                                                                                                                                                                                                                                                                                                                                                                                      data: { datasets: dsets },
                                                                                                                                                                                                                                                                                                                                                                                                                      options: {
                                                                                                                                                                                                                                                                                                                                                                                                                        maintainAspectRatio: false, responsive: true,
                                                                                                                                                                                                                                                                                                                                                                                                                        plugins: {
                                                                                                                                                                                                                                                                                                                                                                                                                          legend: { display: false },
                                                                                                                                                                                                                                                                                                                                                                                                                          title: { display: !!title, text: title || '', font: { size: 13 } }
                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                        scales: horizontal ? { x: valOpts, y: numOpts } : { x: numOpts, y: valOpts }
                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                    }));
                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                  var rowLabels = [];
                                                                                                                                                                                                                                                                                                                                                                                                                  $table.find('tbody tr').each(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                      var $tr = $(this);
                                                                                                                                                                                                                                                                                                                                                                                                                      if (!$tr.find('.pvtRowLabel').length) return;
                                                                                                                                                                                                                                                                                                                                                                                                                      rowLabels.push($tr.find('.pvtRowLabel').map(function(){
                                                                                                                                                                                                                                                                                                                                                                                                                            return $(this).clone().find('.sort-arrow').remove().end().text().trim();
                                                                                                                                                                                                                                                                                                                                                                                                                          }).get().join(' / '));
                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                        if (chartRowFacet && rowVars.length >= 2) {
                                                                                                                                                                                                                                                                                                                                                                                                                          var colKeys = extractColKeys($table);
                                                                                                                                                                                                                                                                                                                                                                                                                          var rowGroups = {}, rowGroupOrder = [];
                                                                                                                                                                                                                                                                                                                                                                                                                          var curOuter = null;
                                                                                                                                                                                                                                                                                                                                                                                                                          $table.find('tbody tr').each(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                              var $tr = $(this);
                                                                                                                                                                                                                                                                                                                                                                                                                              var $rl = $tr.find('.pvtRowLabel');
                                                                                                                                                                                                                                                                                                                                                                                                                              if (!$rl.length) return;
                                                                                                                                                                                                                                                                                                                                                                                                                              var rlArr = $rl.map(function(){
                                                                                                                                                                                                                                                                                                                                                                                                                                  return $(this).clone().find('.sort-arrow').remove().end().text().trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                }).get();
                                                                                                                                                                                                                                                                                                                                                                                                                                var innerLbl;
                                                                                                                                                                                                                                                                                                                                                                                                                                if (rlArr.length >= 2) { curOuter = rlArr[0]; innerLbl = rlArr.slice(1).join(' / '); }
                                                                                                                                                                                                                                                                                                                                                                                                                                else { innerLbl = rlArr[0]; }
                                                                                                                                                                                                                                                                                                                                                                                                                                if (curOuter === null) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                if (!rowGroups[curOuter]) { rowGroups[curOuter] = { innerLabels: [], colData: {} }; rowGroupOrder.push(curOuter); }
                                                                                                                                                                                                                                                                                                                                                                                                                                rowGroups[curOuter].innerLabels.push(innerLbl);
                                                                                                                                                                                                                                                                                                                                                                                                                                if (colKeys.length && colKeys[0] !== '__ALL__') {
                                                                                                                                                                                                                                                                                                                                                                                                                                  var $vals = $tr.find('.pvtVal');
                                                                                                                                                                                                                                                                                                                                                                                                                                  colKeys.forEach(function(ck, ci) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!rowGroups[curOuter].colData[ck]) rowGroups[curOuter].colData[ck] = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                      rowGroups[curOuter].colData[ck].push(cellVal($vals.eq(ci)));
                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                    var v2 = cellVal($tr.find('.pvtTotal').length ? $tr.find('.pvtTotal').first() : $tr.find('.pvtVal').first());
                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!rowGroups[curOuter].colData['__total__']) rowGroups[curOuter].colData['__total__'] = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                    rowGroups[curOuter].colData['__total__'].push(v2);
                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                var rfGlobalMax = undefined;
                                                                                                                                                                                                                                                                                                                                                                                                                                if (!chartFreeY) {
                                                                                                                                                                                                                                                                                                                                                                                                                                  var rfAllVals = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                  rowGroupOrder.forEach(function(rv) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      Object.keys(rowGroups[rv].colData).forEach(function(ck) { rowGroups[rv].colData[ck].forEach(function(v){ rfAllVals.push(v); }); });
                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                    rfGlobalMax = rfAllVals.length ? Math.max.apply(null, rfAllVals) * 1.05 : undefined;
                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                  $container.addClass('pv-facet-grid');
                                                                                                                                                                                                                                                                                                                                                                                                                                  var pH2 = Math.max(180, Math.min(260, 320 - rowGroupOrder.length * 8));
                                                                                                                                                                                                                                                                                                                                                                                                                                  rowGroupOrder.forEach(function(rv) {
                                                                                                                                                                                                                                                                                                                                                                                                                                      var grp = rowGroups[rv];
                                                                                                                                                                                                                                                                                                                                                                                                                                      var $panel = $('<div class=\"pv-facet-panel\"></div>');
                                                                                                                                                                                                                                                                                                                                                                                                                                      $panel.append('<div class=\"pv-facet-lbl\">' + rv + '</div>');
                                                                                                                                                                                                                                                                                                                                                                                                                                      var $cw = $('<div>').css({position:'relative',height:pH2+'px'});
                                                                                                                                                                                                                                                                                                                                                                                                                                      var cv = $('<canvas>')[0]; $cw.append(cv); $panel.append($cw);
                                                                                                                                                                                                                                                                                                                                                                                                                                      $container.append($panel);
                                                                                                                                                                                                                                                                                                                                                                                                                                      var dsets2;
                                                                                                                                                                                                                                                                                                                                                                                                                                      if (colKeys.length && colKeys[0] !== '__ALL__') {
                                                                                                                                                                                                                                                                                                                                                                                                                                        dsets2 = colKeys.map(function(ck, ci) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            return { label: ck.replace(/[|][|]/g, ' / '), data: grp.colData[ck] || [],
                                                                                                                                                                                                                                                                                                                                                                                                                                              backgroundColor: PALETTE[ci % PALETTE.length] + 'BB',
                                                                                                                                                                                                                                                                                                                                                                                                                                              borderColor: PALETTE[ci % PALETTE.length], borderWidth: 1 };
                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                            dsets2 = [{ label: slotLbl, data: grp.colData['__total__'] || [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                backgroundColor: PALETTE[0] + 'BB', borderColor: PALETTE[0], borderWidth: 1 }];
                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                              makeChart(cv, grp.innerLabels, dsets2, chartFreeY ? undefined : rfGlobalMax, null, binscatterMode || useLineChart);
                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (!colVars.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                            var _pvH = $('#__UID__-yaxis-panel').outerHeight() || 340;
                                                                                                                                                                                                                                                                                                                                                                                                                                            $container.css({position:'relative', height: _pvH + 'px'});
                                                                                                                                                                                                                                                                                                                                                                                                                                            var cv = $('<canvas>')[0]; $container.append(cv);
                                                                                                                                                                                                                                                                                                                                                                                                                                            if (useNumBinscat) {
                                                                                                                                                                                                                                                                                                                                                                                                                                              var nbVals = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                              $table.find('tbody tr').each(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  var $tr = $(this);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!$tr.find('.pvtRowLabel').length) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                  var $tc = $tr.find('.pvtTotal').first();
                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!$tc.length) $tc = $tr.find('.pvtVal').first();
                                                                                                                                                                                                                                                                                                                                                                                                                                                  nbVals.push(cellValAt($tc, nbSlotIdx));
                                                                                                                                                                                                                                                                                                                                                                                                                                                });
