                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $panel.append('<div class=\"pv-facet-lbl\">' + fv + '</div>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var $cw = $('<div>').css({position:'relative',height:pH+'px'});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var cv = $('<canvas>')[0]; $cw.append(cv); $panel.append($cw);
