                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var rawPts = nbSlot.varName ? getRawScatterPts(nbXVar, nbSlot.varName, function(d) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return String(d[facetVar]) === fv;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }) : [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            makeNumericBinChart(cv, rowLabels, nbDsets, rawPts, fv, chartFreeY ? undefined : nbGlobalMax);
