                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // -- Stratified regression ---------------------------------------------------

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Regularised incomplete beta (Lentz continued-fraction) for t and F p-values
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function _lnGamma(z) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var p=[0.99999999999980993,676.5203681218851,-1259.1392167224028,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            771.32342877765313,-176.61502916214059,12.507343278686905,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            -0.13857109526572012,9.9843695780195716e-6,1.5056327351493116e-7];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(z<0.5) return Math.log(Math.PI/Math.sin(Math.PI*z))-_lnGamma(1-z);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            z--; var x=p[0], t=z+7.5;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(var i=1;i<9;i++) x+=p[i]/(z+i);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return 0.5*Math.log(2*Math.PI)+(z+0.5)*Math.log(t)-t+Math.log(x);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function _betacf(x,a,b) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var FP=1e-30,EP=3e-7,qab=a+b,qap=a+1,qam=a-1,cv=1,d=1-qab*x/qap,del;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(Math.abs(d)<FP)d=FP; d=1/d; var h=d;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(var m=1;m<=100;m++){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var m2=2*m, aa=m*(b-m)*x/((qam+m2)*(a+m2));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              d=1+aa*d;   if(Math.abs(d)<FP)d=FP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cv=1+aa/cv; if(Math.abs(cv)<FP)cv=FP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              d=1/d; h*=d*cv;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              d=1+aa*d;   if(Math.abs(d)<FP)d=FP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cv=1+aa/cv; if(Math.abs(cv)<FP)cv=FP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              d=1/d; del=d*cv; h*=del;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if(Math.abs(del-1)<EP) break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return h;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function _ibeta(x,a,b) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(x<=0)return 0; if(x>=1)return 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var lb=_lnGamma(a)+_lnGamma(b)-_lnGamma(a+b);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var bt=Math.exp(a*Math.log(x)+b*Math.log(1-x)-lb);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (x<(a+1)/(a+b+2)) ? bt*_betacf(x,a,b)/a : 1-bt*_betacf(1-x,b,a)/b;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function _tPVal(t,df){ return _ibeta(df/(df+t*t), df/2, 0.5); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function _fPVal(F,df1,df2){ return F<=0?1:_ibeta(df2/(df2+df1*F), df2/2, df1/2); }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function olsFit(xArr, yArr) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var n = xArr.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (n < 2) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var sx=0,sy=0,sxy=0,sx2=0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(var i=0;i<n;i++){sx+=xArr[i];sy+=yArr[i];sxy+=xArr[i]*yArr[i];sx2+=xArr[i]*xArr[i];}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var denom = n*sx2 - sx*sx;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(Math.abs(denom) < 1e-10) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var slope=(n*sxy-sx*sy)/denom, intercept=(sy-slope*sx)/n;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var yMean=sy/n, ssTot=0, ssRes=0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(var i=0;i<n;i++){ssTot+=Math.pow(yArr[i]-yMean,2);ssRes+=Math.pow(yArr[i]-(slope*xArr[i]+intercept),2);}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var r2 = ssTot<1e-10 ? 0 : 1-ssRes/ssTot;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var sxx = sx2 - sx*sx/n;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var s2=null, seSlope=null, seInt=null, tSlope=null, tInt=null, pSlope=null, pInt=null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(n>2 && sxx>1e-10){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              s2=ssRes/(n-2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              seSlope=Math.sqrt(s2/sxx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              seInt=Math.sqrt(s2*sx2/(n*sxx));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              tSlope=slope/seSlope; tInt=intercept/seInt;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              pSlope=_tPVal(tSlope,n-2); pInt=_tPVal(tInt,n-2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {slope:slope, intercept:intercept, r2:r2, n:n, ssRes:ssRes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              s2:s2, seSlope:seSlope, seInt:seInt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              tSlope:tSlope, tInt:tInt, pSlope:pSlope, pInt:pInt};
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function renderRegressionChart() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rowVars = regGroupVar ? [regGroupVar] : [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var $container = $('#__UID__-reg-tab-chart');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var $infoWrap = $('#__UID__-reg-info-wrap');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!rowVars.length || !regXVar || !regYVar) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $container.empty();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $infoWrap.empty();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function fp4(v){ return v==null?'n/a':v.toFixed(4); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function fp3(v){ return v==null?'n/a':v.toFixed(3); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function fmtP(p){ return p==null?'n/a':p<0.001?'<0.001':p.toFixed(3); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function star(p){ return p==null?'':p<0.001?'***':p<0.01?'**':p<0.05?'*':p<0.1?'.':''; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var filtered = computeFilteredData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var PALETTE = ['#4472C4','#70AD47','#C55A11','#FFC000','#5B9BD5','#A5A5A5','#FF0000','#7030A0'];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var groups={}, groupOrder=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              filtered.forEach(function(row){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var gk=rowVars.map(function(v){return String(row[v]!=null?row[v]:'(NA)');}).join(' / ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if(!groups[gk]){groups[gk]=[];groupOrder.push(gk);}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var xv=row[regXVar], yv=row[regYVar];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if(xv!=null&&yv!=null&&!isNaN(+xv)&&!isNaN(+yv)) groups[gk].push({x:+xv,y:+yv});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var datasets=[], allX=[], allY=[], groupFits=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var N_LINE=20;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                groupOrder.forEach(function(gk,gi){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var col=PALETTE[gi%PALETTE.length], pts=groups[gk];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    datasets.push({label:gk, type:'scatter', data:pts,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        backgroundColor:col+'44', borderColor:col,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pointRadius:3, pointHoverRadius:5, showLine:false, fill:false});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var xs=pts.map(function(p){return p.x;}), ys=pts.map(function(p){return p.y;});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        xs.forEach(function(v){allX.push(v);}); ys.forEach(function(v){allY.push(v);});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var fit=olsFit(xs,ys);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        groupFits.push(fit);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if(fit){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var xMin=Math.min.apply(null,xs), xMax=Math.max.apply(null,xs);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var linePts=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for(var k=0;k<N_LINE;k++){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var xk=xMin+(xMax-xMin)*k/(N_LINE-1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            linePts.push({x:xk,y:fit.slope*xk+fit.intercept});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          datasets.push({label:gk+' (fit)', type:'scatter', pvtLabel:gk, pvtStats:fit,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              data:linePts, borderColor:col, borderWidth:1.8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              pointRadius:0, pointHoverRadius:4, showLine:true, fill:false, tension:0});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var poolFit=null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if(allX.length>=4){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            poolFit=olsFit(allX,allY);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if(poolFit){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var xMin=Math.min.apply(null,allX), xMax=Math.max.apply(null,allX);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var linePts=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for(var k=0;k<N_LINE;k++){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var xk=xMin+(xMax-xMin)*k/(N_LINE-1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                linePts.push({x:xk,y:poolFit.slope*xk+poolFit.intercept});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              datasets.push({label:'Pooled (all groups)', type:'scatter', pvtLabel:'Pooled (all groups)', pvtStats:poolFit,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  data:linePts, borderColor:'rgba(80,80,80,0.7)', borderWidth:2, borderDash:[7,4],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  pointRadius:0, pointHoverRadius:4, showLine:true, fill:false, tension:0});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Build info panel (Chow test + stat table) -- placed OUTSIDE the flex row
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var g=groupOrder.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var chowHtml='', statHtml='';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Collect valid-fit groups only (olsFit returns null if n<2 or zero x-variance)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rssU=0, validG=0, validX=[], validY=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              groupFits.forEach(function(f,gi){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if(f){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    rssU+=f.ssRes; validG++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var pts=groups[groupOrder[gi]];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pts.forEach(function(p){validX.push(p.x); validY.push(p.y);});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var nValid=validX.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(validG>=2 && nValid>2*validG){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var restrictedFit=olsFit(validX,validY);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if(restrictedFit){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rssR=restrictedFit.ssRes;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var df1=2*(validG-1), df2=nValid-2*validG;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var Fstat=(df1>0&&df2>0)?((rssR-rssU)/df1)/(rssU/df2):null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var pChow=Fstat!=null?_fPVal(Fstat,df1,df2):null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var verdict=pChow==null?'':pChow<0.05
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ?'Structural break detected -- lines differ significantly across groups.'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    :'No significant structural break -- groups share similar regression structure.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var nNote=validG<g?' ('+validG+' of '+g+' groups have sufficient data)':'';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    chowHtml='<div style=\"padding:5px 10px;background:#1F3864;color:white;border:1px solid #152852;border-radius:4px 4px 0 0;font-size:11px;line-height:1.7;\">'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<strong>Chow Test</strong>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ' &nbsp;F('+df1+', '+df2+') = '+(Fstat!=null?Fstat.toFixed(3):'n/a')+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ' &nbsp;p = '+fmtP(pChow)+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ' &nbsp;n = '+nValid+nNote+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<br>'+verdict+'</div>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var anyFit=groupFits.some(function(f){return f!=null;});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(anyFit||poolFit){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var th='style=\"padding:2px 6px;border:1px solid #2F5496;white-space:nowrap;color:white;background:#2F5496;\"';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var td='style=\"padding:2px 6px;border:1px solid #ccc;text-align:right;background:#ffffff;color:#222;\"';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var tdL='style=\"padding:2px 6px;border:1px solid #ccc;background:#ffffff;color:#222;\"';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var tdI='style=\"padding:2px 6px;border:1px solid #ccc;text-align:right;font-style:italic;background:#D6E4F0;color:#1F3864;\"';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var tdLI='style=\"padding:2px 6px;border:1px solid #ccc;font-style:italic;background:#D6E4F0;color:#1F3864;\"';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  statHtml='<table style=\"border-collapse:collapse;width:100%;font-size:11px;\">'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '<thead><tr>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '<th '+th+'>Group</th><th '+th+'>n</th>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '<th '+th+'>b1</th><th '+th+'>SE(b1)</th><th '+th+'>t</th><th '+th+'>p(b1)</th>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '<th '+th+'>b0</th><th '+th+'>R&sup2;</th><th '+th+'>s&sup2;</th>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '</tr></thead><tbody>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  groupOrder.forEach(function(gk,gi){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var f=groupFits[gi]; if(!f) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      statHtml+='<tr>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+tdL+'>'+gk+'</td><td '+td+'>'+f.n+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+td+'>'+fp4(f.slope)+'</td><td '+td+'>'+fp4(f.seSlope)+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+td+'>'+fp3(f.tSlope)+' '+star(f.pSlope)+'</td><td '+td+'>'+fmtP(f.pSlope)+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+td+'>'+fp4(f.intercept)+'</td><td '+td+'>'+fp3(f.r2)+'</td><td '+td+'>'+fp4(f.s2)+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '</tr>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if(poolFit){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var f=poolFit;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      statHtml+='<tr>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+tdLI+'>Pooled</td><td '+tdI+'>'+f.n+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+tdI+'>'+fp4(f.slope)+'</td><td '+tdI+'>'+fp4(f.seSlope)+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+tdI+'>'+fp3(f.tSlope)+' '+star(f.pSlope)+'</td><td '+tdI+'>'+fmtP(f.pSlope)+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<td '+tdI+'>'+fp4(f.intercept)+'</td><td '+tdI+'>'+fp3(f.r2)+'</td><td '+tdI+'>'+fp4(f.s2)+'</td>'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '</tr>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    statHtml+='</tbody></table>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $infoWrap.html(chowHtml+statHtml);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Render chart canvas
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  regChartInstances.forEach(function(c){try{c.destroy();}catch(e){}});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  regChartInstances=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $container.empty().css({height:'340px',position:'relative'});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var canvas=document.createElement('canvas');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $container.append(canvas);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  regChartInstances.push(new Chart(canvas,{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        type:'scatter', data:{datasets:datasets},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        options:{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          maintainAspectRatio:false, responsive:true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          plugins:{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            legend:{display:true, position:'top',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              labels:{font:{size:10},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                filter:function(item){return item.text.indexOf(' (fit)')===-1;}}},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tooltip:{callbacks:{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    title:function(items){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var ds=items[0]&&items[0].dataset;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (ds&&ds.pvtLabel)?ds.pvtLabel:(items[0]?items[0].dataset.label:'');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    label:function(ctx){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if(ctx.dataset.pvtStats) return 'OLS fit -- see stat table below';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return ctx.dataset.label+': ('+ctx.parsed.x.toFixed(2)+', '+ctx.parsed.y.toFixed(2)+')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                scales:{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  x:{title:{display:true,text:regXVar,font:{size:11}},ticks:{font:{size:10}}},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  y:{title:{display:true,text:regYVar,font:{size:11}},ticks:{font:{size:10}}}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function makeRegressionGGCode() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!regGroupVar || !regXVar || !regYVar) return '# Select group, x, and y variables above.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var rows=[regGroupVar], cols=[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var PALETTE=['#4472C4','#70AD47','#C55A11','#FFC000','#5B9BD5','#A5A5A5','#FF0000','#7030A0'];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var numFLines=getNumericFilterCode(lastCfg,true), catFLines=getCategoricalFilterCode(lastCfg,true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var filterSteps=numFLines.concat(catFLines).map(function(l){return '  '+l+' |>\\n';}).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var rx=rColName(regXVar), ry=rColName(regYVar);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var colExpr=rows.length===1?'factor('+rColName(rows[0])+')':'interaction('+rows.map(rColName).join(', ')+')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var colLbl=rows.join(' / ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var palStr=PALETTE.slice(0,8).map(function(c){return dq(c);}).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var facetLine='';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (cols.length===1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              facetLine='  facet_wrap(~ '+rColName(cols[0])+') +\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (cols.length>1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              facetLine='  facet_wrap(~ interaction('+cols.map(rColName).join(', ')+')) +\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var facetNote=cols.length ? '# Note: facets visible in R; browser canvas shows unfaceted view.\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              facetNote+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              dfName+' |>\\n'+filterSteps+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  ggplot(aes(x = '+rx+', y = '+ry+', colour = '+colExpr+')) +\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  geom_point(alpha = 0.35, size = 1.5) +\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  geom_smooth(method = \"lm\", se = FALSE, linewidth = 1) +\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  geom_smooth(aes(group = 1), method = \"lm\", se = FALSE,\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '              colour = \"grey50\", linetype = \"dashed\", linewidth = 1) +\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                facetLine+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  scale_colour_manual(values = c('+palStr+'), name = '+dq(colLbl)+') +\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  labs(x = '+dq(regXVar)+', y = '+dq(regYVar)+') +\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  theme_bw()'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function makeRegressionCode() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!regGroupVar || !regXVar || !regYVar) return '# Select group, x, and y variables above.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rows=[regGroupVar];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var catArg=rows.map(rColName).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var catExpr=rows.length===1?rColName(rows[0]):'interaction('+rows.map(rColName).join(', ')+')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var numFLines=getNumericFilterCode(lastCfg,true), catFLines=getCategoricalFilterCode(lastCfg,true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var filterSteps=numFLines.concat(catFLines).map(function(l){return '  '+l+' |>\\n';}).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rx=rColName(regXVar), ry=rColName(regYVar);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '# ---- Subsample regression: '+regYVar+' ~ '+regXVar+' by '+rows.join(' / ')+' ----\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'library(broom)\\n\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                dfName+' |>\\n'+filterSteps+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  nest_by('+catArg+') |>\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  mutate(\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '    fit   = list(lm('+ry+' ~ '+rx+', data = data)),\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '    tidy  = list(broom::tidy(fit)),\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '    stats = list(broom::glance(fit))\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  ) |>\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  unnest(tidy) |>\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  select('+catArg+', term, estimate, std.error, statistic, p.value)\\n\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '# ---- Pooled additive model (same slope, different intercepts) ----\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'lm('+ry+' ~ '+rx+' + '+catExpr+', data = '+dfName+') |> broom::tidy()\\n\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '# ---- Pooled interaction model (slope may differ by group) ----\\n'+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'lm('+ry+' ~ '+rx+' * '+catExpr+', data = '+dfName+') |> broom::tidy()'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function updateRegressionCode() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $('#__UID__-reg-code').text(makeRegressionCode());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $('#__UID__-reg-gg-code').text(makeRegressionGGCode());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // -- ggplot2 code generation -----------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function makeGGPlotCode() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (boxplotMode) return makeBoxplotCode();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!lastCfg) return '# Configure stat slots and drag a field to Rows.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var rows = lastCfg.rows || [], cols = lastCfg.cols || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var slots = activeSlots();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!rows.length || !slots.length)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return '# Drag at least one field to Rows and configure a stat slot above.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var slot = slots[Math.min(chartStatIdx, slots.length - 1)];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var yVar = slotName(slot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var fn = slot.aggName === 'Count' ? 'n()' : AGG_R_TIDY[slot.aggName].replace('VAR', rColName(slot.varName));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var allGrp = rows.concat(cols);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var numFLines = getNumericFilterCode(lastCfg, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var catFLines = getCategoricalFilterCode(lastCfg, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var filterSteps = numFLines.concat(catFLines).map(function(l){ return '  ' + l + ' |>\\n'; }).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var binSteps = allBinMutateSteps();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var hasTransform = transformState.mode !== 'none' && rows.length > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var hasReorder   = reorderState.mode !== 'original' && rows.length > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var transformStep = hasTransform ? '  ' + getReorderMutate(transformState.mode, rows[0], transformState.param) + ' |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var reorderStep   = hasReorder   ? '  ' + getReorderMutate(reorderState.mode,   rows[0], reorderState.param)  + ' |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var groupsStr = allGrp.map(rColName).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var dotGroups = allGrp.length > 1 ? ', .groups = ' + dq('drop') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var xVar = rColName(rows[0]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var PALETTE = ['#4472C4','#70AD47','#C55A11','#FFC000','#5B9BD5','#A5A5A5','#FF0000','#7030A0'];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var sortArg = sortState.dir === -1 ? 'desc(' + yVar + ')' : yVar;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var sortStep = sortState.colIdx !== -1 ? '  arrange(' + sortArg + ') |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var useBinscatter = binscatterMode && isBinVar(rows[0]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var convertStep = CONVERTED_VARS.filter(function(v) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return rows.indexOf(v) !== -1 || cols.indexOf(v) !== -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }).map(function(v) { return '  mutate(' + rColName(v) + ' = zoo::as.Date(' + rColName(v) + ')) |>\\n'; }).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var coordFlip = horizontal ? '  coord_flip() +\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var code = dfName + ' |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  filterSteps + convertStep + binSteps + transformStep + reorderStep +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  group_by(' + groupsStr + ') |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  summarise(' + yVar + ' = ' + fn + dotGroups + ') |>\\n' + sortStep;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var useFacet = cols.length >= 1 && chartFacet;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var useRowFacet = rows.length >= 2 && chartRowFacet;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var xGGVar = useRowFacet ? rows[1] : rows[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var useDateLine = isDateVar(xGGVar) && !useBinscatter;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (useBinscatter && cols.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  ggplot(aes(x = ' + xVar + ', y = ' + yVar + ', group = 1)) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  geom_point(size = 3, colour = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  geom_line(colour = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  labs(x = ' + dq(rows[0]) + ', y = ' + dq(yVar) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  theme_bw() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  theme(axis.text.x = element_text(angle = 45, hjust = 1))';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else if (cols.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rfX0 = useRowFacet ? rColName(rows[1]) : xVar;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rfX0Lbl = useRowFacet ? rows[1] : rows[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rfScalesArg0 = (useRowFacet && chartFreeY) ? ', scales = ' + dq('free_y') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rfFacetStep0 = useRowFacet ? '  facet_wrap(~ ' + rColName(rows[0]) + rfScalesArg0 + ') +\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (useDateLine) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  ggplot(aes(x = ' + rfX0 + ', y = ' + yVar + ', group = 1)) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  geom_line(colour = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  geom_point(colour = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  scale_x_date() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      rfFacetStep0 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  labs(x = ' + dq(rfX0Lbl) + ', y = ' + dq(yVar) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme_bw() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme(axis.text.x = element_text(angle = 45, hjust = 1))';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  ggplot(aes(x = ' + rfX0 + ', y = ' + yVar + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  geom_col(fill = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      rfFacetStep0 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  labs(x = ' + dq(rfX0Lbl) + ', y = ' + dq(yVar) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme_bw()';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rfX1 = useRowFacet ? rColName(rows[1]) : xVar;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var rfX1Lbl = useRowFacet ? rows[1] : rows[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var nFill = useFacet ? cols.length - 1 : cols.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var fillExpr = nFill === 0 ? null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : nFill === 1 ? 'factor(' + rColName(cols[0]) + ')'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : 'interaction(' + cols.slice(0, nFill).map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var fillLabel = cols.slice(0, nFill).join(' / ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var paletteStr = PALETTE.slice(0, 8).map(function(c){ return dq(c); }).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var facetVar = useFacet ? rColName(cols[cols.length - 1]) : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var scalesArg = ((useFacet || useRowFacet) && chartFreeY) ? ', scales = ' + dq('free_y') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var facetStep = useFacet ? '  facet_wrap(~ ' + facetVar + scalesArg + ') +\\n'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : useRowFacet ? '  facet_wrap(~ ' + rColName(rows[0]) + scalesArg + ') +\\n'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var geomPart = (fillExpr === null)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? useDateLine
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? ('  geom_line(colour = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  geom_point(colour = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  scale_x_date() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      facetStep +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  labs(x = ' + dq(rfX1Lbl) + ', y = ' + dq(yVar) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme_bw() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme(axis.text.x = element_text(angle = 45, hjust = 1))')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      : ('  geom_col(fill = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        facetStep +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        '  labs(x = ' + dq(rfX1Lbl) + ', y = ' + dq(yVar) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        '  theme_bw()')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : useBinscatter
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? ('  geom_point(size = 3) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '  geom_line(aes(group = ' + fillExpr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '  scale_colour_manual(values = c(' + paletteStr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          facetStep.replace(/fill/g,'colour') +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '  labs(x = ' + dq(rfX1Lbl) + ', y = ' + dq(yVar) + ', colour = ' + dq(fillLabel) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '  theme_bw() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '  theme(axis.text.x = element_text(angle = 45, hjust = 1))')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : useDateLine
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? ('  geom_line(aes(group = ' + fillExpr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '  geom_point() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '  scale_colour_manual(values = c(' + paletteStr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '  scale_x_date() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            facetStep.replace(/fill/g,'colour') +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '  labs(x = ' + dq(rfX1Lbl) + ', y = ' + dq(yVar) + ', colour = ' + dq(fillLabel) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '  theme_bw() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '  theme(axis.text.x = element_text(angle = 45, hjust = 1))')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : ('  geom_col(position = ' + dq('dodge') + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  scale_fill_manual(values = c(' + paletteStr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              facetStep +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  labs(x = ' + dq(rfX1Lbl) + ', y = ' + dq(yVar) + ', fill = ' + dq(fillLabel) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  theme_bw()');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var aesFill = (useBinscatter || useDateLine) ? 'colour' : 'fill';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var aesExtra = useDateLine && fillExpr ? ', group = ' + fillExpr : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              code = '# Unlike the orange panel, which uses pivot_wider() to reshape data into\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '# wide form for the pivot table, ggplot2 requires long (tidy) form.\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '# pivot_wider() is therefore omitted here; the column variable is\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '# passed to fill = so geom_col(position = \"dodge\") handles grouping.\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              code +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (fillExpr === null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? '  ggplot(aes(x = ' + rfX1 + ', y = ' + yVar + (useDateLine ? ', group = 1' : '') + ')) +\\n'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : '  ggplot(aes(x = ' + rfX1 + ', y = ' + yVar + ', ' + aesFill + ' = ' + fillExpr + aesExtra + ')) +\\n') +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                geomPart;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return code;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function updateGGPlotCode() { $('#__UID__-ggplot-code').text(makeGGPlotCode()); }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // -- Boxplot code generation -------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function makeBoxplotCode() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!lastCfg) return '# Configure stat slots and drag a field to Rows.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rows = lastCfg.rows || [], cols = lastCfg.cols || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var slots = activeSlots();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!rows.length || !slots.length)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return '# Drag at least one field to Rows and configure a stat slot above.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var slot = slots[Math.min(chartStatIdx, slots.length - 1)];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (['Count','NA Ratio','Variation Ratio','Entropy'].indexOf(slot.aggName) !== -1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return '# Boxplot requires a numeric variable — select Mean, Median, Sum, SD, Min, or Max in the stat slot.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var yVar = rColName(slot.varName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var yLbl = slot.varName;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var numFLines = getNumericFilterCode(lastCfg, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var catFLines = getCategoricalFilterCode(lastCfg, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var filterSteps = numFLines.concat(catFLines).map(function(l){ return '  ' + l + ' |>\\n'; }).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var binSteps = allBinMutateSteps();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var hasTransform = transformState.mode !== 'none' && rows.length > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var hasReorder   = reorderState.mode !== 'original' && rows.length > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var transformStep = hasTransform ? '  ' + getReorderMutate(transformState.mode, rows[0], transformState.param) + ' |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var reorderStep   = hasReorder   ? '  ' + getReorderMutate(reorderState.mode,   rows[0], reorderState.param)  + ' |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var PALETTE = ['#4472C4','#70AD47','#C55A11','#FFC000','#5B9BD5','#A5A5A5','#FF0000','#7030A0'];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var coordFlip = horizontal ? '  coord_flip() +\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var paletteStr = PALETTE.slice(0, 8).map(function(c){ return dq(c); }).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var useFacet    = cols.length >= 1 && chartFacet;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var useRowFacet = rows.length >= 2 && chartRowFacet;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var scalesArg   = ((useFacet || useRowFacet) && chartFreeY) ? ', scales = ' + dq('free_y') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var xVar, xLbl;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (useRowFacet) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                xVar = rColName(rows[1]); xLbl = rows[1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                xVar = rows.length === 1 ? rColName(rows[0]) : 'interaction(' + rows.map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                xLbl = rows.join(' / ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var facetStep = useFacet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? '  facet_wrap(~ ' + (cols.length === 1 ? rColName(cols[0]) : 'interaction(' + cols.map(rColName).join(', ') + ')') + scalesArg + ') +\\n'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : useRowFacet ? '  facet_wrap(~ ' + rColName(rows[0]) + scalesArg + ') +\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var code = dfName + ' |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              filterSteps + binSteps + transformStep + reorderStep;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (cols.length === 0 || useFacet) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  ggplot(aes(x = ' + xVar + ', y = ' + yVar + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  geom_boxplot(fill = ' + dq(PALETTE[0]) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                facetStep +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  labs(x = ' + dq(xLbl) + ', y = ' + dq(yLbl) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  theme_bw()';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var fillExpr  = cols.length === 1 ? 'factor(' + rColName(cols[0]) + ')' : 'interaction(' + cols.map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var fillLabel = cols.join(' / ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  ggplot(aes(x = ' + xVar + ', y = ' + yVar + ', fill = ' + fillExpr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  geom_boxplot() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  scale_fill_manual(values = c(' + paletteStr + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                facetStep +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  labs(x = ' + dq(xLbl) + ', y = ' + dq(yLbl) + ', fill = ' + dq(fillLabel) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coordFlip +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  theme_bw()';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return code;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // -- Heatmap ggplot2 code generation ----------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function makeHeatmapGGCode(rendererName) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!lastCfg) return '# Configure stat slots and drag fields to Rows and Columns.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rows = lastCfg.rows || [], cols = lastCfg.cols || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var slots = activeSlots();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!rows.length || !cols.length || !slots.length)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return '# Drag at least one field to Rows, one to Columns, and configure a stat slot above.';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // 关键修复：使用与 renderBarChart 完全相同的索引选择逻辑
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var idx = chartStatIdx;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (idx >= slots.length) idx = slots.length - 1;  // 边界保护
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (idx < 0) idx = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var slot = slots[idx];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var statN = slotName(slot);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // 调试输出（在浏览器控制台可看到当前选择的统计量）
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log('Heatmap using stat slot index', idx, 'name:', statN);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // ----- 安全构造聚合表达式 -----
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var aggExpr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (slot.aggName === 'Count') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                aggExpr = 'n()';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var varName = rColName(slot.varName);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                switch (slot.aggName) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Sum': aggExpr = 'sum(' + varName + ', na.rm = TRUE)'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Mean': aggExpr = 'mean(' + varName + ', na.rm = TRUE)'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Median': aggExpr = 'median(' + varName + ', na.rm = TRUE)'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'SD': aggExpr = 'sd(' + varName + ', na.rm = TRUE)'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Min': aggExpr = 'min(' + varName + ', na.rm = TRUE)'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Max': aggExpr = 'max(' + varName + ', na.rm = TRUE)'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Count Unique': aggExpr = 'n_distinct(' + varName + ')'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'NA Ratio': aggExpr = 'mean(is.na(' + varName + '))'; break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Variation Ratio':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  aggExpr = '1 - max(prop.table(table(' + varName + '[!is.na(' + varName + ')])))';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 'Entropy':
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  aggExpr = '(function(v){p<-prop.table(table(v[!is.na(v)]));-sum(p*log2(p))})(' + varName + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  default: aggExpr = slot.aggName + '(' + varName + ', na.rm = TRUE)';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // -------------------------------------------------

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var allGrp = rows.concat(cols);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var groupsStr = allGrp.map(rColName).join(', ');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var dotGroups = allGrp.length > 1 ? ', .groups = ' + dq('drop') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var rowExpr = rows.length === 1 ? rColName(rows[0]) : 'interaction(' + rows.map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var colExpr = cols.length === 1 ? rColName(cols[0]) : 'interaction(' + cols.map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var numFLines = getNumericFilterCode(lastCfg, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var catFLines = getCategoricalFilterCode(lastCfg, true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var filterSteps = numFLines.concat(catFLines).map(function(l){ return '  ' + l + ' |>\\n'; }).join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var binSteps = allBinMutateSteps();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var hasTransform = transformState.mode !== 'none' && rows.length > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var hasReorder   = reorderState.mode !== 'original' && rows.length > 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var transformStep = hasTransform ? '  ' + getReorderMutate(transformState.mode, rows[0], transformState.param) + ' |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var reorderStep   = hasReorder   ? '  ' + getReorderMutate(reorderState.mode,   rows[0], reorderState.param)  + ' |>\\n' : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var code = dfName + ' |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              filterSteps + binSteps + transformStep + reorderStep;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // 固定行和列的顺序（与 Table 视图一致）
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (rows.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                code += '  mutate(' + rows[0] + ' = fct_inorder(as.factor(' + rows[0] + '))) |>\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (cols.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                code += '  mutate(' + cols[0] + ' = fct_inorder(as.factor(' + cols[0] + '))) |>\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  group_by(' + groupsStr + ') |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              '  summarise(' + statN + ' = ' + aggExpr + dotGroups + ') |>\\n';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // 根据热图类型处理颜色范围
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (rendererName === 'Heatmap') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                '  mutate(fill_min = min(' + statN + ', na.rm = TRUE),\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '         fill_max = max(' + statN + ', na.rm = TRUE)) |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  ungroup() |>\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else if (rendererName === 'Row Heatmap') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var rg = rows.length === 1 ? rColName(rows[0]) : 'interaction(' + rows.map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  group_by(' + rg + ') |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '  mutate(' + statN + ' = (' + statN + ' - min(' + statN + ', na.rm = TRUE)) /\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '           (max(' + statN + ', na.rm = TRUE) - min(' + statN + ', na.rm = TRUE))) |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  ungroup() |>\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else if (rendererName === 'Col Heatmap') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var cg = cols.length === 1 ? rColName(cols[0]) : 'interaction(' + cols.map(rColName).join(', ') + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  group_by(' + cg + ') |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '  mutate(' + statN + ' = (' + statN + ' - min(' + statN + ', na.rm = TRUE)) /\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '           (max(' + statN + ', na.rm = TRUE) - min(' + statN + ', na.rm = TRUE))) |>\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  ungroup() |>\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var fillScale;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (rendererName === 'Heatmap') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fillScale = '  scale_fill_gradient(low = \"white\", high = \"red\",\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        '                     limits = c(unique(fill_min), unique(fill_max)),\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        '                     na.value = \"grey90\") +\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fillScale = '  scale_fill_gradient(low = \"white\", high = \"red\", limits = c(0, 1), na.value = \"grey90\") +\\n';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      code +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  ggplot(aes(x = ' + colExpr + ', y = ' + rowExpr + ', fill = ' + statN + ')) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  geom_tile(colour = \"white\", linewidth = 0.5) +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fillScale +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  labs(x = ' + dq(cols.join(' / ')) + ', y = ' + dq(rows.join(' / ')) + ', fill = ' + dq(statN) + ') +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme_minimal() +\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '  theme(axis.text.x = element_text(angle = 45, hjust = 1))';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return code;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function updateHeatmapCode() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var rn = $('#__UID__-renderer').find('select').val() || 'Table';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var isHeatmap = rn === 'Heatmap' || rn === 'Row Heatmap' || rn === 'Col Heatmap';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var $wrap = $('#__UID__-heatmap-wrap');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (isHeatmap) { $wrap.show(); $('#__UID__-heatmap-code').text(makeHeatmapGGCode(rn)); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      else { $wrap.hide(); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // -- Snapshot download helpers --------------------------------------------

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function pvTimestamp() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var d = new Date();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var pad = function(n) { return String(n).padStart(2, '0'); };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return d.getFullYear() +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pad(d.getMonth() + 1) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pad(d.getDate()) + '_' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pad(d.getHours()) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pad(d.getMinutes()) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pad(d.getSeconds());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function pvDownloadHtml(filename, html) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var blob = new Blob([html], { type: 'text/html;charset=utf-8' });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var url = URL.createObjectURL(blob);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var a = document.createElement('a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      a.href = url;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      a.download = filename;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      document.body.appendChild(a);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      a.click();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.body.removeChild(a);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          URL.revokeObjectURL(url);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function pvReplaceCanvasesWithImages(srcRoot, cloneRoot) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var srcCanvases = srcRoot.querySelectorAll('canvas');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var cloneCanvases = cloneRoot.querySelectorAll('canvas');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        srcCanvases.forEach(function(canvas, i) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!cloneCanvases[i]) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var img = document.createElement('img');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              img.src = canvas.toDataURL('image/png');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              img.style.maxWidth = '100%';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              img.style.height = 'auto';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              img.style.display = 'block';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cloneCanvases[i].replaceWith(img);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var msg = document.createElement('p');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              msg.textContent = 'Chart image could not be exported.';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              msg.style.color = '#c00';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              msg.style.fontSize = '12px';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cloneCanvases[i].replaceWith(msg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function pvInlineComputedStyles(srcNode, cloneNode) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!srcNode || !cloneNode) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (srcNode.nodeType === 1 && cloneNode.nodeType === 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var computed = window.getComputedStyle(srcNode);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var cssText = '';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (var i = 0; i < computed.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              var prop = computed[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cssText += prop + ':' + computed.getPropertyValue(prop) + ';';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cloneNode.setAttribute('style', cssText);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var srcChildren = srcNode.childNodes;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var cloneChildren = cloneNode.childNodes;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (var j = 0; j < srcChildren.length; j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pvInlineComputedStyles(srcChildren[j], cloneChildren[j]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function pvStripInteractivity(cloneRoot) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Static snapshot: remove scripts and external CSS dependency.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cloneRoot.querySelectorAll('script').forEach(function(el) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              el.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cloneRoot.querySelectorAll('link[rel=\"stylesheet\"]').forEach(function(el) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                el.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Keep current controls visible, but disable interaction.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cloneRoot.querySelectorAll('select, input, button, textarea').forEach(function(el) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  el.setAttribute('disabled', 'disabled');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  el.style.pointerEvents = 'none';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  el.style.opacity = '0.85';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Remove floating filter popups / draggable long-form popup if currently open.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cloneRoot.querySelectorAll('.pvtFilterBox, .pv-longform-popup').forEach(function(el) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    el.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function pvCollectInlineStyles() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var cssText = '';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $('style').each(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cssText += '\\n' + ($(this).html() || '');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cssText += '\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'body { font-family: Arial, sans-serif; margin: 24px; color: #222; background: white; }\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'h1 { font-size: 20px; margin: 0 0 14px; }\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'h2 { font-size: 16px; margin: 20px 0 8px; }\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '.pv-static-meta { font-size: 12px; color: #555; margin-bottom: 14px; }\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '.pv-static-section { margin-bottom: 20px; }\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '.pv-static-chart img { max-width: 100%; height: auto; display: block; }\\n' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '.pv-static-table-wrap { overflow-x: auto; }\\n';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return cssText;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function pvWrapStaticHtml(title, bodyHtml) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var cssText = pvCollectInlineStyles();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return '<!DOCTYPE html>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<html>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<head>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<meta charset=\"UTF-8\">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<title>' + title + '</title>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<style>' + cssText + '</style>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '</head>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<body>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    bodyHtml +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '</body>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '</html>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // -- 1. Interactive full-page snapshot -------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Keeps the full page interactive, but still depends on pivot_libs/.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function pvSaveInteractiveFullPageSnapshot() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    saveStateToHash();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var curHash = window.location.hash || '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var html = '<!DOCTYPE html>\\n' + document.documentElement.outerHTML;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    var bootScript =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<script>window.location.hash = ' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    JSON.stringify(curHash) +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ';</' + 'script>';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (/<head[^>]*>/i.test(html)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      html = html.replace(/<head([^>]*)>/i, '<head$1>' + bootScript);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      html = html.replace(/<html[^>]*>/i, function(m) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return m + bootScript;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pvDownloadHtml(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'pivot_interactive_full_snapshot_' + pvTimestamp() + '.html',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        html
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // -- 2. Static full-page snapshot ------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Saves the current whole page as static HTML; no pivot_libs/ needed.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function pvSaveStaticFullPageSnapshot() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      saveStateToHash();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var srcBody = document.body;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var cloneBody = srcBody.cloneNode(true);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Convert all Chart.js canvases to embedded PNG images.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pvReplaceCanvasesWithImages(srcBody, cloneBody);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Inline computed CSS so the output does not rely on external CSS files.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pvInlineComputedStyles(srcBody, cloneBody);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Remove JS/external CSS and disable controls.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pvStripInteractivity(cloneBody);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var meta =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<div style=\"font-family:Arial,sans-serif;font-size:12px;color:#555;margin:0 0 16px 0;\">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<b>PivotUI static full-page snapshot</b><br>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'Saved at: ' + new Date().toLocaleString() + '<br>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'This is a static snapshot. Interactive pivot controls are disabled.' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '</div>';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var html =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<!DOCTYPE html>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<html>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<head>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<meta charset=\"UTF-8\">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<title>PivotUI static full-page snapshot</title>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '</head>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '<body style=\"background:#222222;margin:0;padding:24px;\">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      meta +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cloneBody.innerHTML +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '</body>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      '</html>';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pvDownloadHtml(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'pivot_static_full_snapshot_' + pvTimestamp() + '.html',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        html
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // -- 3. Result-only snapshot ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Saves only the current result area: pivot table/chart or regression result.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function pvBuildPivotResultBody() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var rows = lastCfg && lastCfg.rows ? lastCfg.rows.join(', ') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var cols = lastCfg && lastCfg.cols ? lastCfg.cols.join(', ') : '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var slots = activeSlots().map(function(s) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return s.aggName === 'Count'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? 'Count'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : s.aggName + '(' + s.varName + ')';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }).join(', ');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $body = $('<div></div>');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $body.append('<h1>Pivot table result snapshot</h1>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $body.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div class=\"pv-static-meta\">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Rows:</b> ' + (rows || '(none)') + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Columns:</b> ' + (cols || '(none)') + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Statistics:</b> ' + (slots || '(none)') + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Saved at:</b> ' + new Date().toLocaleString() + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '</div>'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $table = $('#__UID__ .pvtTable').first();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ($table.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var $tableBlock = $('<div class=\"pv-static-section pv-static-table-wrap\"></div>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $tableBlock.append($table.clone(false, false));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append('<h2>Pivot table</h2>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append($tableBlock);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append('<p>No pivot table result found.</p>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $chartWrap = $('#__UID__-chart-wrap');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ($chartWrap.length && $chartWrap.is(':visible')) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var chartClone = $chartWrap[0].cloneNode(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          pvReplaceCanvasesWithImages($chartWrap[0], chartClone);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var $chartClone = $(chartClone);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // Remove controls from result-only snapshot.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $chartClone.find('.pv-chart-ctrl').remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $chartClone.find('.pv-yaxis-panel').remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $chartClone.find('input, select, button').remove();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append('<h2>Chart</h2>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $('<div class=\"pv-static-section pv-static-chart\"></div>').append($chartClone)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return $body.html();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function pvBuildRegressionResultBody() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var group = $('#__UID__-reg-group option:selected').text() || '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var xvar  = $('#__UID__-reg-x option:selected').text() || '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var yvar  = $('#__UID__-reg-y option:selected').text() || '';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $body = $('<div></div>');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $body.append('<h1>Regression result snapshot</h1>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $body.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div class=\"pv-static-meta\">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Group:</b> ' + (group || '(none)') + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>X:</b> ' + (xvar || '(none)') + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Y:</b> ' + (yvar || '(none)') + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '<div><b>Saved at:</b> ' + new Date().toLocaleString() + '</div>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          '</div>'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $regChart = $('#__UID__-reg-tab-chart');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ($regChart.length) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var regChartClone = $regChart[0].cloneNode(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          pvReplaceCanvasesWithImages($regChart[0], regChartClone);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append('<h2>Regression plot</h2>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $('<div class=\"pv-static-section pv-static-chart\"></div>').append($(regChartClone))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append('<p>No regression chart found.</p>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $info = $('#__UID__-reg-info-wrap');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if ($info.length && $.trim($info.text()).length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append('<h2>Regression summary</h2>');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $body.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $('<div class=\"pv-static-section\"></div>').append($info.clone(false, false))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return $body.html();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function pvSaveResultSnapshot() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var title;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var bodyHtml;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (activeTab === 'regression') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          title = 'Regression result snapshot';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          bodyHtml = pvBuildRegressionResultBody();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          title = 'Pivot table result snapshot';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          bodyHtml = pvBuildPivotResultBody();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pvDownloadHtml(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'pivot_result_snapshot_' + pvTimestamp() + '.html',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          pvWrapStaticHtml(title, bodyHtml)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // -- Snapshot button events -------------------------------------------------

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $('#__UID__-snapshot-interactive-full-btn').on('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var $btn = $(this);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            pvSaveInteractiveFullPageSnapshot();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $btn.text('Saved interactive').addClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $btn.text('Save interactive full page').removeClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }, 2000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error(e);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $btn.text('Interactive save failed').addClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $btn.text('Save interactive full page').removeClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $('#__UID__-snapshot-static-full-btn').on('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var $btn = $(this);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  pvSaveStaticFullPageSnapshot();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $btn.text('Saved static').addClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $btn.text('Save static full page').removeClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }, 2000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error(e);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $btn.text('Static save failed').addClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $btn.text('Save static full page').removeClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $('#__UID__-snapshot-result-btn').on('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      var $btn = $(this);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pvSaveResultSnapshot();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $btn.text('Saved result').addClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $btn.text('Save result snapshot').removeClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }, 2000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.error(e);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $btn.text('Result save failed').addClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setTimeout(function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $btn.text('Save result snapshot').removeClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-copy-state-url-btn').on('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var $btn = $(this);

