                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // -- Column-role tooltip --------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $(document).on('mouseenter', '#__UID__ .pvtAttr[data-pv-hint]', function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $('#__UID__-col-tip').text($(this).attr('data-pv-hint'))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .css({ left: e.pageX + 14, top: e.pageY - 8 }).show();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }).on('mouseleave', '#__UID__ .pvtAttr[data-pv-hint]', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $('#__UID__-col-tip').hide();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }).on('mousemove', '#__UID__ .pvtAttr[data-pv-hint]', function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $('#__UID__-col-tip').css({ left: e.pageX + 14, top: e.pageY - 8 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // -- Undo / redo buttons and keyboard shortcuts ---------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $('#__UID__-undo-btn').on('click', undoState);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $('#__UID__-redo-btn').on('click', redoState);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $(document).on('keydown.undoredo__UID__', function(e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!e.ctrlKey && !e.metaKey) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (e.key === 'z' || e.key === 'Z') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (e.shiftKey) { redoState(); } else { undoState(); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else if (e.key === 'y' || e.key === 'Y') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            redoState();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

