                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $('#__UID__-reg-gg-btn').on('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var code = $('#__UID__-reg-gg-code').text().trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var $btn = $(this);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!code || code.charAt(0) === '#') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $btn.text('No code yet').addClass('pv-btn-warn');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setTimeout(function(){$btn.text('\\u2398 Copy ggplot2 code').removeClass('pv-btn-warn');}, 2000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  navigator.clipboard.writeText('```{r}\\n' + code + '\\n```').then(function(){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $btn.text('\\u2713 Copied!').addClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setTimeout(function(){$btn.text('\\u2398 Copy ggplot2 code').removeClass('pv-btn-ok');}, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }).catch(function(){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $btn.text('\\u2718 Copy failed').addClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setTimeout(function(){$btn.text('\\u2398 Copy ggplot2 code').removeClass('pv-btn-err');}, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // -- Copy code chunk to clipboard ------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $('#__UID__-insert-btn').on('click', function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var code = $('#__FID__').text().trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        var $btn = $(this);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!code || code.charAt(0) === '#') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $btn.text('No code yet').addClass('pv-btn-warn');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setTimeout(function(){$btn.text('\\u2398 Copy code chunk').removeClass('pv-btn-warn');}, 2000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        navigator.clipboard.writeText('```{r}\\n' + code + '\\n```').then(function(){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            $btn.text('\\u2713 Copied!').addClass('pv-btn-ok');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setTimeout(function(){$btn.text('\\u2398 Copy code chunk').removeClass('pv-btn-ok');}, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }).catch(function(){
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $btn.text('\\u2718 Copy failed').addClass('pv-btn-err');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setTimeout(function(){$btn.text('\\u2398 Copy code chunk').removeClass('pv-btn-err');}, 2500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });"

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        rows_json <- if (is.null(rows)) "[]" else paste0('["', paste(rows, collapse = '","'), '"]')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cols_json <- if (is.null(cols)) "[]" else paste0('["', paste(cols, collapse = '","'), '"]')

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- js_tmpl
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace(    js, stringr::fixed("__DFNAME__"), df_name)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace_all(js, stringr::fixed("__UID__"),    uid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace_all(js, stringr::fixed("__WID__"),    wid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace_all(js, stringr::fixed("__LID__"),    lid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace_all(js, stringr::fixed("__FID__"),    fid)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace(    js, stringr::fixed("__ROWS__"),   rows_json)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace(    js, stringr::fixed("__COLS__"),   cols_json)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace(    js, stringr::fixed("__COL_ANNOTATIONS__"), col_annotations_json)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace(    js, stringr::fixed("__DATE_VARS__"),       date_vars_json)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js <- stringr::str_replace(    js, stringr::fixed("__CONVERTED_VARS__"),  converted_vars_json)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        js_data <- paste0("window['", uid, "pvdata']=", as.character(json), ";")

